// ==========================================
// ★ K 의 방 — C등급 직업 갈림길 · 보정
// ==========================================
//
//   C — 기괴 · 몬스터 사냥. 혼자서는 아무도 못 산다. 보정은 그 다섯을 한 몸으로 세운다.
//     북잡이 drummer · 전술가 tactician · 부여술사 enchanter (마력) · 분대장 squad (무력) · 진법가 formation (내공)

// ── 북잡이 ──────────────────────────────
kJob('drummer', 'C', [

{ at:'C', t:'어둠 — 벽 속의 박',
  x:`문을 지나자 바닥이 미지근하다.<br><br>
    벽에 손을 대 보니 울린다. 둥, 쉬고, 둥. 느리고 크다.<br>
    여기는 무언가의 안쪽이다. 북잡이 귀에는 그렇게 들린다.<br><br>
    일행 숨이 벌써 그 박에 끌려가고 있다. 다섯이 다 같이 느려진다. 너무 느리다.`,
  o:[
    { l:'① 제 박을 따로 세운다.', k:'fix', dc:14, wake:1,
      ok:`벽 박 둘 사이에 작은 박을 셋 넣었다. 톡, 톡, 톡.<br><br>큰 박에 끌려가던 숨이 작은 박에 걸렸다. 하나씩 제 빠르기로 돌아온다.<br>벽은 계속 둥 하고 울린다. 이쪽 북은 그 밑에서 따로 간다.<br><br>남의 박 속에서 제 박을 지킨 건 처음이다. 큰 소리를 이기려 하지 않았다. 사이에 끼워 넣었다. 손목이 그걸 기억했다.`,
      ng:`작은 박을 넣는데 손이 자꾸 벽 박을 따라간다.<br><br>둥, 쉬고, 둥. 이쪽 북도 둥, 쉬고, 둥.<br>일행 하나가 벽에 기대 눈을 감았다. 흔들어 깨우는 데 한참 걸렸다. 이쪽 가슴도 그 박으로 뛰고 있었다.`,
      win:{ exp:20, dream:2, mind:6 }, lose:{ mind:-9, spirit:-8 } },
    { l:'② 귀를 덮고 벽에서 떨어져 걷는다.', k:'steady', dc:13,
      ok:`다들 벽에서 한 걸음씩 떨어지게 했다. 이쪽은 귀를 반쯤 덮었다.<br><br>울림이 발바닥으로만 온다. 귀로 안 들으면 덜 끌린다.<br>가운데로만 걸었다. 다음 문까지 아무도 벽에 안 기댔다.`,
      ng:`가운데로 걷는데 바닥도 울린다.<br><br>귀를 덮어도 발로 들어온다. 무릎이 박에 맞춰 꺾인다.<br>한 사람이 주저앉았다. 둘이 부축해서 겨우 문을 넘었다.`,
      win:{ exp:14, spirit:5 }, lose:{ hp:-9, mind:-7 } }
  ] },

{ at:'C1', t:'도축장 — 갈고리 줄',
  x:`천장에 쇠줄이 돌고 있다. 줄에 갈고리가 매달려 지나간다. 철컥, 쉬고, 철컥.<br><br>
    갈고리마다 고기가 걸려 있다. 몇 개는 비었다. 빈 갈고리는 조금 낮게 지나간다.<br>
    쇠가 쇠를 치는 소리에도 박이 있다. 세어 보면 아홉 박에 하나씩이다.<br><br>
    빈 갈고리가 지나갈 때마다 끝이 살짝 돈다. 사람 쪽으로.`,
  o:[
    { l:'① 아홉 박을 짚어 하나씩 건너게 한다.', k:'fix', dc:14,
      ok:`북 테를 가볍게 쳤다. 하나, 둘, 셋, 아홉까지.<br><br>아홉에 갈고리가 지나가고 하나에 한 사람이 뛰었다. 다섯 번.<br>마지막이 이쪽이다. 등 뒤로 쇠 끝이 바람을 갈랐다.<br><br>건너와서 보니 빈 갈고리 하나가 멈춰 있다. 이쪽을 향해 돌아선 채로.`,
      ng:`일곱에서 줄이 빨라졌다. 박이 줄었다.<br><br>셋째 사람이 늦었다. 빈 갈고리가 어깨 옷을 꿰고 지나갔다. 옷이 찢어지며 살갗도 같이 찢겼다.<br>줄은 다시 아홉 박으로 돌아갔다. 일부러 그런 것 같다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 엇박을 쳐서 줄을 헛돌게 한다.', k:'break', dc:15,
      doom:{ title:'박을 배운 갈고리', what:'갈고리에 걸려 끌려갑니다', dc:15, sec:60,
        text:`엇박을 쳤다. 둥, 둥둥, 쉼.<br><br>줄이 덜컥거렸다. 갈고리들이 엉킨다. 됐다 싶었다.<br>다음 박에 줄이 이쪽 엇박을 따라 했다. 둥, 둥둥, 쉼. 빈 갈고리가 쉼에 내려왔다.<br><br>허리띠에 걸렸다. 발이 들린다. 줄이 이쪽을 싣고 안쪽으로 간다.`,
        dieText:`줄은 아홉 박으로 돈다. 다만 이제 가끔 엇박이 섞인다.<br><br>둥, 둥둥, 쉼. 고기가 걸린 갈고리 사이로 북 하나가 매달려 지나간다.<br>칠 사람이 없어도 줄이 흔들릴 때마다 운다.` },
      ok:`엇박을 쳤다. 둥, 둥둥, 쉼.<br><br>줄이 덜컥거렸다. 갈고리들이 서로 부딪혀 엉켰다. 줄이 멎었다.<br>엉킨 사이로 다섯이 다 건넜다.<br><br>건너편에서 다시 철컥 소리가 났다. 이번엔 엇박이다. 줄이 배웠다. 다시 오면 안 통한다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'C1', t:'도축장 — 다시 붙는 고기',
  x:`도마 위에 고깃덩이가 있다. 반으로 갈려 있다.<br><br>
    갈린 자리가 서로를 찾는다. 실 같은 것이 뻗어 이어진다. 숨 열 번이면 붙는다.<br>
    도마 밑에서 그것의 다리가 나왔다. 넷이다. 사람 다리 둘, 짐승 다리 둘.<br><br>
    일행이 칼을 쥐고 둘러쌌다. 칼질이 제각각이다. 하나가 자르는 동안 다른 데가 붙는다.`,
  o:[
    { l:'① 내려칠 박을 하나로 모은다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"둥에 다 같이."</span><br><br>북을 크게 한 번 쳤다. 칼 넷이 한꺼번에 내려갔다. 네 군데가 동시에 갈렸다.<br>실이 뻗는다. 찾을 짝이 너무 많다. 실끼리 엉켰다. 둥. 또 한꺼번에.<br><br>세 번째 둥에 그것이 멈췄다. 넷의 팔이 한 팔처럼 움직였다. 박은 귀로 들어가는 게 아니라 팔로 들어간다. 이번에 손으로 알았다. 북채가 남의 어깨까지 닿았다.`,
      ng:`둥에 다 같이 라고 했는데 둘은 둥 전에, 하나는 둥 뒤에 쳤다.<br><br>세 번의 칼질이 세 번의 틈이 됐다. 틈마다 실이 이었다.<br>그것의 짐승 다리가 이쪽 정강이를 찼다. 뼈가 울렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 붙는 데 걸리는 숨을 센다.', k:'sense', dc:14,
      ok:`칼질을 멈추게 하고 셌다. 숨 열 번. 다시 갈랐을 때도 열 번. 큰 덩이일수록 느리다.<br><br>제일 큰 덩이부터 갈고 작은 것은 나중에 했다. 큰 것이 붙는 동안 작은 것을 끝냈다.<br>셈이 칼보다 빨랐다.`,
      ng:`세는 동안 그것이 가만있지 않았다.<br><br>네 다리로 도마에서 뛰어내렸다. 세던 이쪽 쪽으로.<br>북으로 막았다. 테가 우그러졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-13, mind:-5 } },
    { l:'③ 북채로 다리 이음매를 친다.', k:'break', dc:14,
      ok:`사람 다리와 짐승 다리가 붙은 자리가 있다. 거기만 색이 다르다.<br><br>북채 끝으로 그 자리를 세게 쳤다. 이음매가 벌어졌다. 짐승 다리 하나가 떨어져 나갔다.<br>떨어진 다리는 다시 붙지 않았다. 짝이 아니었던 것이다.<br><br>그 다리는 챙겼다. 짐승 고기다. 아마 괜찮을 것이다.`,
      ng:`치는데 북채가 살에 박혔다.<br><br>빼려는데 살이 채를 감싼다. 붙는 쪽으로 끌어당긴다.<br>채를 놓았다. 채 하나가 그것의 일부가 됐다.`,
      win:{ exp:18, dream:1, item:'짐승 고기' }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C2', t:'인형 공방 — 딸깍거리는 이',
  x:`선반마다 사기 인형이 앉아 있다. 하얀 얼굴, 빨간 입술.<br><br>
    입술 사이로 이가 보인다. 진짜 이다. 사람 이처럼 누렇다.<br>
    인형들이 이를 부딪친다. 딸깍, 딸깍. 한 줄씩 차례로. 왼쪽 선반에서 오른쪽 선반으로.<br><br>
    세는 소리다. 마지막 선반이 딸깍하면 셈이 끝난다. 셈이 끝나면 무엇이 오는지는 모른다.`,
  o:[
    { l:'① 딸깍 뒤에 박을 이어 붙인다.', k:'fix', dc:14,
      ok:`마지막 선반 차례가 오기 직전에 북 테를 쳤다. 딸깍과 똑같이.<br><br>인형들이 멈칫했다. 셈이 하나 늘었다. 다시 처음부터 센다.<br>셈이 도는 동안 다섯이 공방을 가로질렀다. 끝날 때마다 이쪽이 하나를 보탰다.<br><br>문을 닫을 때까지 인형들은 끝을 못 냈다. 끝이 없는 셈은 아무것도 부르지 못한다.`,
      ng:`테를 치는 순간이 반 박 늦었다.<br><br>마지막 선반이 딸깍했다. 그리고 조용해졌다. 인형 서른 개가 동시에 고개를 이쪽으로 돌렸다.<br>뛰었다. 등 뒤로 사기 깨지는 소리와 이 부딪치는 소리가 쫓아왔다. 종아리에 작은 이빨 자국이 줄지어 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-13, spirit:-7 } },
    { l:'② 북을 품고 작업대 밑에 숨는다.', k:'hide', dc:14,
      ok:`북을 품에 넣고 작업대 밑으로 들어갔다. 다들 따라 엎드렸다.<br><br>마지막 선반이 딸깍했다. 인형들이 고개를 돌렸다. 아무도 안 보인다.<br>한참 뒤 다시 처음부터 세기 시작했다. 그 틈에 기어서 나왔다.<br><br>북을 안 친 덕에 아무도 안 들켰다. 쉼표도 박이다.`,
      ng:`작업대 밑에 먼저 와 있는 것이 있었다.<br><br>목 없는 인형 몸통이다. 이쪽 소매를 잡았다. 사기 손가락이 차다.<br>뿌리치다 작업대에 머리를 박았다. 소리가 났다. 다들 뛰어야 했다.`,
      win:{ exp:15, spirit:5 }, lose:{ hp:-9, spirit:-9 } }
  ] },

{ at:'C2', t:'인형 공방 — 줄이 끄는 팔',
  x:`천장에서 실이 내려온다. 가늘고 많다. 거미줄보다 질기다.<br><br>
    일행 하나가 실에 손목이 걸렸다. 걸린 팔이 저 혼자 올라간다. 칼을 쥔 팔이다.<br>
    팔이 박자를 탄다. 위층 어딘가에서 누가 줄을 당기는 박자다. 느리게 들었다가 빠르게 내린다.<br><br>
    칼끝이 옆 사람 목 쪽으로 내려오고 있다.`,
  o:[
    { l:'① 그 팔이 따를 박을 준다.', k:'fix', dc:15, wake:1,
      ok:`위층 박보다 한 박 빠르게 쳤다. 둥, 둥. 걸린 사람 귀에 대고.<br><br>팔이 망설였다. 실이 당기는 박과 북 박 사이에서. 사람 몸은 실보다 북을 먼저 안다. 오래전부터 그랬다.<br>칼끝이 북 박을 따라 바닥으로 내려갔다. 그 틈에 다른 일행이 실을 끊었다.<br><br>걸렸던 사람이 제 손목을 주무른다. 이쪽 손목도 저리다. 남의 팔을 박으로 붙잡고 있었다. 이쪽 박이 남의 몸 안에서 줄 노릇을 했다.`,
      ng:`한 박 빠르게 쳤는데 위층이 더 빨라졌다.<br><br>두 박이 다투는 사이 팔이 경련하듯 떨었다. 칼끝이 옆 사람 귓바퀴를 스쳤다. 피가 났다.<br>실은 끝내 이쪽이 이로 끊었다. 입술이 베였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, spirit:-9 } },
    { l:'② 걸린 손목을 잡아 누른다.', k:'bond', dc:14,
      ok:`걸린 사람 손목을 두 손으로 잡아 아래로 눌렀다.<br><br>실이 당긴다. 이쪽도 당긴다. 그 사람이 이쪽 눈을 보고 숨을 맞췄다.<br>다른 일행이 실을 끊을 때까지 놓지 않았다. 손바닥에 실 자국이 파였다.`,
      ng:`누르는데 실이 하나 더 내려와 이쪽 손목에 감겼다.<br><br>이제 둘이 매달린 꼴이다. 두 팔이 같은 박으로 올라간다.<br>다른 일행이 다 끊어 줄 때까지 한참을 버둥댔다.`,
      win:{ exp:16, spirit:5 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 떨리는 칼끝',
  x:`짐승 하나를 잡고 쉬는 자리에 모였다. 다들 손이 떨린다.<br><br>
    칼을 쥐었던 손은 놓고 나서도 한참 떤다. 무서워서가 아니다. 너무 세게 쥐어서다.<br>
    치료하는 사람이 붕대를 감는데 그 손도 떤다.<br><br>
    떨림도 박이다. 빠르고 잘고, 제각각인 박.`,
  o:[
    { l:'① 아주 느린 박을 깐다.', k:'fix', dc:14,
      ok:`북을 무릎에 놓고 손바닥으로 쓸듯 쳤다. 둥. 길게 쉬고. 둥.<br><br>떨림이 그 사이로 빠져나간다. 칼 쥐었던 손이 하나씩 펴졌다. 붕대가 반듯하게 감겼다.<br>이쪽 손도 같이 펴졌다. 치면서 쉬었다.`,
      ng:`느리게 친다고 쳤는데 이쪽 손도 떨고 있었다.<br><br>떨리는 손으로 친 박은 떨린다. 다들 그 떨림을 받아 갔다.<br>붕대가 두 번 풀렸다.`,
      win:{ exp:16, mind:7 }, lose:{ mind:-8, spirit:-6 } },
    { l:'② 북 가죽부터 살핀다.', k:'steady', dc:13,
      ok:`북을 뒤집어 가죽을 봤다. 짐승 피가 튀어 말라붙었다.<br><br>마른 피는 소리를 죽인다. 물 한 모금으로 불려 손톱으로 긁어냈다.<br>쳐 보니 맑다. 다음 사냥에 쓸 소리다.<br><br>북을 먼저 돌보는 사람 옆에서 다들 제 칼을 닦기 시작했다.`,
      ng:`긁는데 피가 아니었다.<br><br>가죽에 붙은 것이 꿈틀했다. 짐승 몸에서 튄 무언가다. 아직 산다.<br>북을 털어 밟았다. 가죽에 구멍이 하나 났다.`,
      win:{ exp:13, dream:1, spirit:5 }, lose:{ hp:-8, spirit:-8 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 종 속의 것',
  x:`성당이 거꾸로 서 있다. 발밑이 둥근 천장이다. 머리 위로 신도석과 제단이 매달려 있다.<br><br>
    천장 갈빗대 사이에 종이 놓여 있다. 입을 위로 벌리고. 종 안이 젖은 소리를 낸다.<br>
    종 안에는 추 대신 무언가 들어 있다. 숨을 쉰다. 소리가 나면 그쪽으로 기운다.<br><br>
    종을 보면 칠 박부터 생각하는 버릇이 있다. 이번에는 안 칠 박을 생각해야 한다.`,
  o:[
    { l:'① 박을 종 반대편으로 던진다.', k:'fix', dc:14,
      ok:`멀리 갈빗대 하나를 겨눠 북채를 던졌다. 딱. 다른 손으로 북을 덮었다.<br><br>종 안의 것이 그쪽으로 기울었다. 종이 땅땅 울며 굴러갔다. 소리를 쫓아서.<br>그 반대편으로 다섯이 걸었다. 아무도 숨소리를 크게 내지 않았다.<br><br>채 하나는 거기 두고 왔다. 박 하나를 미끼로 썼다.`,
      ng:`던진 채가 갈빗대에 맞고 튀어 돌아왔다. 이쪽 발밑으로.<br><br>딱. 종이 이쪽으로 기울었다. 종 입에서 젖은 것이 혀처럼 나왔다.<br>뒷걸음질하다 갈빗대 사이 홈에 발이 빠졌다. 발목이 꺾였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 종 안을 들여다본다.', k:'gaze', dc:15,
      doom:{ title:'젖은 종', what:'종 속으로 빨려 들어갑니다', dc:15, sec:55,
        text:`종 테두리를 짚고 안을 들여다봤다.<br><br>안은 생각보다 깊다. 종이 아니라 목구멍이다. 벽에 주름이 있다. 주름이 박자를 탄다.<br>숨이 그 박자를 따라갔다. 들이쉬고, 또 들이쉬고.<br><br>몸이 앞으로 쏠린다. 테두리를 짚은 손이 미끄러진다. 종이 이쪽을 삼키며 울기 시작했다.`,
        dieText:`종이 한 번 울렸다. 둥.<br><br>북소리와 아주 비슷했다. 일행 몇이 저도 모르게 그 박에 발을 맞췄다.<br>거꾸로 선 성당에서 그 종은 이제 박을 맞춰 운다. 아무도 치지 않는데.` },
      ok:`테두리를 짚고 안을 봤다. 안은 종이 아니라 목구멍이다. 주름이 박자를 탄다.<br><br>숨이 그 박에 끌려가려 했다. 이를 악물고 제 박으로 셌다. 넷 들이쉬고 넷 내쉬고.<br>주름 끝에 누런 덩이가 보였다. 심장이다. 종을 울리는 건 그것이다.<br><br>일행 하나가 창을 넣어 찔렀다. 종이 한 번 낮게 울고 조용해졌다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 입 많은 성가대',
  x:`매달린 성가대석에서 노래가 내려온다.<br><br>
    성가대원은 열둘. 입은 그보다 훨씬 많다. 목에도, 손바닥에도, 옷자락 안에도.<br>
    노래가 느리다. 한 소절에 숨 한 번. 일행 숨이 그 소절에 맞춰진다. 하나가 따라 흥얼거리기 시작했다.<br><br>
    흥얼거리는 사람 턱 밑에서 살이 갈라지려 한다. 입이 하나 더 생기려 한다.`,
  o:[
    { l:'① 노래 밑에 박을 깐다.', k:'fix', dc:15, wake:1,
      ok:`소절 사이마다 짧은 박을 둘씩 넣었다. 둥둥. 노래가 숨 쉬는 자리에.<br><br>노래는 숨을 쉬지 못하게 됐다. 쉴 자리에 북이 있다. 소절이 길어지고, 흐트러지고, 끊겼다.<br>흥얼거리던 사람이 입을 다물었다. 턱 밑 갈라짐이 도로 닫혔다.<br><br>성가대 입들이 다 이쪽을 향했다. 계속 쳤다. 노래를 깨려고 친 게 아니다. 노래 사이를 이쪽 것으로 채웠다. 남의 박 사이가 이쪽 자리라는 걸 이제 손이 안다.`,
      ng:`둥둥을 넣는데 성가대가 그 박을 노래에 넣어 버렸다.<br><br>노래가 이쪽 박까지 먹고 더 커졌다. 둘째 사람이 흥얼거린다.<br>둘을 끌고 성가대석 밑을 벗어났다. 한 사람 턱 밑에 작은 흉이 남았다. 입 모양이다.`,
      win:{ exp:24, dream:3, spirit:6 }, lose:{ mind:-10, spirit:-12 } },
    { l:'② 흥얼거리는 사람 입을 막고 지나간다.', k:'steady', dc:14,
      ok:`흥얼거리는 사람 입을 손바닥으로 막았다. 다른 손으로 제 귀를 막았다.<br><br>둘이 한 몸처럼 성가대석 밑을 지났다. 손바닥 밑에서 그 사람 입술이 계속 노래를 지었다.<br>벗어나고서야 그 사람이 손바닥을 문 걸 알았다. 이쪽 손에 자국이 났다. 그쪽은 모른다.`,
      ng:`막은 손바닥 밑에서 노래가 새어 나왔다.<br><br>귀를 막은 손도 소용없다. 노래는 뼈로 들어온다.<br>밑을 벗어날 때 이쪽도 흥얼거리고 있었다. 일행이 뺨을 쳐서 멈췄다.`,
      win:{ exp:16, mind:5 }, lose:{ mind:-9, spirit:-10 } },
    { l:'③ 북을 세게 쳐서 성가대석을 흔든다.', k:'break', dc:15,
      ok:`북을 머리 위로 들고 힘껏 쳤다. 둥—<br><br>매달린 성가대석이 흔들렸다. 낡은 사슬 하나가 끊어졌다. 대원 셋이 떨어져 발밑 둥근 천장에 처박혔다. 갈빗대 사이에서 입들이 한참 벙긋거렸다.<br>노래가 반으로 줄었다. 반 노래는 숨을 못 잡는다.`,
      ng:`힘껏 쳤는데 사슬이 안 끊어졌다.<br><br>성가대 입들이 일제히 이쪽 박을 따라 했다. 둥— 열두 사람 몫의 둥이다.<br>귀에서 피가 났다. 한동안 아무 소리도 안 들렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C4', t:'포자 온실 — 부푸는 주머니',
  x:`온실 유리가 뿌옇다. 안쪽에 곰팡이가 두껍게 앉았다.<br><br>
    화단마다 버섯 주머니가 솟아 있다. 사람 머리만 하다. 부풀었다가 꺼진다. 꺼질 때 노란 가루가 피어오른다.<br>
    숨이다. 숨에는 박이 있다. 주머니마다 다르다.<br><br>
    통로는 주머니 사이로 하나뿐이다.`,
  o:[
    { l:'① 꺼지는 박 사이를 짚어 건넌다.', k:'fix', dc:14,
      ok:`주머니 셋의 박을 셌다. 일곱, 다섯, 아홉. 셋이 한꺼번에 부풀어 있는 때가 있다.<br><br>그때를 기다려 북을 쳤다. 다섯이 숨을 참고 뛰었다. 뒤에서 셋이 동시에 꺼졌다. 노란 가루가 빈 통로를 덮었다.<br>아무도 들이마시지 않았다.<br><br>박 셋을 겹쳐 셌다. 하나를 세는 것보다 어렵다. 겹친 박 속에 빈자리가 있다.`,
      ng:`겹친 박을 세는데 하나가 박을 바꿨다. 다섯에서 넷으로.<br><br>통로 한가운데서 셋이 꺼졌다. 노란 가루가 얼굴을 덮었다.<br>기침이 멈추지 않는다. 혀에 무언가 자라는 맛이 난다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-10, spirit:-10 } },
    { l:'② 숨 참는 박을 친다.', k:'steady', dc:14,
      ok:`둥에 들이쉬고, 둥 넷 동안 참는다. 그렇게 정했다.<br><br>주머니가 꺼질 때마다 참는 박이 걸리게 했다. 맞을 때도 있고 아닐 때도 있었다.<br>건너와서 둘이 기침했다. 오래가지는 않았다.`,
      ng:`참는 박을 넷으로 잡았는데 다들 셋째에서 숨이 찼다.<br><br>여기 공기는 무겁다. 숨이 짧아진다.<br>셋이 동시에 들이켰다. 가루가 같이 들어갔다. 밤새 목에서 실 같은 것을 뱉었다.`,
      win:{ exp:14, mind:5 }, lose:{ hp:-11, mind:-7 } }
  ] },

{ at:'C4', t:'포자 온실 — 정원사의 걸음',
  x:`화단 사이로 정원사가 걷는다. 앞치마, 장화, 챙 넓은 모자.<br><br>
    얼굴이 없다. 모자 밑이 하얀 실로 차 있다. 곰팡이가 사람 옷을 입고 걷는다.<br>
    걸음이 이상하다. 한 걸음에 소리가 둘 난다. 철벅, 그리고 조금 늦게 사각.<br><br>
    장화가 내는 소리와 그 안의 것이 내는 소리다. 둘이 반 박 어긋나 있다.`,
  o:[
    { l:'① 어긋난 반 박에 치게 한다.', k:'fix', dc:15, wake:1,
      ok:`철벅과 사각 사이를 짚었다. 그 반 박에 북을 쳤다. 다들 거기 맞춰 들어갔다.<br><br>옷과 곰팡이가 따로 노는 반 박이다. 그때 치면 몸이 받아 내지 못한다. 칼이 옷을 지나 실 덩이까지 한 번에 들어갔다.<br>정원사가 무너졌다. 앞치마 안에서 실이 한참 꿈틀대다 멎었다.<br><br>상대의 박을 쪼개 그 틈을 남의 손에 쥐여 줬다. 지금까지는 이쪽 박을 나눠 줬다. 오늘은 저쪽 박을 나눠 줬다.`,
      ng:`반 박을 짚었는데 정원사가 걸음을 멈췄다. 철벅도 사각도 없다.<br><br>박이 없는 것은 칠 데가 없다. 다들 허공을 쳤다.<br>정원사가 모자를 들어 올렸다. 하얀 실이 쏟아져 나와 가까운 사람 팔을 감았다. 떼어 내느라 살갗이 같이 벗겨졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 철벅 소리에 발을 맞춰 숨어 지난다.', k:'hide', dc:14,
      ok:`정원사 철벅에 맞춰 발을 디뎠다. 다섯이 같은 박으로.<br><br>정원사 귀에는 제 발소리만 들린다. 화단 뒤를 돌아 지나갔다.<br>사각 소리가 바로 옆을 지날 때 다들 숨을 멈췄다.`,
      ng:`철벅에 맞추는데 하나가 사각에 맞췄다.<br><br>정원사가 섰다. 모자가 이쪽으로 돌았다. 모자 밑에서 실이 바람도 없이 흔들린다.<br>뛰었다. 장화 소리가 화단 둘을 넘어 쫓아왔다.`,
      win:{ exp:16, spirit:5 }, lose:{ hp:-10, spirit:-9 } },
    { l:'③ 사각 소리가 나는 자리를 찾는다.', k:'sense', dc:14,
      ok:`사각 소리만 따로 들었다. 등에서 난다. 허리 위, 왼쪽.<br><br>옷 밑에 덩이가 있다. 거기서 실이 온몸으로 뻗는다. 일행에게 그 자리를 손으로 짚어 보였다.<br>창 하나가 등을 꿰뚫었다. 정원사가 장화째 주저앉았다.<br><br>앞치마 주머니에 산나물이 한 줌 들어 있다. 진짜 정원사가 뜯어 둔 것이다.`,
      ng:`사각 소리를 쫓다 보니 소리가 여럿이다.<br><br>화단 흙 밑에서도 사각, 사각. 발밑이다.<br>발목에 실이 감겼다. 장화를 벗고서야 빠져나왔다.`,
      win:{ exp:18, dream:2, item:'산나물' }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C', t:'사냥 — 다섯 숨, 한 짐승',
  x:`굴 끝에서 그것이 나왔다. 말만 하다. 가죽이 없다. 드러난 살이 젖어서 번들거린다.<br><br>
    다리가 몇 개인지 셀 수가 없다. 움직일 때마다 다르다.<br>
    일행이 둘러쌌다. 다섯이 다섯 박으로 숨을 쉰다. 그것은 그중 제일 빠른 숨을 고른다.<br><br>
    제일 빠른 숨은 맨 왼쪽, 창 든 사람이다.`,
  o:[
    { l:'① 사냥 박을 깐다.', k:'fix', dc:15, wake:1,
      ok:`북을 허리에 붙이고 박을 깔았다. 둥, 둥, 둥둥. 들이고, 들이고, 친다.<br><br>창 든 사람 숨이 그 박에 들어왔다. 다른 넷도. 다섯 숨이 한 박이 되자 그것이 머뭇거렸다. 고를 숨이 없다.<br>둥둥에 다섯이 한꺼번에 들어갔다. 세 번 만에 그것이 주저앉았다.<br><br>치는 내내 이쪽 팔이 다섯 개인 것 같았다. 이쪽은 힘을 주지 않았다. 힘이 날 자리를 줬다. 박이 듣는 사람 몸에서 힘으로 바뀌는 게 처음으로 손끝에 느껴졌다.`,
      ng:`박을 깔기 전에 그것이 먼저 움직였다.<br><br>창 든 사람에게 뛰어들었다. 창이 빗나갔다. 다들 제각각 뛰어들었다. 박이 없는 칼질은 서로를 막는다.<br>이쪽 어깨에 그것의 다리 하나가 내리꽂혔다.`,
      win:{ exp:25, dream:3, mind:6 }, lose:{ hp:-17, mind:-6 } },
    { l:'② 그것의 숨 박을 깬다.', k:'break', dc:15,
      ok:`그것의 숨을 들었다. 길게 들이쉬고 짧게 세 번 내쉰다.<br><br>들이쉬는 한가운데에 북을 세게 쳤다. 그것이 사레들린 듯 몸을 떨었다. 숨이 꼬였다.<br>꼬인 틈에 창이 들어갔다.`,
      ng:`세게 쳤는데 그것이 숨을 멈췄다. 박을 들은 것이다.<br><br>그리고 이쪽으로 돌아섰다. 북 치는 쪽이 제일 시끄럽다.<br>북을 방패 삼아 막았다. 가죽이 찢어졌다. 팔도.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 멈추지 않는 칼질',
  x:`작업장 안쪽에서 칼질 소리가 난다. 탕, 탕, 탕. 한 번도 안 쉰다.<br><br>
    앞치마를 두른 큰 것이 서 있다. 팔이 넷이다. 둘은 칼을 들고 둘은 고기를 민다. 고기가 잘리면 줄이 한 칸 간다.<br>
    줄이 돌면 도축장 고기가 자란다. 저 칼질이 이 도축장의 박이다.<br><br>
    그 박이 멈추면 무슨 일이 생기는지 아무도 모른다. 멈춰야 한다.`,
  o:[
    { l:'① 칼질 박을 조금씩 늦춘다.', k:'fix', dc:15,
      ok:`칼질에 맞춰 북을 쳤다. 탕에 둥. 똑같이. 세 번 맞추자 그것의 어깨가 북을 듣기 시작했다.<br><br>그다음부터 조금씩 늦췄다. 그것의 칼이 따라 늦어진다. 박은 맞추는 쪽이 끌려간다. 이번에는 저쪽이 맞췄다.<br>칼질 사이가 숨 다섯 번이 됐을 때 일행이 칼 든 팔 둘을 동시에 잘랐다.<br><br>줄이 멎었다. 도축장 전체가 한 번 크게 떨었다.`,
      ng:`맞추는 동안 이쪽이 끌려갔다. 탕에 둥, 탕에 둥. 늦출 수가 없다.<br><br>손이 저 혼자 칼질 박을 친다. 멈추려 해도 손이 안 멈춘다.<br>일행이 북채를 빼앗고서야 멈췄다. 손목이 퉁퉁 부었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, mind:-10 } },
    { l:'② 칼질 사이를 센다.', k:'sense', dc:14,
      ok:`탕과 탕 사이를 셌다. 똑같은 줄 알았는데 일곱 번째마다 한 번 길다. 칼을 가는 박이다.<br><br>일곱 번째를 기다려 일행을 들여보냈다. 칼을 갈 때 그것은 앞을 안 본다.<br>창 셋이 앞치마 밑을 꿰뚫었다.`,
      ng:`세는데 그것이 일곱 번째를 건너뛰었다.<br><br>칼을 갈지 않고 그대로 휘둘렀다. 들어가던 일행 하나가 팔을 베였다.<br>끌고 나왔다. 피가 많이 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 줄 돌리는 바퀴에 북채를 끼운다.', k:'break', dc:15,
      ok:`벽에 큰 나무 바퀴가 돈다. 줄을 돌리는 바퀴다.<br><br>바퀴살 사이에 북채를 쑤셔 넣었다. 우드득. 바퀴가 섰다. 줄이 섰다.<br>그것이 칼질을 멈추고 바퀴 쪽을 봤다. 그 사이 일행이 뒤에서 덮쳤다.<br><br>북채 하나가 부러졌다. 박 하나를 바퀴에 박아 넣은 셈이다.`,
      ng:`끼우는데 바퀴가 북채째 이쪽 손을 끌어당겼다.<br><br>팔이 바퀴살 사이로 들어갈 뻔했다. 소매가 찢겨 들어갔다.<br>바퀴는 계속 돈다. 소매 한쪽이 줄에 걸려 갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-5 } }
  ] },

{ at:'C2', t:'인형 공방 — 북 치는 인형',
  x:`작업대 위에 북 치는 인형이 있다. 태엽이 등에 꽂혀 있다.<br><br>
    인형이 작은 북을 친다. 똑, 똑, 똑. 그 박에 맞춰 공방 인형들이 고개를 까딱인다. 하나씩 일어선다.<br>
    태엽은 아무도 안 감았다. 그래도 돈다.<br><br>
    박을 쥔 쪽이 판을 쥔다. 지금 판은 저 인형 것이다.`,
  o:[
    { l:'① 박을 빼앗아 온다.', k:'fix', dc:15, wake:1,
      ok:`인형 박에 맞춰 이쪽 북을 쳤다. 똑에 둥. 그다음엔 똑보다 먼저 둥.<br><br>인형들이 헷갈렸다. 작은 박과 큰 박. 큰 박 쪽으로 고개가 돌았다. 그다음부터는 이쪽 박에 까딱인다.<br>박을 천천히 늦췄다. 일어서던 인형들이 하나씩 도로 앉았다. 눈꺼풀이 내려갔다.<br><br>북 치는 인형이 혼자 똑, 똑 친다. 아무도 안 따른다. 남의 판을 이쪽 판으로 바꿨다. 크게 쳐서가 아니다. 먼저 쳐서다. 손이 이제 남의 박보다 반 박 앞에 서는 법을 안다.`,
      ng:`둥을 먼저 치려는데 인형이 박을 바꿨다. 똑똑, 똑.<br><br>인형들이 그 박에 다 일어섰다. 일어선 인형들이 이를 딸깍이며 다가온다.<br>문까지 뛰었다. 손등을 셋이나 물렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 북 치는 인형을 부순다.', k:'break', dc:14,
      ok:`망치를 집어 인형 북을 내리쳤다. 작은 북이 깨졌다.<br><br>박이 끊겼다. 일어서던 인형들이 그 자세로 굳었다. 반쯤 일어선 채로.<br>그 사이를 조심조심 지나갔다.<br><br>북 치는 사람이 북을 깼다. 기분이 이상했다.`,
      ng:`망치가 인형 머리에 맞았다. 사기가 깨지며 안에서 이가 쏟아졌다.<br><br>수십 개다. 사람 이다. 바닥에 흩어진 이들이 저희끼리 딸깍인다.<br>그 박에 인형들이 다 일어섰다. 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-11, spirit:-10 } }
  ] },

{ at:'C', t:'어둠 — 따라 치는 소리',
  x:`북을 치면 어둠 저편에서 대답이 온다.<br><br>
    처음엔 메아리인 줄 알았다. 둥에 둥. 그런데 점점 빨리 온다. 이쪽이 치기도 전에.<br>
    무언가 박을 배우고 있다. 배운 박으로 이쪽을 부르려는 것 같다.<br><br>
    일행 하나가 그쪽으로 한 걸음 갔다. 이쪽 북인 줄 알고.`,
  o:[
    { l:'① 일부러 틀린 박을 친다.', k:'fix', dc:15,
      ok:`다섯이 미리 정해 둔 박이 있다. 둥, 쉼, 둥둥. 그걸 일부러 틀리게 쳤다. 둥둥, 쉼, 둥.<br><br>저편이 그대로 따라 쳤다. 틀린 박을.<br>일행이 멈췄다. 우리 박이 아니라는 걸 알았다. 저편은 틀린 줄도 모르고 계속 따라 친다.<br><br>흉내는 틀린 것까지 흉내 낸다. 그래서 들킨다.`,
      ng:`틀린 박을 쳤는데 저편이 맞는 박으로 쳤다. 둥, 쉼, 둥둥.<br><br>저쪽이 이쪽 약속까지 안다. 한 걸음 간 사람이 두 걸음째를 디뎠다.<br>허리를 잡아 끌어냈다. 그 사람 귀에서 한참 둥 소리가 났다고 한다.`,
      win:{ exp:20, dream:2, spirit:6 }, lose:{ mind:-8, spirit:-12 } },
    { l:'② 북을 덮고 박을 끊는다.', k:'hide', dc:14,
      ok:`북을 품에 넣고 손을 들어 다들 멈추게 했다.<br><br>저편 북도 멈췄다. 따라 칠 것이 없다.<br>한참을 그대로 있었다. 저편에서 무언가 기어가는 소리가 났다. 멀어졌다.`,
      ng:`이쪽이 멈추자 저편이 혼자 치기 시작했다.<br><br>이제 이쪽 박이 저쪽 것이다. 둥, 쉼, 둥둥. 일행들이 그 박에 발을 맞춘다.<br>하나씩 붙잡아 멈춰 세웠다. 다들 얼굴이 하얗다.`,
      win:{ exp:15, spirit:5 }, lose:{ mind:-7, spirit:-10 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 매달린 신도석',
  x:`머리 위로 신도석이 줄지어 매달려 있다. 바닥에 박힌 채 거꾸로.<br><br>
    의자 밑에 무언가 붙어 산다. 박쥐 같은데 날개가 사람 손이다. 손가락 사이에 막이 있다.<br>
    가끔 하나가 떨어진다. 갈빗대 길로. 떨어질 때마다 툭. 툭. 박이 있다.<br><br>
    갈빗대 길을 따라 쉰 걸음을 가야 한다. 위에 신도석이 서른 줄이다.`,
  o:[
    { l:'① 떨어지는 박을 짚어 건넌다.', k:'fix', dc:14,
      ok:`툭 소리를 셌다. 열한 박마다 하나. 앞줄부터 차례로 떨어진다.<br><br>떨어지는 줄의 한 줄 뒤를 따라 걸었다. 막 떨어진 자리에는 한동안 안 떨어진다.<br>쉰 걸음 동안 무릎을 펴지 않았다. 다 건넜다.<br><br>박을 쫓아간 게 아니다. 박 뒤를 따라갔다. 뒤가 제일 조용하다.`,
      ng:`열한 박이 열 박이 됐다.<br><br>하나가 이쪽 목덜미에 떨어졌다. 손 날개가 목을 감는다. 손가락이 차다.<br>떼어 내자 목에 손자국이 남았다. 다섯 손가락.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-13, spirit:-7 } },
    { l:'② 갈빗대 가장자리로 피해 간다.', k:'evade', dc:14,
      ok:`신도석이 없는 가장자리 갈빗대로 갔다. 좁다. 한 발씩.<br><br>위에 아무것도 없다. 대신 옆이 비었다. 둥근 천장이 그대로 아래로 휜다.<br>한 발 한 발 디뎌 건넜다. 아무도 안 미끄러졌다.`,
      ng:`좁은 갈빗대에서 발이 미끄러졌다.<br><br>둥근 천장 곡면을 따라 한참 미끄러졌다. 갈빗대 하나에 걸려 멈췄다.<br>무릎과 손바닥이 다 벗겨졌다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-14, mind:-5 } },
    { l:'③ 북을 울려 미리 다 떨군다.', k:'break', dc:15,
      ok:`신도석 쪽으로 북을 치켜들고 세게 쳤다. 둥— 둥—<br><br>의자 밑에 붙은 것들이 놀라 한꺼번에 떨어졌다. 수십 마리. 갈빗대 위에서 버둥거린다.<br>떨어진 것들은 다시 못 올라간다. 일행이 하나씩 밟고 찔렀다.<br><br>떨어질 것을 다 떨구면 그 뒤가 빈다. 오래된 셈이다.`,
      ng:`쳤는데 절반만 떨어졌다.<br><br>나머지 절반이 깨어서 소리 난 쪽으로 날아왔다. 손 날개들이 얼굴을 덮었다.<br>북을 휘둘러 쫓았다. 얼굴에 손톱자국이 잔뜩 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, spirit:-8 } }
  ] },

{ at:'C4', t:'포자 온실 — 덩이의 맥',
  x:`온실 한가운데에 덩이가 있다. 방 하나만 하다.<br><br>
    덩이가 뛴다. 둥. 뛸 때마다 온실 전체의 버섯이 같이 부푼다. 정원사들이 같이 멈칫한다.<br>
    여기의 박은 다 저 덩이에서 나온다. 저것이 심장이다.<br><br>
    덩이 밑에서 굵은 뿌리가 사방으로 뻗었다. 뿌리 하나가 발밑을 지나간다. 맥이 뛴다.`,
  o:[
    { l:'① 맥을 따라 치다가 한 박을 비운다.', k:'fix', dc:15,
      doom:{ title:'큰 쪽이 끄는 박', what:'뿌리에 감겨 덩이 속으로 끌려갑니다', dc:15, sec:55,
        text:`덩이 박에 맞춰 쳤다. 둥에 둥. 덩이가 이쪽 박을 듣기 시작했다.<br><br>비우려 했다. 덩이가 안 비운다. 대신 이쪽 북이 빨라진다. 박은 큰 쪽이 끈다.<br>발밑 뿌리가 맥을 치며 일어섰다. 발목을 감았다. 종아리, 무릎.<br><br>덩이 쪽으로 끌려간다. 덩이 표면이 입처럼 벌어진다. 북소리가 그 안에서 울린다.`,
        dieText:`덩이는 계속 뛴다. 둥.<br><br>다만 이제 그 박 사이사이에 작은 박이 섞인다. 톡, 톡, 톡.<br>온실의 버섯들이 그 작은 박에도 부푼다. 다음에 오는 사람은 여기 박이 둘이라는 걸 알게 될 것이다.` },
      ok:`덩이 박에 맞춰 쳤다. 둥에 둥. 세 번 맞추자 덩이가 이쪽 박을 듣기 시작했다.<br><br>그리고 멈췄다. 한 박을 통째로 비웠다.<br>덩이가 그 빈 박에 맞춰 뛰려다 헛뛰었다. 온실 버섯이 반만 부풀다 주저앉았다. 정원사들이 선 채로 비틀거렸다.<br><br>헛뛴 틈에 일행이 뿌리 셋을 잘랐다. 덩이 박이 처음으로 흐트러졌다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 뿌리 사이로 숨어 덩이 뒤로 돈다.', k:'hide', dc:15,
      ok:`뿌리가 맥 칠 때마다 흙이 들썩인다. 들썩이지 않는 사이를 골라 디뎠다.<br><br>덩이 뒤로 돌았다. 뒤쪽은 뿌리가 적다. 늙은 쪽이다. 거기서 칼을 넣었다. 덩이가 처음으로 둥이 아닌 소리를 냈다.<br><br>덩이 뒤 그늘에 평범한 버섯이 몇 개 나 있다. 갓이 갈색이고 실이 없다. 여기 것 같지 않다. 땄다.`,
      ng:`디딘 데가 뿌리였다. 맥이 발바닥을 쳤다.<br><br>뿌리가 들려 이쪽을 화단으로 내던졌다. 노란 가루가 덮쳤다.<br>한참 기침했다. 입 안에서 흙냄새가 빠지지 않는다.`,
      win:{ exp:20, dream:2, item:'야생 버섯' }, lose:{ hp:-14, spirit:-9 } }
  ] },

{ at:'C', t:'쉬는 자리 — 남의 손에 쥐여 준 채',
  x:`쉬는 자리에서 일행 하나가 북을 쳐 보고 싶다고 한다.<br><br>
    사냥 때마다 박을 들었다고 한다. 들으면 칼이 가볍다고. 그 박을 제 손으로 쳐 보고 싶다고.<br>
    북채를 건넸다. 그 사람 손이 크다. 칼 쥐는 손이다.<br><br>
    첫 박이 너무 세다.`,
  o:[
    { l:'① 손목을 잡아 박을 넣어 준다.', k:'fix', dc:14, wake:1,
      ok:`그 사람 손목을 뒤에서 잡았다. 같이 쳤다. 둥. 힘을 빼라고 했다. 둥.<br><br>열 번쯤 치자 손목에서 힘이 빠졌다. 박이 섰다. 크지 않은데 멀리 간다.<br>손을 놓았다. 그 사람이 혼자 쳤다. 이쪽 박과 똑같지는 않다. 그 사람 박이다.<br><br>박을 남의 손에 넣어 줬다. 지금까지 이쪽 박은 이쪽 손에만 있었다. 이제 다섯 손 중 하나가 더 칠 줄 안다. 가르치는 손이 치는 손보다 조금 더 깊이 박을 알게 됐다.`,
      ng:`손목을 잡았는데 그 사람이 힘을 더 줬다. 둥!<br><br>가죽이 울다 못해 찢어질 것 같다. 이쪽 손가락이 북채와 가죽 사이에 찧였다.<br>북채를 돌려받았다. 그 사람이 미안해했다. 손가락이 퍼렇다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-9, mind:-6 } },
    { l:'② 북은 이쪽이 치고 박 세는 법만 가르친다.', k:'steady', dc:13,
      ok:`북채는 이쪽이 쥐고 그 사람에게 박을 세게 했다. 하나, 둘, 셋, 둥.<br><br>그 사람이 셋에 숨을 들이켜고 둥에 내쉰다. 손이 무릎을 친다.<br>칠 줄 몰라도 셀 줄은 알게 됐다. 사냥에서는 그게 먼저다.`,
      ng:`세는데 그 사람이 졸았다. 지쳤다.<br><br>이쪽도 졸았다. 박을 세다 잠들면 꿈에서도 센다.<br>깨어 보니 불이 꺼져 있다. 다시 피우느라 손이 다 얼었다.`,
      win:{ exp:14, mind:5 }, lose:{ hp:-8, mind:-7 } }
  ] },

{ at:'C', t:'사냥 뒤 — 꿈틀대는 덩이',
  x:`쓰러뜨린 것이 아직 꿈틀댄다. 잘린 자리마다 살이 부풀어 오른다.<br><br>
    일행은 다 지쳤다. 칼을 들 팔이 없다. 그것은 지치지 않는다.<br>
    꿈틀대는 데도 박이 있다. 점점 고르게 된다. 고르게 되면 다시 일어선다.<br><br>
    마지막 한 번이 필요하다. 다섯이 한 번에.`,
  o:[
    { l:'① 마지막 한 박을 친다.', k:'fix', dc:15,
      ok:`다들 숨이 고르게 될 때까지 기다렸다. 북을 가슴에 대고 작게 셋. 그리고 크게 하나.<br><br>다섯이 그 하나에 칼을 내렸다. 남은 힘을 다 모은 하나다.<br>꿈틀대던 박이 끊겼다. 다시 안 이어졌다.<br><br>그것 옆에 다 같이 주저앉았다. 한참 아무도 말하지 않았다.`,
      ng:`크게 하나를 쳤는데 둘이 못 일어섰다.<br><br>셋의 칼은 모자랐다. 그것이 반쯤 일어섰다가 쓰러졌다가 다시 일어섰다.<br>끝낼 때까지 그 짓을 네 번 했다. 다들 팔이 안 올라간다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 아직 덜 부푼 데를 도려내 챙긴다.', k:'luck', dc:14,
      ok:`부풀어 오르는 살 중에 덜 부푼 데가 있다. 아직 짐승 고기 색이다.<br><br>거기를 도려냈다. 도려낸 덩이는 다시 안 붙었다. 떨어진 건 그것이 아니다.<br>불에 구우면 먹을 수 있을 것이다. 아마.`,
      ng:`도려내는데 덩이가 칼을 물었다. 칼이 살 속으로 들어간다.<br><br>칼을 놓았다. 그것이 일어섰다. 다들 다시 칼을 쥐어야 했다.<br>이쪽 손에 그것의 진물이 묻었다. 따끔거린다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C', t:'어둠 — 터진 손바닥',
  x:`손바닥이 다 터졌다. 북채를 너무 오래 쥐었다.<br><br>
    쥐면 피가 배어 미끄럽다. 놓으면 박이 없다.<br>
    앞에서 무언가 다가온다. 바닥을 긁는 소리. 여럿이다.<br><br>
    일행이 이쪽을 본다. 박을 기다린다.`,
  o:[
    { l:'① 발로 박을 세운다.', k:'fix', dc:15, wake:1,
      ok:`북을 바닥에 엎어 놓고 발뒤꿈치로 쳤다. 쿵. 쉬고, 쿵.<br><br>낮다. 바닥을 타고 간다. 일행 발바닥으로 들어간다. 다들 발로 박을 받았다.<br>다가오던 것들과 싸우는 동안 이쪽은 손을 하나도 안 썼다.<br><br>박이 손에 있는 줄 알았다. 손은 박이 나가는 문 하나였다. 다른 문도 있다. 몸 어디서든 박을 낼 수 있다는 걸 다리가 먼저 알았다.`,
      ng:`발로 쳤는데 북이 미끄러졌다. 쿵이 아니라 퍽.<br><br>박이 안 섰다. 다들 제각각 싸웠다. 둘이 다쳤다.<br>이쪽 손바닥은 그 와중에 더 터졌다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-15, mind:-7 } },
    { l:'② 손을 싸매고 다시 쥔다.', k:'heal', dc:14,
      ok:`옷자락을 찢어 손바닥에 감았다. 단단히. 그 위로 북채를 쥐었다.<br><br>피가 천에 밴다. 미끄럽지는 않다.<br>쳤다. 둥. 소리가 조금 무디다. 박은 섰다.`,
      ng:`감는 동안 다가오는 것들이 닿았다.<br><br>반만 감은 손으로 북채를 쥐었다. 미끄러졌다. 채가 날아갔다.<br>맨손으로 쳤다. 터진 손바닥이 가죽에 붙었다 떨어졌다.`,
      win:{ exp:15, hp:6 }, lose:{ hp:-13, spirit:-6 } }
  ] },

{ at:'C', t:'나가는 길 — 북 없는 박',
  x:`나가는 문이 보인다. 다들 지쳤다. 이쪽도 지쳤다.<br><br>
    팔이 안 올라간다. 북을 칠 힘이 없다.<br>
    그런데 일행 발소리가 고르다. 다섯이 같은 박으로 걷는다. 아무도 북을 안 치는데.<br><br>
    북잡이는 그 소리를 듣고 한참 걸음을 멈췄다.`,
  o:[
    { l:'① 북을 등에 메고 그 박에 들어간다.', k:'fix', dc:14,
      ok:`북을 등에 메고 걸었다. 이쪽도 그 박에 들어갔다.<br><br>남이 만든 박에 이쪽이 걷는다. 처음이다.<br>문을 지났다. 다섯이 한 박에.<br><br>등 뒤 북이 걸음마다 등을 톡톡 친다. 그것도 박이다.`,
      ng:`메고 걷는데 박이 조금씩 흐트러졌다. 다들 이쪽 북을 기다리고 있었다.<br><br>안 치니 박이 풀렸다. 하나가 발을 헛디뎠다.<br>문 앞에서 넘어졌다. 무릎이 깨졌다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-9, mind:-6 } },
    { l:'② 마지막으로 한 번 친다.', k:'steady', dc:14,
      ok:`북을 앞으로 돌려 한 번 쳤다. 둥.<br><br>다섯 걸음이 그 소리에 한 번 더 맞춰졌다. 그걸로 됐다.<br>문을 나서자 손이 저절로 북채를 놓았다.`,
      ng:`친다는 게 북 테를 쳤다. 딱.<br><br>어둠 저편에서 딱, 하고 대답이 왔다. 다들 뛰었다.<br>문을 나올 때 등 뒤로 무언가 긁는 소리가 났다.`,
      win:{ exp:15, mind:6 }, lose:{ mind:-8, spirit:-8 } },
    { l:'③ 맨 뒤에서 발소리를 센다.', k:'sense', dc:14,
      ok:`맨 뒤로 가서 발소리를 셌다. 이쪽 빼고 넷. 맞다.<br><br>발소리 하나하나가 다르다. 그래도 같은 박 안에 있다.<br>문을 나설 때까지 셌다. 하나도 안 빠졌다.`,
      ng:`세는데 다섯이다. 이쪽을 빼고.<br><br>다시 셌다. 넷. 또 셌다. 다섯.<br>문을 나오고 뒤를 봤다. 아무도 없다. 문 안쪽에서 발소리 하나가 멈췄다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-7, spirit:-10 } }
  ] }

]);

// ── 전술가 ──────────────────────────────
kJob('tactician', 'C', [

{ at:'C', t:'첫 방 — 자국의 셈',
  x:`첫 방 바닥에 자국이 많다. 긁힌 자국, 끌린 자국, 마른 핏자국.<br><br>
    자국은 셈이다. 긁힌 폭으로 발톱 수를, 끌린 길이로 무게를, 핏자국 높이로 키를 센다.<br>
    여기 사는 것은 사람보다 크다. 하나다. 혼자서는 아무도 못 잡는다.<br><br>
    일행은 벌써 칼을 뽑았다. 다섯이 다섯 방향을 본다.`,
  o:[
    { l:'① 미끼, 몰이, 마무리를 나눈다.', k:'fix', dc:15, wake:1,
      ok:`발 빠른 사람을 미끼로, 힘센 둘을 몰이로, 창 든 사람을 마무리로. 이쪽은 셋 사이 가운데에 섰다.<br><br>그것이 나왔다. 미끼를 쫓았다. 몰이 둘이 양옆을 막았다. 좁아진 길 끝에 창이 기다렸다.<br>한 번에 들어갔다. 그것이 벽에 박혀 쓰러졌다.<br><br>사람 다섯을 셋으로 셌다. 셋을 다시 하나로 셌다. 돌을 놓은 게 아니라 판 전체를 수 하나로 만들었다. 셈이 한 단 깊어졌다.`,
      ng:`나누자고 했는데 미끼를 아무도 안 하려 한다.<br><br>정하는 사이 그것이 먼저 나왔다. 미끼 없는 판에서는 다 미끼다.<br>제일 가까운 사람이 이쪽이었다. 등을 할퀴었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 자국을 따라 굴부터 찾는다.', k:'sense', dc:14,
      ok:`끌린 자국을 따라갔다. 벽 구석에 굴이 있다. 안에서 숨소리가 난다. 자는 숨이다.<br><br>자는 것은 판에 없는 셈이다. 굴 입구를 돌로 막고 다른 길로 돌았다.<br>싸우지 않은 것도 이긴 셈에 든다.`,
      ng:`굴을 찾았는데 숨소리가 굴 안이 아니라 뒤에서 난다.<br><br>자국은 나간 자국이었다. 돌아본 순간 그것이 덮쳤다.<br>바닥을 굴러 피했다. 팔꿈치가 깨졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-13, mind:-6 } }
  ] },

{ at:'C1', t:'도축장 — 빈 갈고리 셋',
  x:`쇠줄에 갈고리가 돈다. 빈 갈고리는 셋. 고기 걸린 것이 열일곱.<br><br>
    빈 갈고리는 낮게 지나간다. 사람 목 높이다. 고기 걸린 것은 높이 지나간다.<br>
    세면 보인다. 빈 것 셋 사이 간격이 똑같지 않다. 첫째와 둘째 사이가 제일 길다.<br><br>
    그 사이에 다섯이 다 건너야 한다.`,
  o:[
    { l:'① 건널 순서를 짠다.', k:'fix', dc:14,
      ok:`느린 사람을 첫째로, 빠른 사람을 마지막으로. 둘씩 짝지어 손을 잡게 했다. 이쪽은 셋째 자리.<br><br>첫째 빈 갈고리가 지나가자 바로 뛰었다. 둘, 둘, 하나. 마지막 하나가 건너자 둘째가 지나갔다.<br>숨 한 번 차이였다.<br><br>셈이 맞았다. 맞는 셈은 늘 숨 한 번만큼만 맞는다.`,
      ng:`둘씩 짝지었는데 한 짝이 손을 놓쳤다.<br><br>하나가 줄 밑에 멈췄다. 둘째 빈 갈고리가 왔다. 그 사람을 밀어 엎드리게 했다. 이쪽 어깨에 갈고리 끝이 박혔다.<br>빼는 데 살이 같이 딸려 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-5 } },
    { l:'② 고깃덩이를 걸어 빈 갈고리를 없앤다.', k:'break', dc:14,
      ok:`바닥에 떨어진 고깃덩이를 들어 빈 갈고리에 걸었다. 하나, 둘.<br><br>고기가 걸리자 갈고리가 높이 올라갔다. 빈 것이 하나만 남았다.<br>하나는 셈이 쉽다. 다 건넜다.<br><br>걸어 둔 고기가 줄을 돌며 조금씩 부풀었다. 다음 사람 몫까지 셈하지는 않았다.`,
      ng:`고기를 거는데 고기가 이쪽 손목을 감았다.<br><br>잘린 고기가 아직 산다. 손목에서 떼어 내는 사이 빈 갈고리가 지나갔다. 머리카락이 한 줌 뜯겨 갔다.<br>두피에서 피가 흐른다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 자르면 늘어난다',
  x:`고기 짐승이 셋이다. 아까는 하나였다.<br><br>
    하나를 반으로 갈랐더니 둘이 됐다. 둘 중 하나를 또 갈랐더니 셋이 됐다. 자를수록 늘어난다.<br>
    칼이 셈을 틀리게 한다. 여기서 칼질은 더하기다.<br><br>
    창고 구석에 소금 자루가 쌓여 있다. 도축장은 고기를 소금에 절인다.`,
  o:[
    { l:'① 자른 자리마다 소금을 치게 한다.', k:'fix', dc:15, wake:1,
      ok:`둘은 자르고 둘은 소금을 뿌리게 했다. 자르는 손 바로 뒤에 소금 손.<br><br>잘린 자리에 소금이 닿자 실이 오그라들었다. 붙지 않는다. 늘지도 않는다.<br>셋이 둘이 되고 둘이 하나가 되고 하나가 고기가 됐다.<br><br>칼을 빼기로 바꿨다. 같은 칼, 같은 손인데 짝을 지어 놓으니 셈이 뒤집혔다. 무엇을 쓰느냐보다 무엇 뒤에 무엇을 놓느냐가 판이다. 이번에 손으로 알았다.`,
      ng:`소금 손이 자르는 손을 못 따라갔다.<br><br>소금 안 친 자리가 붙고, 갈라지고, 늘었다. 다섯이 됐다.<br>소금 자루를 통째로 던져 막고 물러났다. 다들 어딘가 물렸다.`,
      win:{ exp:25, dream:3, item:'소금 덩이' }, lose:{ hp:-15, mind:-8 } },
    { l:'② 자르지 말고 통에 가둔다.', k:'steady', dc:14,
      ok:`칼을 거두게 하고 빈 고기 통을 엎어 셋을 가뒀다. 위에 둘이 앉았다.<br><br>통 속에서 셋이 부딪힌다. 붙을 데가 없어 서로 붙는다. 하나가 된다.<br>하나가 된 것은 통을 못 들어 올렸다. 무게가 늘었을 뿐이다.`,
      ng:`엎었는데 하나가 통 밖으로 비어져 나왔다.<br><br>비어져 나온 것이 앉은 사람 허벅지를 물었다. 통이 들썩였다.<br>다시 눌러 앉느라 한참 씨름했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'③ 어느 것이 처음 것인지 본다.', k:'gaze', dc:15,
      ok:`셋을 봤다. 하나만 흉터가 있다. 처음 갈린 자리다.<br><br>나머지 둘은 거기서 나간 것이다. 처음 것만 잡으면 된다. 처음 것의 심줄을 끊자 둘이 흐물흐물 녹았다.<br>처음을 찾으면 셈이 짧아진다.`,
      ng:`흉터가 셋 다 있다.<br><br>처음 것이 둘에게 흉터를 나눠 줬다. 들킨 줄 아는 모양이다.<br>찾는 동안 셋이 동시에 덮쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-7 } }
  ] },

{ at:'C2', t:'인형 공방 — 안 볼 때 오는 것',
  x:`선반에 인형이 서른하나. 다시 세니 서른둘이다.<br><br>
    보는 동안엔 가만있다. 눈을 돌리면 자리가 바뀐다. 한 칸씩 가까워진다.<br>
    눈은 다섯 쌍이다. 선반은 사방에 있다.<br><br>
    나가는 문은 공방 반대편이다.`,
  o:[
    { l:'① 눈을 나눠 맡긴다.', k:'fix', dc:14,
      ok:`사방을 넷이 하나씩 맡게 했다. 맡은 쪽만 보고 걷게 했다. 이쪽은 가운데에서 넷의 등을 봤다.<br><br>눈이 비는 쪽이 없다. 인형들이 한 칸도 못 움직였다.<br>뒷걸음질하는 사람, 옆걸음질하는 사람. 이상한 걸음으로 다섯이 공방을 건넜다.<br><br>문을 닫는 순간 안에서 사기 부딪치는 소리가 쏟아졌다. 서른몇 개가 한꺼번에 움직였다.`,
      ng:`맡은 쪽을 보던 사람 하나가 눈을 깜박였다.<br><br>깜박임 한 번에 한 칸. 그쪽 인형이 발치까지 왔다. 이가 발목에 박혔다.<br>떼어 내자 사기 턱이 부서졌다. 이는 박힌 채 남았다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 인형들 얼굴을 벽으로 돌려놓는다.', k:'hide', dc:14,
      ok:`가까운 선반부터 인형을 돌려놓았다. 얼굴이 벽을 보게.<br><br>얼굴을 돌려놓은 것은 안 움직였다. 보는 것을 쫓는 것은 보지 못하면 쫓지 못한다.<br>스물을 돌려놓고 나머지 사이로 지났다.`,
      ng:`돌려놓은 인형이 고개만 돌렸다. 목이 한 바퀴 돈다.<br><br>사기 목이 갈리는 소리가 났다. 그 소리에 다른 인형들도 고개를 돌렸다.<br>뛰었다. 등 뒤로 딸깍 소리가 쫓아왔다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, spirit:-9 } }
  ] },

{ at:'C2', t:'인형 공방 — 실 끝을 쥔 손',
  x:`천장에서 실이 수백 가닥 내려온다. 위층으로 이어진다.<br><br>
    실 끝마다 인형이 매달렸다. 몇 가닥은 일행 손목과 발목에 이미 걸렸다. 아직 당기지는 않는다.<br>
    실이 다 같은 실이 아니다. 몇 가닥만 팽팽하다. 팽팽한 실이 나머지를 쥐고 있다.<br><br>
    어느 실을 끊느냐에 따라 나머지가 풀리거나 조인다.`,
  o:[
    { l:'① 끊을 실을 고른다.', k:'fix', dc:15,
      doom:{ title:'셈에 없던 실', what:'실에 감겨 위층으로 끌려 올라갑니다', dc:15, sec:60,
        text:`팽팽한 실 하나를 골라 끊었다. 셈으로는 그것이 나머지를 쥔 실이다.<br><br>나머지가 풀렸다. 일행 손목에서 실이 흘러내렸다. 맞았다.<br>그런데 이쪽 손목의 실은 안 풀렸다. 조였다. 끊은 실이 잡던 무게가 다 이쪽 실로 왔다.<br><br>발이 바닥에서 떨어진다. 천장 구멍 쪽으로 당겨 올라간다. 위층에서 무언가 실을 감는 소리가 난다.`,
        dieText:`셈은 맞았다. 일행 넷은 다 풀려났다.<br><br>셈에 넣지 않은 실이 하나 있었다. 셈하는 사람 손목에 걸린 실.<br>위층 작업대 위에 새 인형이 하나 앉았다. 손가락을 꼽는 모양으로 굳은 인형이다.` },
      ok:`팽팽한 실을 셌다. 일곱. 그중 둘이 나머지 다섯을 쥐고 있다. 둘 중 하나는 이쪽 손목에 이어졌다.<br><br>이쪽 손목 실부터 이로 끊고, 나머지 하나를 칼로 끊었다. 동시에.<br>실 수백 가닥이 한꺼번에 흘러내렸다. 인형들이 바닥에 쏟아져 깨졌다.<br><br>셈에 제 손목을 맨 먼저 넣었다. 빼먹었으면 이쪽이 매달렸을 것이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 실이 모이는 데를 보고 올라갈 길을 찾는다.', k:'sense', dc:14,
      ok:`실을 눈으로 따라갔다. 위층 바닥 구멍 셋으로 모인다. 구멍 하나는 계단 위다.<br><br>계단 위 구멍 밑으로는 실이 지나가지 않는다. 실을 내리는 데에 계단이 걸리면 안 되니까.<br>계단 벽에 붙어 올라갔다. 실 하나 안 건드렸다.`,
      ng:`실을 따라가다 실에 걸렸다. 목이다.<br><br>얼른 손가락을 끼워 넣었다. 실이 손가락을 파고들었다.<br>일행이 끊어 줄 때까지 숨을 못 쉬었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-13, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 안 맞는 셈',
  x:`사냥 하나를 끝내고 쉰다. 셈을 할 때다.<br><br>
    다친 사람 둘. 깊은 상처 하나, 얕은 것 넷. 약초는 한 뭉치. 칼 하나는 이가 빠졌다. 횃불은 셋.<br>
    다음 사냥은 이번보다 클 것이다. 여기서는 늘 그렇다.<br><br>
    셈이 안 맞는다. 하나를 버려야 맞는다.`,
  o:[
    { l:'① 약초를 깊은 상처에만 쓴다.', k:'fix', dc:14,
      ok:`약초를 다 깊은 상처에 썼다. 얕은 상처 넷은 물로 씻고 천으로 묶었다.<br><br>깊은 상처가 덧나지 않았다. 얕은 것들은 따끔거렸다. 그것뿐이다.<br>다음 사냥에 다섯이 다 섰다.<br><br>똑같이 나누면 다 조금씩 낫는다. 조금씩 나은 다섯은 다음 판에서 다 조금씩 진다.`,
      ng:`깊은 상처에 다 썼는데 얕은 상처 하나가 곪았다.<br><br>얕은 줄 알았는데 안에 무언가 박혀 있었다. 이빨 조각이다.<br>빼내는 동안 그 사람이 이를 악물었다. 셈에 없던 상처다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-8, spirit:-7 } },
    { l:'② 이 빠진 칼을 버리고 횃불을 늘린다.', k:'luck', dc:14,
      ok:`이 빠진 칼을 내려놓고 그 손에 횃불 하나를 더 쥐게 했다.<br><br>여기 것들은 불을 싫어한다. 불 둘이 칼 하나보다 낫다.<br>칼을 내려놓은 돌 틈에서 꿀단지가 나왔다. 앞서 쉬어 간 누군가 숨겨 둔 것이다.`,
      ng:`칼을 내려놓는데 돌 틈에 무언가 있었다.<br><br>잘린 손가락이다. 아직 움직인다. 이쪽 손등을 기어오른다.<br>털어 내고 밟았다. 다들 쉬지를 못했다.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ mind:-7, spirit:-9 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 위가 아래다',
  x:`성당이 거꾸로 서 있다. 둥근 천장을 밟고 걷는다. 제단은 머리 위에 매달려 있다.<br><br>
    다들 위를 보며 걷다 발을 헛디딘다. 오른쪽이라 하면 왼쪽으로 간다. 거꾸로 선 데서는 손도 거꾸로 짚인다.<br>
    판을 짜도 다들 판을 거꾸로 읽는다.<br><br>
    나가는 문은 위에 있다. 원래는 바닥에 있던 문이다.`,
  o:[
    { l:'① 판의 말을 바꿔 다시 짠다.', k:'fix', dc:15, wake:1,
      ok:`오른쪽 왼쪽을 버렸다. 제단 쪽, 종 쪽. 제단 쪽으로 세 걸음, 종 쪽으로 두 걸음. 머리 위 것에 이름을 붙여 셈을 다시 했다.<br><br>다들 위를 보며 걸었다. 위를 보고 걷는 게 여기서는 맞는 걸음이다.<br>아무도 안 헤맸다. 문 밑까지 곧장 왔다.<br><br>판을 뒤집지 않았다. 판의 말을 바꿨다. 같은 수도 이름을 바꾸면 남의 손에서 바로 읽힌다. 셈은 남이 읽을 수 있어야 셈이다.`,
      ng:`제단 쪽, 종 쪽으로 이름을 붙였는데 종이 움직였다.<br><br>종 쪽이 바뀌었다. 다들 엉뚱한 데로 갔다. 하나가 갈빗대 사이 틈으로 빠질 뻔했다.<br>붙잡아 올렸다. 손가락 둘이 젖혀졌다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ hp:-12, mind:-9 } },
    { l:'② 발밑 갈빗대를 세어 길을 잡는다.', k:'sense', dc:14,
      ok:`위를 안 보고 발밑만 봤다. 갈빗대가 방사로 뻗었다. 셋째 갈빗대가 문 쪽으로 간다.<br><br>그것만 따라 걸었다. 다들 이쪽 발만 보고 걸었다.<br>문 밑에 닿았다.`,
      ng:`갈빗대를 세는데 하나가 더 있다. 다시 세니 또 하나.<br><br>늘어나는 갈빗대는 갈빗대가 아니다. 셋째라고 디딘 데가 물컹했다.<br>발을 뺐다. 발목에 진물이 묻었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-11, spirit:-7 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 혀 셋, 사람 다섯',
  x:`둥근 천장 위에 종이 셋. 입을 위로 벌리고 있다.<br><br>
    종 안에 사는 것은 지나가는 것을 낚는다. 종 입에서 혀 같은 것이 튀어나와 감아 들인다. 한 번에 하나.<br>
    세 종 사이를 지나야 한다. 혀는 셋이다. 사람은 다섯이다.<br><br>
    혀 셋이 다 나온 뒤에는 한동안 안 나온다. 감아 들인 것을 씹는 동안.`,
  o:[
    { l:'① 미끼 셋을 던질 판을 짠다.', k:'fix', dc:15,
      ok:`외투 둘과 배낭 하나에 돌을 넣어 묶었다. 하나씩 세 종 앞에 던졌다.<br><br>혀 셋이 다 나와 미끼를 감아 들였다. 종 안에서 우적거리는 소리.<br>그 사이 다섯이 다 지났다.<br><br>세 종 다 배낭과 외투를 뱉어 냈다. 먹을 것이 아니란 걸 아는 데 숨 스무 번. 셈한 대로다.`,
      ng:`미끼 둘을 던지고 셋째를 던지려는데 하나가 셋째 종 앞으로 먼저 나섰다.<br><br>혀가 그 사람을 골랐다. 허리를 감았다. 다 같이 매달려 당겼다.<br>끌어냈다. 허리에 둥글게 살이 벗겨졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, mind:-6 } },
    { l:'② 제가 미끼가 되어 뛴다.', k:'evade', dc:15,
      ok:`맨 앞으로 나가 세 종 앞을 지그재그로 뛰었다.<br><br>혀 셋이 차례로 나왔다. 하나, 둘. 셋째가 발목을 스쳤다.<br>셋 다 나온 뒤에 손을 흔들었다. 넷이 지났다.<br><br>셈하는 사람이 셈 속에 뛰어들었다. 숨이 찼다.`,
      ng:`둘째 종 앞에서 발이 갈빗대에 걸렸다.<br><br>혀가 무릎을 감았다. 종 쪽으로 끌려간다. 일행이 팔을 잡았다.<br>빠져나왔다. 무릎에 혀 자국이 붉게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 종 입에 젖은 천을 덮는다.', k:'hide', dc:14,
      ok:`젖은 천을 들고 종 뒤로 다가갔다. 소리 없이. 종 입에 천을 덮었다.<br><br>혀가 천을 감았다. 천째 종 안으로 들어갔다. 그 종은 한참 천을 씹었다.<br>두 종만 남았다. 다섯이 둘째와 셋째 사이로 지났다.`,
      ng:`천을 덮는데 종이 울렸다. 낮게. 젖은 소리로.<br><br>다른 두 종이 같이 울렸다. 혀가 셋 다 이쪽으로 나왔다.<br>엎드려 피했다. 하나가 등을 쓸고 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C4', t:'포자 온실 — 노란 강',
  x:`온실 천장에 환기창이 셋. 하나만 열려 있다. 바람이 그리로 빠진다.<br><br>
    바람이 빠지는 길로 포자가 흐른다. 노란 강이다. 그 강을 피해서 가야 한다.<br>
    강은 바람을 따라 굽는다. 바람은 문을 열고 닫을 때마다 바뀐다.<br><br>
    문을 하나 열면 강이 굽는다. 어느 쪽으로 굽을지 셈해야 한다.`,
  o:[
    { l:'① 문을 열어 강을 비킨다.', k:'fix', dc:15,
      doom:{ title:'굽은 강', what:'포자 더미에 파묻힙니다', dc:15, sec:60,
        text:`서쪽 문을 열었다. 셈대로라면 강이 서쪽으로 굽는다.<br><br>강이 굽었다. 서쪽이 아니라 이쪽으로. 셈에 없던 환기창 하나가 바람에 열렸다.<br>노란 강이 머리 위로 쏟아졌다. 숨을 참았다. 무릎까지, 허리까지 가루가 쌓인다.<br><br>가루가 무겁다. 움직일수록 파묻힌다. 입을 열면 들어온다.`,
        dieText:`바람은 다시 바뀌었다. 강은 한동안 같은 자리에 머물렀다.<br><br>그 자리에 노란 언덕이 하나 생겼다. 사람 키만 하다.<br>며칠 지나 언덕 위에 버섯이 났다. 줄을 맞춰서. 셈하듯이.` },
      ok:`서쪽 문을 열기 전에 천장 환기창들을 다시 셌다. 셋 중 하나가 덜렁거린다. 그것도 셈에 넣었다.<br><br>강이 굽었다. 서쪽으로 반, 덜렁이는 창 쪽으로 반. 두 갈래 사이에 길이 났다.<br>다섯이 그 사이로 지났다. 머리 위로 노란 것이 두 갈래로 흘렀다.<br><br>셈에 넣은 것 하나가 길 하나를 냈다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 젖은 천으로 입을 막고 건넌다.', k:'heal', dc:14,
      ok:`물통을 다 털어 천을 적셨다. 다섯이 입과 코를 막았다.<br><br>강 가장 좁은 데를 골라 숨을 참고 건넜다. 젖은 천이 노란 것을 붙잡았다.<br>건너와서 천을 버렸다. 천이 노랗게 굳었다. 벌써 실이 나 있다.`,
      ng:`천이 모자랐다. 넷만 적셨다.<br><br>이쪽은 마른 소매로 막았다. 건너는 동안 가루가 스몄다.<br>밤새 기침했다. 기침할 때마다 노란 것이 나왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-9 } }
  ] },

{ at:'C4', t:'포자 온실 — 정원사 셋의 돌림',
  x:`정원사 셋이 화단을 돈다. 모자 밑이 하얀 실이다.<br><br>
    도는 길이 정해져 있다. 셋 다 같은 길을 다른 때에 돈다. 물뿌리개를 들고. 물 대신 노란 가루를 뿌린다.<br>
    셋이 한 바퀴 도는 데 걸리는 숨을 셌다. 하나는 백, 하나는 백이십, 하나는 백오십.<br><br>
    셋 다 한쪽을 비우는 때가 언젠가 온다. 언제인지 셈해야 한다.`,
  o:[
    { l:'① 셋이 다 비우는 틈을 짠다.', k:'fix', dc:15, wake:1,
      ok:`셈을 바닥에 손가락으로 그었다. 백, 백이십, 백오십. 셋이 다 동쪽 화단을 등지는 때가 숨 육백에 한 번 온다.<br><br>다섯이 육백을 셌다. 같이. 이쪽 입만 움직이고 다들 이쪽 입을 봤다.<br>육백에 셋이 다 등을 돌렸다. 동쪽 화단을 가로질렀다. 가로지르고 나서도 숨 마흔이 남았다.<br><br>셋의 셈을 하나로 묶었다. 따로 셀 때는 안 보이던 틈이 묶으니 보였다. 엇갈린 것들 사이에도 맞물리는 데가 있다.`,
      ng:`육백을 세는데 하나가 물통을 떨어뜨렸다.<br><br>주우러 돌아섰다. 셈이 깨졌다. 셋 중 하나가 셈보다 일찍 돌아왔다.<br>노란 가루를 정면으로 맞았다. 눈이 부어 반나절 앞을 못 봤다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-12, spirit:-10 } },
    { l:'② 하나만 떼어 내 사냥한다.', k:'break', dc:15,
      ok:`백오십 걸리는 놈이 제일 느리다. 그놈이 다른 둘과 제일 멀어지는 자리를 골랐다.<br><br>화단 그늘에서 기다렸다가 다섯이 한꺼번에 덮쳤다. 모자가 날아가고 실 덩이가 쏟아졌다.<br>다른 둘은 셈대로 멀리 있었다. 하나만 잡았다. 그걸로 돌림에 구멍이 났다.`,
      ng:`덮쳤는데 실 덩이가 생각보다 질겼다. 칼이 미끄러진다.<br><br>시간이 걸렸다. 셈에 없던 시간이다. 다른 하나가 돌아왔다.<br>둘에게 쫓겨 화단 둘을 넘었다. 장화를 하나 잃었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, mind:-6 } },
    { l:'③ 돌림 바깥 창고를 먼저 턴다.', k:'luck', dc:14,
      ok:`돌림 바깥에 창고가 있다. 정원사들이 안 들어가는 데다.<br><br>안은 말라 있다. 곰팡이가 없다. 선반에 말린 고기가 기름종이에 싸여 있다. 진짜 정원사들의 점심이다.<br>창고 문틀에 소금이 발라져 있었다. 그래서 안 들어온 것이다.`,
      ng:`창고 문을 여는데 문 안쪽에 하얀 실이 막처럼 쳐져 있다.<br><br>팔이 막을 뚫었다. 실이 팔에 붙어 따라 나왔다. 따끔거린다.<br>창고 안은 이미 곰팡이 집이다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'사냥 — 좁은 목',
  x:`큰 것이 넓은 방에 산다. 넓은 데서는 다섯이 둘러싸도 빈틈이 넷이다.<br><br>
    방 한쪽에 좁은 통로가 있다. 어깨 하나 너비. 저것이 들어가면 몸통이 걸린다.<br>
    몰아넣으면 앞만 남는다. 앞만 있는 짐승은 셈이 쉽다.<br><br>
    몰려면 누군가 넓은 데서 뒤를 쳐야 한다. 그 사람은 몰리는 짐승 앞에 선다.`,
  o:[
    { l:'① 좁은 데로 모는 판을 짠다.', k:'fix', dc:15, wake:1,
      ok:`횃불 둘을 양옆에 세워 넓은 쪽을 막고, 하나가 뒤에서 소리를 지르게 했다. 창 둘은 통로 끝에. 이쪽은 통로 입구 바로 옆 벽에 붙었다.<br><br>그것이 불을 피해 통로로 들어왔다. 어깨가 걸렸다. 앞으로도 뒤로도 못 간다.<br>창 둘이 앞을 쳤다. 이쪽은 옆에서 걸린 어깨를 쳤다. 셋이 세 군데를 치니 금방 끝났다.<br><br>짐승을 판 위에 놓지 않았다. 땅을 판으로 썼다. 벽 하나, 통로 하나가 사람 둘 몫을 했다. 이제 방을 보면 방이 먼저 셈에 들어온다.`,
      ng:`횃불 하나가 늦게 섰다. 넓은 쪽이 반만 막혔다.<br><br>그것이 통로 대신 빈 쪽으로 빠졌다. 소리 지르던 사람을 들이받았다.<br>쓰러진 사람을 끌어내는 동안 이쪽이 앞을 막았다. 갈비뼈가 결린다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-17, mind:-6 } },
    { l:'② 제가 넓은 쪽에 버티고 선다.', k:'steady', dc:15,
      ok:`통로 반대편 넓은 데에 섰다. 그것이 이쪽으로 왔다가 다섯 걸음 앞에서 멈췄다.<br><br>사람 하나가 버티고 서 있으면 짐승은 잰다. 재는 동안 뒤에서 창이 들어갔다.<br>다리가 후들거렸다. 그것이 쓰러지고 나서야 떨렸다.`,
      ng:`그것이 재지 않았다. 그대로 왔다.<br><br>옆으로 굴렀다. 어깨가 바닥에 갈렸다.<br>창이 그 뒤에 들어갔다. 이쪽은 셈에서 빠진 채로 누워 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-5 } }
  ] },

{ at:'C1', t:'도축장 — 빈 자리 하나',
  x:`작업 줄이 길다. 자리가 열둘. 자리마다 고깃덩이가 하나씩 놓여 있다. 하나만 비었다.<br><br>
    안쪽에서 앞치마 두른 큰 것이 줄을 본다. 줄이 한 칸 갈 때마다 자리를 하나씩 센다.<br>
    빈 자리에서 그것의 고개가 멈춘다. 그리고 둘레를 둘러본다. 채울 것을 찾는다.<br><br>
    둘레에 있는 것은 다섯이다.`,
  o:[
    { l:'① 빈 자리를 다른 것으로 채운다.', k:'fix', dc:15,
      ok:`바닥에 떨어진 갈비짝을 끌어다 빈 자리에 놓았다. 줄이 한 칸 갔다.<br><br>그것이 셌다. 열둘. 고개가 안 멈췄다. 둘레를 안 봤다.<br>그 사이 다섯이 줄 뒤를 지나 안쪽으로 갔다. 그것의 등 뒤다.<br><br>셈하는 것은 셈이 맞으면 안 본다. 그건 저쪽도 이쪽도 같다.`,
      ng:`갈비짝을 놓았는데 줄이 한 칸 가면서 굴러떨어졌다.<br><br>빈 자리가 다시 비었다. 그것의 고개가 멈췄다. 이쪽을 봤다.<br>칼이 날아왔다. 피했는데 귀 끝이 잘렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-15, spirit:-7 } },
    { l:'② 자리를 하나 더 비운다.', k:'break', dc:15,
      ok:`고깃덩이 하나를 더 끌어내렸다. 빈 자리가 둘.<br><br>그것이 고개를 멈추고 둘레를 둘러봤다. 하나를 채우러 오다가 또 하나가 빈 걸 보고 섰다. 셈이 두 번 틀리면 셈하는 것도 멈춘다.<br>멈춘 틈에 넷이 덮쳤다.`,
      ng:`둘을 비우자 그것이 둘을 채우러 왔다. 빨리.<br><br>둘레에서 제일 가까운 둘을 집으려 했다. 이쪽과 옆 사람이다.<br>칼등에 맞아 둘 다 바닥에 나뒹굴었다. 일행이 끌어냈다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'③ 그것이 세는 박을 센다.', k:'sense', dc:14,
      ok:`그것이 한 칸에 한 번씩 고개를 끄덕인다. 열두 번 끄덕이면 처음으로 돌아간다. 처음으로 돌아갈 때 한 번 눈을 감는다.<br><br>그 한 번을 기다려 지나갔다. 다섯이 한 번에.<br>눈 뜬 그것은 빈 자리만 계속 봤다.`,
      ng:`열둘을 세는데 그것이 열하나에서 처음으로 돌아갔다.<br><br>셈이 하나 줄었다. 지나가던 넷째가 그것 눈에 걸렸다.<br>쇠갈고리가 날아와 넷째 발목을 꿰었다. 줄에 끌려가기 전에 잘라 냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'인형 공방 — 넷만 있는 인형',
  x:`작업대 위에 인형이 나란히 앉아 있다. 새것이다. 유약이 아직 마르지 않았다.<br><br>
    하나하나 일행을 닮았다. 옷, 머리 모양, 흉터까지. 그런데 넷이다. 다섯째 자리는 비었다.<br>
    다섯째 자리 옆에 붓과 사기 흙이 놓여 있다. 지금 만드는 중이다.<br><br>
    일행 넷이 제 인형을 보고 얼굴이 하얘졌다. 이쪽 것만 아직 없다.`,
  o:[
    { l:'① 인형 자리를 섞어 놓는다.', k:'fix', dc:15, wake:1,
      ok:`인형 넷의 자리를 바꿨다. 첫째를 셋째에, 둘째를 넷째에. 옷도 서로 바꿔 입혔다.<br><br>만드는 것은 누가 누구인지 셈해야 다음을 만든다. 셈을 섞어 놓으면 다음이 늦어진다.<br>공방을 나올 때까지 다섯째 자리는 비어 있었다. 위층에서 무언가 짜증스럽게 흙을 치는 소리가 났다.<br><br>사람을 셈하는 판이 저쪽에도 있다. 저쪽 판을 흐트러뜨린 건 처음이다. 판을 짜는 손이 남의 판을 지우는 데에도 쓰인다는 걸 알았다.`,
      ng:`섞어 놓았는데 인형들이 저절로 제자리로 돌아갔다. 사기 엉덩이가 작업대를 긁으며.<br><br>그리고 다섯째 자리에 새 인형이 앉았다. 반쯤 빚다 만 것이다. 얼굴만 있다. 이쪽 얼굴이다.<br>등 뒤가 한참 서늘했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-10, spirit:-12 } },
    { l:'② 제 자리에 다른 것을 앉힌다.', k:'gaze', dc:14,
      ok:`다섯째 자리에 깨진 인형 몸통 하나를 앉혔다. 그 위에 이쪽 머리띠를 둘렀다.<br><br>붓이 저절로 움직이다 멈췄다. 이미 있는 것은 또 안 만든다.<br>나머지 넷은 들고 나와 불에 넣었다. 사기가 터지며 안에서 사람 머리카락이 탔다.`,
      ng:`머리띠를 두르는데 붓이 이쪽 손등을 그었다.<br><br>유약 같은 하얀 줄이 생겼다. 닦아도 안 지워진다. 손등이 차갑다.<br>공방을 나오고 한참 뒤에야 그 줄이 지워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-9, spirit:-10 } }
  ] },

{ at:'C', t:'어둠 — 틀린 판',
  x:`판이 틀렸다. 앞에 하나라고 셈했는데 둘이었다.<br><br>
    일행 하나가 다쳤다. 다리다. 못 걷는다. 둘째 것이 어둠 속에서 다시 오고 있다.<br>
    틀린 판을 붙잡고 있으면 다 틀린다.<br><br>
    다들 이쪽 입을 본다.`,
  o:[
    { l:'① 판을 버리고 새로 짠다.', k:'fix', dc:15,
      ok:`<span style="color:#d4af37;">"둘이 업고, 둘이 막고, 하나는 불."</span><br><br>짧게 말했다. 길게 말할 시간이 없다. 다들 바로 움직였다. 판이 틀린 걸 다들 알았으니까.<br>업은 둘이 먼저 빠지고 막는 둘이 뒷걸음질로 따랐다. 이쪽이 불을 휘두르며 맨 끝에 섰다.<br><br>새 판은 틀린 판보다 거칠었다. 거친 판이 맞았다.`,
      ng:`새로 짜는데 입이 안 떨어진다. 셈이 머릿속에서 엉켰다.<br><br>그 한 숨 사이 둘째 것이 닿았다. 막을 사람이 정해지지 않았다.<br>이쪽이 막았다. 팔에 깊은 자국이 났다.`,
      win:{ exp:22, dream:2, mind:6 }, lose:{ hp:-16, mind:-8 } },
    { l:'② 다친 이부터 뒤로 뺀다.', k:'bond', dc:14,
      ok:`판을 짤 생각을 접고 다친 사람 겨드랑이에 팔을 넣었다. 끌었다.<br><br>다른 넷이 저절로 그 앞을 막았다. 시키지 않았다. 누가 끌려가면 다들 그 앞에 선다.<br>판 없이도 판이 섰다.`,
      ng:`끌다가 둘이 같이 넘어졌다.<br><br>둘째 것이 넘어진 쪽으로 왔다. 일행이 막아 줬다. 막은 사람이 다쳤다.<br>틀린 판이 하나 더 틀렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 여섯을 세는 노래',
  x:`매달린 성가대석에서 노래가 내려온다. 노래에 숫자가 있다.<br><br>
    하나, 둘, 셋, 넷, 다섯. 일행 머릿수만큼 세고, 여섯을 부른다. 여섯을 부를 때마다 입들이 이쪽을 향한다.<br>
    여섯째는 없다. 없는 여섯째를 찾는다.<br><br>
    찾다 못하면 하나를 데려가 여섯을 만들 것이다. 노래가 그렇게 끝난다.`,
  o:[
    { l:'① 대열을 갈라 셈을 흐린다.', k:'fix', dc:15,
      doom:{ title:'여섯째 자리', what:'성가대석으로 끌려 올라갑니다', dc:15, sec:55,
        text:`다섯을 둘과 셋으로 나눠 멀찍이 세웠다. 노래가 하나, 둘에서 멈췄다. 셈이 흐트러졌다. 됐다.<br><br>노래가 다시 셌다. 이번에는 둘과 셋을 따로. 그리고 이쪽을 셌다. 어느 쪽에도 안 든 사람.<br>여섯째. 입들이 일제히 이쪽을 불렀다.<br><br>발이 둥근 천장에서 떨어진다. 위로. 성가대석에서 손이 수십 개 내려온다.`,
        dieText:`노래가 끝났다. 여섯까지 셌다.<br><br>성가대석 맨 끝자리에 새 대원이 섰다. 입이 하나다. 아직은.<br>그 입이 노래 대신 무언가를 센다. 아무도 못 알아듣는 셈이다.` },
      ok:`다섯을 둘과 셋으로 나눠 세웠다. 이쪽은 셋 쪽에 섞였다. 판 밖에 서지 않았다.<br><br>노래가 하나, 둘을 세고 다시 하나, 둘, 셋을 셌다. 다섯은 안 나온다. 다섯이 안 나오면 여섯도 안 나온다.<br>노래가 처음으로 돌아가는 사이 다들 성가대석 밑을 벗어났다.<br><br>판을 흐릴 때는 셈하는 사람도 판 안에 있어야 한다. 밖에 있으면 혼자 세어진다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 귀를 막고 셈 없이 지나간다.', k:'steady', dc:14,
      ok:`다들 귀를 막게 했다. 숫자를 듣지 않으면 숫자에 안 든다.<br><br>성가대석 밑을 지나는 동안 입들이 소리 없이 벙긋거렸다. 다섯, 여섯.<br>아무도 대답하지 않았다.`,
      ng:`귀를 막았는데 하나가 손을 뗐다. 팔이 저려서.<br><br>그 사람이 다섯을 들었다. 대답했다. 저도 모르게.<br>입들이 그쪽을 향했다. 다 같이 그 사람을 끌고 뛰었다.`,
      win:{ exp:16, mind:5 }, lose:{ mind:-10, spirit:-11 } }
  ] },

{ at:'C4', t:'포자 온실 — 뿌리 여덟, 손 다섯',
  x:`온실 한가운데 덩이가 있다. 방 하나만 하다. 뿌리 여덟이 사방으로 뻗었다.<br><br>
    뿌리 하나를 자르면 나머지 일곱이 굵어진다. 물을 나눠 먹던 것이 일곱으로 가니까.<br>
    그렇다고 한꺼번에 여덟을 자를 손은 없다. 손은 다섯이다.<br><br>
    뿌리마다 굵기가 다르다. 굵은 것과 가는 것이 짝을 지어 있다.`,
  o:[
    { l:'① 뿌리 자를 순서를 짠다.', k:'fix', dc:15, wake:1,
      ok:`짝을 봤다. 굵은 것은 가는 것에게서 물을 받는다. 가는 것부터 자르면 굵은 것이 마른다.<br><br>가는 것 넷을 동시에 잘랐다. 굵은 넷이 굵어지지 않고 시들었다. 물 줄 짝이 없다.<br>시든 넷은 칼 한 번에 끊어졌다. 덩이가 처음으로 쪼그라들었다.<br><br>여덟을 여덟으로 세지 않았다. 넷으로 셌다. 이어진 것은 하나로 센다. 그러니 손 다섯이 모자라지 않았다. 셈하는 눈이 이제 이어진 데를 먼저 찾는다.`,
      ng:`가는 것부터 잘랐는데 짝이 틀렸다. 굵은 것 하나는 가는 것 둘에게서 받고 있었다.<br><br>굵은 것이 남은 하나에게서 물을 다 빨았다. 더 굵어졌다. 휘둘렀다.<br>둘이 화단까지 날아갔다. 이쪽도 그중 하나다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-17, mind:-6 } },
    { l:'② 밑동에 불을 놓는다.', k:'break', dc:15,
      ok:`남은 등잔 기름을 덩이 밑동에 붓고 불을 붙였다.<br><br>덩이가 오그라들었다. 뿌리가 불을 피해 땅속으로 숨는다. 숨는 뿌리는 싸우지 않는다.<br>노란 가루가 불에 타며 단내를 냈다. 다들 멀리 물러섰다.`,
      ng:`불이 붙는 순간 덩이가 가루를 뿜었다.<br><br>가루가 불에 닿아 펑 터졌다. 앞머리와 눈썹이 탔다.<br>불은 금방 꺼졌다. 덩이는 그대로다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'③ 뿌리를 따라가 물 대는 데를 찾는다.', k:'sense', dc:14,
      ok:`제일 굵은 뿌리를 따라갔다. 온실 구석 물통으로 들어간다. 빗물받이다.<br><br>물통 마개를 뽑았다. 물이 바닥으로 쏟아졌다. 뿌리가 마른 입처럼 벌어졌다.<br>물통 바닥에 물고기가 몇 마리 남아 퍼덕였다. 정원사들이 빗물받이에 길러 먹던 모양이다.`,
      ng:`뿌리를 따라가다 뿌리가 움직였다. 이쪽 발목을 감았다.<br><br>덩이 쪽으로 반 걸음 끌려갔다. 칼로 끊었다.<br>끊긴 뿌리가 발목에 붙은 채 꿈틀거렸다.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ hp:-13, spirit:-7 } }
  ] },

{ at:'C', t:'쉬는 자리 — 두 판',
  x:`쉬는 자리에서 일행 둘이 다툰다. 다음 사냥을 어떻게 할지.<br><br>
    하나는 기다렸다 덮치자고 하고, 하나는 먼저 쫓자고 한다. 둘 다 반쯤 맞다.<br>
    판이 둘이면 사냥이 둘로 갈린다. 갈린 사냥은 둘 다 진다.<br><br>
    둘이 이쪽을 본다. 골라 달라는 눈이다.`,
  o:[
    { l:'① 두 판을 하나로 묶는다.', k:'fix', dc:14, wake:1,
      ok:`고르지 않았다. 기다리자는 쪽에 기다리는 자리를 맡기고, 쫓자는 쪽에 쫓는 자리를 맡겼다. 쫓아서 기다리는 데로 모는 판이다.<br><br>둘이 서로를 봤다. 제 판이 반쪽씩 들어 있다. 둘 다 고개를 끄덕였다.<br>다음 사냥은 짠 대로 됐다.<br><br>남의 판 둘을 하나로 꿰맸다. 이쪽 판은 하나도 안 넣었다. 판을 짜는 일이 판을 고르는 일보다 넓다는 걸 이번에 알았다.`,
      ng:`묶자고 했는데 둘 다 제 쪽이 앞이어야 한다고 했다.<br><br>다툼이 셋이 됐다. 이쪽까지.<br>결국 아무 판 없이 사냥에 들어갔다. 다들 조금씩 다쳐서 나왔다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-10, spirit:-7 } },
    { l:'② 제비를 뽑게 한다.', k:'luck', dc:13,
      ok:`돌 두 개를 쥐고 하나를 고르게 했다. 흰 돌이 나왔다. 기다리는 판.<br><br>진 쪽도 군말이 없었다. 제비는 아무 편도 아니다.<br>기다리는 판이 맞았다. 운이 좋았다.`,
      ng:`검은 돌이 나왔다. 쫓는 판.<br><br>쫓다가 놓쳤다. 기다리자던 쪽이 아무 말도 안 했다. 그게 더 무거웠다.<br>다음 쉬는 자리까지 아무도 이쪽과 말을 안 섞었다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-9, spirit:-6 } }
  ] },

{ at:'C', t:'사냥 뒤 — 먹어도 되는 살',
  x:`잡은 것을 갈랐다. 안쪽 살은 멀쩡해 보인다. 짐승 고기 색이다.<br><br>
    다들 배가 고프다. 가져온 것은 반 끼밖에 안 남았다.<br>
    먹어도 되는지는 모른다. 여기 것들은 겉이 멀쩡해도 속이 다르다.<br><br>
    다 같이 틀리면 업어 줄 사람이 없다.`,
  o:[
    { l:'① 순서를 정해 맛보게 한다.', k:'fix', dc:14,
      ok:`한 사람만 손톱만큼 구워 씹게 했다. 이쪽이 맡았다. 정한 사람이 맡는 게 순서다.<br><br>한 식경 기다렸다. 혀가 멀쩡하다. 배도 멀쩡하다.<br>그다음에 조금 더, 그다음에 다 같이. 순서가 배를 채웠다.`,
      ng:`한 식경 뒤 이쪽 손끝이 저렸다. 혀가 굳는다.<br><br>남은 고기는 다 버렸다. 이쪽은 한나절 앓았다.<br>첫 사람이 이쪽이라 다행이었다. 그렇게 셈하기로 했다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-13, mind:-6 } },
    { l:'② 소금에 절여 하룻밤 둔다.', k:'heal', dc:14,
      ok:`남은 소금을 다 써서 고기를 절였다. 하룻밤 두기로 했다.<br><br>아침에 보니 고기 표면에 하얀 실이 몇 가닥 나왔다가 말라 죽어 있다. 소금이 이겼다.<br>실을 긁어내고 구웠다. 먹을 만했다.`,
      ng:`아침에 보니 소금 위로 실이 덮여 있다.<br><br>소금이 모자랐다. 고기도 소금도 다 버렸다.<br>배가 고픈 채로 떠났다.`,
      win:{ exp:15, dream:1, hp:6 }, lose:{ hp:-9, mind:-7 } },
    { l:'③ 그것이 모아 둔 먹이를 뒤진다.', k:'luck', dc:14,
      ok:`그것의 굴을 뒤졌다. 먹다 남긴 것들 사이에 버섯이 쌓여 있다. 그것이 모아 둔 것이다.<br><br>짐승은 독 있는 것을 안 모은다. 그것도 짐승이다. 아마.<br>버섯은 멀쩡했다.`,
      ng:`굴 안에 먹다 남긴 것이 무엇인지 봤다.<br><br>사람 장화다. 안에 아직 발이 있다.<br>아무도 그날 밤 먹지 않았다.`,
      win:{ exp:15, dream:2, item:'야생 버섯' }, lose:{ mind:-8, spirit:-10 } }
  ] },

{ at:'C', t:'어둠 — 무거운 셈',
  x:`셈은 숫자를 남긴다. 다친 횟수, 잃은 것, 거의 잃을 뻔한 것.<br><br>
    오늘 셈이 무겁다. 판대로 했는데 둘이 크게 다쳤다. 판이 틀린 데는 없다. 그래도 다쳤다.<br>
    틀리지 않은 판에서 다친 것은 누구 몫인지 셈이 안 된다.<br><br>
    그 숫자를 혼자 쥐고 있다. 손이 무겁다.`,
  o:[
    { l:'① 오늘 판을 다 같이 펼쳐 본다.', k:'fix', dc:14,
      ok:`오늘 판을 바닥에 다시 그렸다. 다들 보게 했다. 어디서 누가 다쳤는지.<br><br>다친 사람 하나가 손가락으로 짚었다. 여기서 제가 한 걸음 더 나갔다고. 판에 없던 한 걸음이다.<br>셈이 맞춰졌다. 누구 탓도 아니다. 다음 판에 한 걸음을 넣으면 된다.<br><br>쥐고 있던 숫자를 내려놓았다. 손이 가벼워졌다.`,
      ng:`펼쳤는데 다들 말이 없다.<br><br>말이 없는 판이 제일 무겁다. 아무도 짚지 않았다.<br>숫자는 다시 이쪽 손으로 돌아왔다.`,
      win:{ exp:18, dream:2, spirit:7 }, lose:{ mind:-9, spirit:-9 } },
    { l:'② 셈을 접고 잔다.', k:'steady', dc:13,
      ok:`셈을 접었다. 오늘 셈은 내일 아침에 다시 한다.<br><br>누웠다. 숫자가 눈꺼풀 뒤에서 한참 돌다 멈췄다.<br>아침에 다시 세니 덜 무거웠다.`,
      ng:`접었는데 접히지 않는다. 누워서도 센다.<br><br>둘, 하나, 셋. 다친 횟수가 꿈에서 늘어난다.<br>아침에 눈이 벌겋다.`,
      win:{ exp:13, mind:6 }, lose:{ mind:-8, spirit:-7 } }
  ] },

{ at:'C', t:'나가는 길 — 벽에 남긴 판',
  x:`나가는 문 앞이다. 다섯이 다 섰다. 다들 어딘가 다쳤다. 그래도 다섯이다.<br><br>
    문 옆 벽에 앞사람들이 남긴 자국이 있다. 숯으로 그은 줄. 몇 명이 들어와 몇 명이 나갔는지.<br>
    대개 나간 쪽이 적다.<br><br>
    전술가는 나가는 길에도 셈을 남긴다. 다음에 올 사람 몫이다.`,
  o:[
    { l:'① 오늘 판을 벽에 그려 남긴다.', k:'fix', dc:14,
      ok:`숯으로 오늘 판을 그렸다. 갈고리 박, 소금, 좁은 목, 뿌리 짝. 쓸 만한 것만.<br><br>맨 끝에 다섯 줄을 긋고 옆에 다섯 줄을 또 그었다. 들어온 다섯, 나간 다섯.<br>앞사람들 줄 가운데 처음으로 같은 수다.<br><br>판은 남이 쓸 때 판이다. 벽에 걸어 두고 나왔다.`,
      ng:`그리는데 숯이 부러졌다. 손이 떨려서.<br><br>반만 그렸다. 반 판은 다음 사람을 더 헷갈리게 한다. 지웠다.<br>나오는 길에 문틀에 손등을 찧었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-8, mind:-7 } },
    { l:'② 앞사람들 셈을 읽는다.', k:'gaze', dc:14,
      ok:`앞사람들 줄을 읽었다. 대개 셋째 문에서 줄었다. 아까 이쪽이 피해 온 문이다.<br><br>그 문에 숯으로 가위표를 그었다. 그리고 나왔다.<br>셈은 앞사람이 하고 이쪽이 맞췄다.`,
      ng:`읽다 보니 맨 마지막 줄이 방금 그은 듯 새것이다.<br><br>들어온 줄이 여섯. 나간 줄이 다섯. 이쪽 일행보다 하나 많다.<br>세어 보니 다섯이다. 문을 나올 때까지 세 번을 셌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-8, spirit:-10 } }
  ] }

]);

// ── 부여술사 ────────────────────────────
kJob('enchanter', 'C', [

{ at:'C', t:'첫 방 — 부여를 먹는 벽',
  x:`이 안의 것들은 살아 있다. 벽도, 바닥도, 문고리도. 손을 대면 미지근하다.<br><br>
    부여는 물건에 덧입히는 일이다. 산 것에 입히면 산 것이 그걸 먹는다. 입힌 것이 금방 녹아 없어진다.<br>
    일행 칼에 날카로움을 입혀 두려고 했다. 그런데 칼날에 벌써 이곳 진물이 묻었다.<br><br>
    진물 묻은 날은 산 것과 반쯤 같다.`,
  o:[
    { l:'① 마력을 써서 날 끝에만 날카로움을 입힌다.', k:'fix', dc:15, cost:{ mana:18 }, wake:1,
      ok:`날 전체에 입히지 않았다. 날 끝 한 줄에만. 실 한 가닥 너비로 마력을 좁혔다.<br><br>진물이 묻은 데는 건너뛰고 마른 쇠에만 박았다. 좁게 입힌 것은 녹을 데가 적다.<br>사냥이 끝나고 봐도 날 끝이 푸르게 서 있다.<br><br>넓게 덮는 것만 부여인 줄 알았다. 좁게 박는 것도 부여다. 마력이 바늘처럼 가늘어질 수 있다는 걸 손끝이 처음 알았다.`,
      ng:`좁히다가 마력이 흩어졌다. 진물 쪽으로 흘렀다.<br><br>진물이 마력을 먹고 부풀었다. 칼날에 하얀 혹이 맺혔다.<br>긁어냈다. 칼은 원래보다 무뎌졌다. 이쪽 손끝도 저리다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-10, spirit:-8 } },
    { l:'② 벽이 먹은 부여의 흔적을 본다.', k:'gaze', dc:14,
      ok:`벽을 봤다. 덧입혔다 녹은 자국이 군데군데 있다. 앞사람들 것이다.<br><br>문틀만 자국이 없다. 문틀은 죽은 나무다. 여기서 유일하게 안 산 것이다.<br>문틀 조각을 떼어 냈다. 거기 입힌 것은 녹지 않을 것이다.`,
      ng:`자국을 보는데 자국이 이쪽을 본다.<br><br>녹은 부여가 벽 속에서 눈처럼 뭉쳐 있다. 마력 쓰는 사람을 알아본다.<br>눈을 돌렸다. 한참 관자놀이가 쑤셨다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-8, spirit:-9 } }
  ] },

{ at:'C1', t:'도축장 — 아묾을 입힌 고기',
  x:`도축장 고기는 자르면 다시 붙는다. 숨 열 번이면 붙는다.<br><br>
    일행이 고기 짐승과 싸운다. 벨 때마다 붙는다. 칼이 지친다. 팔이 지친다.<br>
    부여술사 눈에는 붙는 것이 보인다. 잘린 자리에 덧입혀진 것이 있다. 아묾이다. 누군가 이 도축장 고기에 통째로 입혀 놓았다.<br><br>
    입힌 것은 입힌 것으로 막을 수 있다.`,
  o:[
    { l:'① 마력을 써서 칼에 아물지 않음을 입힌다.', k:'fix', dc:15, cost:{ mana:20 }, wake:1,
      ok:`일행 칼 셋을 차례로 쥐고 마력을 먹였다. 아묾을 거꾸로 짜서. 벤 자리는 닫히지 않는다.<br><br>칼이 들어갔다. 실이 뻗었다. 뻗다가 멈췄다. 잘린 자리가 서로를 못 찾는다.<br>셋째 칼질에 짐승이 두 동강 났다. 다시 안 붙었다.<br><br>남이 입힌 것을 읽고 그 반대를 입혔다. 입히는 일이 대답하는 일이 됐다. 저쪽 부여가 묻고 이쪽 부여가 답했다.`,
      ng:`거꾸로 짠다는 게 반만 거꾸로 됐다. 칼에 아묾이 입혀졌다.<br><br>벤 자리가 더 빨리 붙는다. 칼이 살에 붙어 안 빠진다.<br>칼을 버리고 물러났다. 짐승이 칼을 품은 채 따라왔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-15, mind:-8 } },
    { l:'② 칼을 불에 달궈 지진다.', k:'break', dc:14,
      ok:`횃불에 칼을 달궜다. 시뻘겋게.<br><br>벤 자리를 지졌다. 지진 살은 실을 못 뻗는다.<br>오래 걸렸다. 그래도 붙지 않았다. 도축장에 고기 굽는 냄새가 났다.`,
      ng:`달구는 동안 짐승이 기다리지 않았다.<br><br>달군 칼을 든 사람을 덮쳤다. 칼이 떨어지며 이쪽 정강이를 지졌다.<br>살 타는 냄새가 났다. 이쪽 살이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-5 } }
  ] },

{ at:'C1', t:'도축장 — 찾는 갈고리',
  x:`쇠줄 갈고리 중에 몇 개가 줄을 벗어나 움직인다. 공중에서 사람 쪽으로 기운다.<br><br>
    쇠는 스스로 안 움직인다. 눈을 가늘게 뜨면 갈고리마다 덧입힌 것이 보인다. 찾음이다. 걸 것을 찾음.<br>
    오래된 부여다. 겹겹이 두껍다. 도축장이 생길 때부터 입혀 놓은 것 같다.<br><br>
    갈고리 하나가 이쪽 목 높이에서 멈췄다.`,
  o:[
    { l:'① 갈고리의 부여를 벗긴다.', k:'fix', dc:15,
      doom:{ title:'찾던 것', what:'갈고리에 걸려 줄 위로 끌려갑니다', dc:15, sec:60,
        text:`갈고리 끝을 손가락으로 짚고 찾음을 한 겹씩 벗겼다.<br><br>세 겹째에서 부여가 이쪽 손가락으로 옮겨 붙었다. 찾음이 이쪽을 찾았다. 갈고리가 손바닥을 꿰었다.<br>줄이 당긴다. 몸이 들린다. 찾던 것을 찾은 갈고리가 기뻐하듯 떨린다.<br><br>천장 줄 쪽으로 올라간다. 줄 끝 어둠에서 칼질 소리가 난다.`,
        dieText:`쇠줄이 돈다. 갈고리마다 무언가 걸려 있다.<br><br>그중 하나는 갈고리 끝에 사람 손가락 자국이 남아 있다. 부여를 벗기려던 손가락이다.<br>그 갈고리는 더는 사람 쪽으로 기울지 않는다. 찾던 것을 찾았으니까.` },
      ok:`갈고리 끝을 손가락으로 짚고 찾음을 한 겹씩 벗겼다.<br><br>세 겹째가 이쪽 손가락으로 옮겨 오려 했다. 옮겨 오는 가닥부터 끊었다.<br>갈고리가 축 늘어졌다. 그냥 쇠다. 다른 갈고리들도 차례로 벗겼다.<br><br>벗겨 낸 찾음이 손바닥에 남았다. 쥐고 있으면 무언가를 찾는 느낌이 난다. 버렸다. 여기서 찾을 만한 것은 없다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 걸린 고깃덩이 사이로 숨어 지나간다.', k:'evade', dc:14,
      ok:`걸린 고깃덩이 사이에 몸을 붙였다. 고기를 방패 삼아.<br><br>갈고리가 찾는 것은 걸 것이다. 고기는 이미 걸려 있다. 고기 옆은 못 본다.<br>줄 끝까지 고기 사이를 옮겨 다녔다.`,
      ng:`붙은 고깃덩이가 이쪽 등을 감았다. 자라는 고기다.<br><br>떼어 내느라 버둥대는 사이 빈 갈고리가 찾아왔다. 어깨를 긁었다.<br>고기 냄새가 살에 뱄다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-7 } }
  ] },

{ at:'C2', t:'인형 공방 — 사기 살갗',
  x:`이빨 난 인형이 일어섰다. 무릎 높이다. 열둘.<br><br>
    칼이 사기 살갗에 튕긴다. 깨져야 할 사기가 안 깨진다.<br>
    가만히 보면 보인다. 살갗마다 단단함이 입혀져 있다. 사기는 원래 무른 것이다. 무른 것에 입힌 단단함은 얇게 떠 있다.<br><br>
    얇은 것은 뒤집기 쉽다.`,
  o:[
    { l:'① 마력을 써서 단단함을 무름으로 뒤집는다.', k:'fix', dc:15, cost:{ mana:18 },
      ok:`가장 가까운 인형 머리에 손을 얹고 마력을 밀었다. 떠 있던 단단함이 뒤집혔다.<br><br>사기가 젖은 흙처럼 물러졌다. 이빨이 손에 닿기 전에 뺐다.<br>하나에 하나씩 얹을 시간은 없다. 바닥에 손바닥을 대고 넓게 흘렸다. 무릎 높이의 것들이 다리부터 주저앉았다.<br><br>무너진 사기 속에서 이빨만 멀쩡히 남아 딸깍거렸다.`,
      ng:`뒤집는데 단단함이 이쪽 손으로 넘어왔다. 손가락이 굳는다.<br><br>굳은 손가락으로는 마력이 안 나간다. 인형 하나가 그 손을 물었다.<br>이빨 자국이 굳은 손가락에 하얗게 남았다. 아픈 건 한참 뒤에 왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-13, mind:-8 } },
    { l:'② 사기 이음매를 찾아 짚어 준다.', k:'gaze', dc:14,
      ok:`인형은 굽기 전에 이어 붙인다. 목, 어깨, 허리. 이음매에는 단단함이 덜 먹는다.<br><br>일행에게 목을 치라고 했다. 칼이 이음매로 들어갔다. 머리가 떨어졌다.<br>떨어진 머리가 바닥에서 계속 딸깍인다. 밟았다.`,
      ng:`이음매를 짚는데 인형이 고개를 돌려 이음매를 감췄다.<br><br>저것도 저 약한 데를 안다.<br>치는 칼이 다 튕겼다. 튕긴 칼에 일행 하나가 베였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-6 } },
    { l:'③ 쇠망치로 내리친다.', k:'break', dc:15,
      ok:`공방 구석에서 쇠망치를 찾았다. 무겁다.<br><br>단단함은 날을 튕긴다. 무게는 못 튕긴다. 내리치자 인형이 바닥째 부서졌다.<br>망치를 돌려 가며 셋을 부쉈다. 팔이 빠질 것 같다.`,
      ng:`망치를 드는 사이 인형 둘이 다리에 매달렸다.<br><br>이빨이 종아리로 들어왔다. 망치를 놓쳤다.<br>일행이 떼어 줬다. 종아리에 동그란 이빨 자국이 둘.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-5 } }
  ] },

{ at:'C2', t:'인형 공방 — 실에 걸린 손목',
  x:`천장에서 실이 내려와 일행 손목에 감겼다. 하나, 둘, 셋.<br><br>
    실이 당긴다. 감긴 팔들이 칼을 든 채 저희끼리 겨눈다. 위층 어딘가에서 누가 줄을 조종한다.<br>
    실에도 덧입힌 것이 있다. 놓지 않음. 끊으려면 칼이 필요한데, 칼 든 손이 묶여 있다.<br><br>
    실보다 먼저 손목을 바꾸면 된다.`,
  o:[
    { l:'① 마력을 써서 손목에 미끄러움을 입힌다.', k:'fix', dc:15, cost:{ mana:16 }, wake:1,
      ok:`감긴 손목을 하나씩 짧게 쥐고 미끄러움을 흘렸다. 살갗 위에 기름 한 겹 같은 것을.<br><br>실이 놓지 않음을 쥐고 있어도 쥘 데가 미끄러지면 소용없다. 손목들이 하나씩 실 고리에서 빠져나왔다.<br>빠진 손들이 바로 실을 잘랐다.<br><br>물건에 입힌 것은 그 물건을 바꾼다. 사람 살갗에 입힌 것은 그 사람이 할 수 있는 일을 바꾼다. 그 차이를 손바닥이 처음으로 확실히 알았다.`,
      ng:`미끄러움을 입혔는데 실이 아니라 칼자루가 미끄러졌다.<br><br>칼 셋이 바닥에 떨어졌다. 실은 그대로다. 빈손이 된 팔들이 이쪽 목을 향해 뻗었다.<br>목을 할퀴고서야 다른 일행이 실을 끊었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, spirit:-9 } },
    { l:'② 실을 불로 태운다.', k:'break', dc:14,
      ok:`횃불을 실 다발 밑에 댔다. 놓지 않음은 손을 놓지 않는다. 불은 안 놓을 수 없다.<br><br>실이 타며 오그라들었다. 탄 끝이 위로 달아났다.<br>손목에 탄 자국이 남았다. 묶인 것보다는 낫다.`,
      ng:`불을 대자 실이 불을 피해 다른 데를 감았다. 이쪽 팔이다.<br><br>타다 만 실이 뜨거운 채로 감겼다. 살갗이 데었다.<br>떼어 내는 데 한참.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 금 간 방패',
  x:`사냥을 하나 끝냈다. 쉬는 자리에서 장비를 봤다.<br><br>
    방패 하나가 금이 갔다. 앞에 서는 사람 방패다. 그것의 발톱이 박혔던 자리에서 금이 세 갈래로 뻗었다.<br>
    다음 사냥에서 저 방패가 깨지면 앞에 선 사람이 깨진다.<br><br>
    새 방패는 없다.`,
  o:[
    { l:'① 마력을 써서 금에 버팀을 입힌다.', k:'fix', dc:14, cost:{ mana:17 },
      ok:`금 세 갈래를 손가락으로 따라가며 버팀을 흘렸다. 금 안쪽부터 차곡차곡.<br><br>금은 그대로 보인다. 그런데 두드려 보면 소리가 꽉 찼다.<br>방패 주인이 두드려 보고 고개를 끄덕였다.<br><br>고친 게 아니다. 금 간 채로 버티게 했다. 여기서는 그게 더 오래간다.`,
      ng:`버팀이 금을 따라가다 금 끝에서 넘쳤다. 성한 데까지 번졌다.<br><br>성한 데가 버팀을 먹고 뻣뻣해졌다. 뻣뻣한 나무는 잘 쪼개진다.<br>다음 사냥에서 방패가 반으로 갈라졌다. 주인 팔뚝이 찢어졌다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 젖은 가죽끈으로 단단히 감는다.', k:'steady', dc:13,
      ok:`가죽끈을 물에 적셔 금 위로 감았다. 마르면 줄어든다. 줄어들면 조인다.<br><br>한 시진 뒤 끈이 말라 방패를 꽉 조였다.<br>부여는 아꼈다. 마른 가죽도 가끔 부여 노릇을 한다.`,
      ng:`감는 동안 끈이 모자랐다. 세 갈래 중 둘만 감았다.<br><br>나머지 한 갈래가 다음 사냥에서 벌어졌다.<br>방패 끝이 떨어져 나갔다.`,
      win:{ exp:14, mana:6 }, lose:{ hp:-10, mind:-6 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 뜨는 발',
  x:`거꾸로 선 성당에서는 둥근 천장을 밟고 걷는다. 둥글어서 미끄럽다. 갈빗대 사이가 깊다.<br><br>
    게다가 여기서는 발이 가끔 뜬다. 한 걸음에 반 뼘씩. 무게가 위로 당겨진다. 머리 위에 매달린 제단 쪽으로.<br>
    한 사람이 벌써 갈빗대에서 발이 떴다가 겨우 붙잡았다.<br><br>
    신발에 무언가 입혀야 한다.`,
  o:[
    { l:'① 마력을 써서 신발 바닥에 붙음을 입힌다.', k:'fix', dc:15, cost:{ mana:20 }, wake:1,
      ok:`다섯 켤레 밑창을 하나씩 손바닥으로 쓸며 붙음을 먹였다. 너무 붙으면 못 걷는다. 한 걸음 떼는 만큼만 놓아주게.<br><br>신발이 돌에 착 붙었다 떨어졌다 한다. 발이 뜨려 할 때마다 밑창이 붙잡았다.<br>제단 밑을 지날 때 다들 발이 한 번씩 들썩였다. 아무도 안 떴다.<br><br>붙게만 입힌 게 아니라 언제 놓을지도 입혔다. 부여에 때를 넣었다. 덧입힌 것이 저 혼자 숨을 쉰다.`,
      ng:`붙음이 너무 먹혔다. 한 사람 신발이 갈빗대에 붙어 안 떨어진다.<br><br>신발을 벗겼다. 맨발로 남은 길을 갔다. 맨발이 떴다.<br>허리띠를 잡아 내렸다. 그 사람 발바닥이 다 까졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 서로 허리를 줄로 잇는다.', k:'bond', dc:14,
      ok:`밧줄로 다섯 허리를 이었다. 하나가 뜨면 넷이 잡는다.<br><br>제단 밑에서 둘이 동시에 떴다. 셋이 버텼다. 줄이 팽팽해졌다가 풀렸다.<br>다 지났다. 허리마다 줄 자국이 났다.`,
      ng:`셋이 동시에 떴다. 둘로는 못 버틴다.<br><br>줄째 끌려 올라가다 제단 모서리에 걸렸다. 다들 제단 밑에 매달렸다.<br>하나씩 내려오는 데 한 식경. 팔이 다 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-13, mind:-6 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 소리로 사냥하는 종',
  x:`갈빗대 사이에 종이 놓여 있다. 입을 위로 벌리고.<br><br>
    종 안에 사는 것은 소리로 사냥한다. 종을 울려 귀를 멀게 하고, 멀게 한 것을 혀로 감아 들인다.<br>
    천에 고요를 입히면 된다. 소리를 삼키는 천.<br><br>
    종을 덮으려면 천이 종만 해야 한다. 외투 두 벌을 이어야 한다.`,
  o:[
    { l:'① 마력을 써서 외투에 고요를 입혀 덮는다.', k:'fix', dc:15, cost:{ mana:18 },
      ok:`외투 두 벌 소매를 묶어 잇고 고요를 먹였다. 천이 무거워졌다. 소리를 삼킬 자리가 생긴 것이다.<br><br>종 입에 덮었다. 종이 울렸다. 소리가 안 났다. 천만 부르르 떨었다.<br>울려도 안 들리니 종 안의 것이 혀를 내지 못했다. 그 옆을 다섯이 지나갔다.<br><br>외투는 두고 왔다. 덮어 둔 채로. 한참 뒤까지 천이 떨렸다.`,
      ng:`고요를 입혔는데 이음매가 샜다. 소매 묶은 데.<br><br>그 틈으로 종소리가 터져 나왔다. 좁게 모여서 더 날카롭다. 귀가 먹먹하다.<br>먹먹한 사이 혀가 나와 발목을 핥았다. 껍질이 벗겨졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, spirit:-10 } },
    { l:'② 종 안에 손을 넣어 추를 붙잡는다.', k:'break', dc:15,
      doom:{ title:'추 대신', what:'종 속으로 끌려 들어갑니다', dc:15, sec:55,
        text:`종 안에 팔을 넣었다. 추를 잡으면 종이 못 운다.<br><br>추가 아니다. 따뜻하고 젖었다. 손가락이 그것에 닿자 그것이 손가락을 감았다.<br>팔꿈치까지 들어갔다. 어깨까지. 종 안이 생각보다 깊다.<br><br>종이 울리기 시작했다. 안에서. 이쪽 몸을 추 삼아.`,
        dieText:`종이 다시 운다. 그 소리가 전과 조금 다르다.<br><br>추가 바뀌었다. 무거운 추다.<br>종이 울릴 때마다 안에서 무언가 부딪는다. 손바닥 같은 소리로.` },
      ok:`종 안에 팔을 넣었다. 따뜻하고 젖은 것이 손가락을 감았다. 그대로 움켜쥐었다.<br><br>부여는 안 했다. 대신 쥔 손을 놓지 않았다. 그것이 버둥댈수록 종이 울지 못했다. 추를 쥔 셈이다.<br>일행이 종 테두리 틈으로 칼을 박아 넣었다. 그것이 축 늘어졌다.<br><br>팔을 빼니 팔뚝이 붉게 부어 있다. 종 안이 뜨거웠다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'C4', t:'포자 온실 — 올 사이의 막음',
  x:`온실 공기가 노랗다. 숨 쉴 때마다 가루가 들어온다.<br><br>
    가루가 든 사람은 기침을 하다가, 한참 뒤에 기침을 멈춘다. 그때부터 위험하다. 정원사들도 처음엔 기침을 했을 것이다.<br>
    천으로 입을 막아도 가루는 지나간다. 천은 구멍투성이다.<br><br>
    천에 막음을 입히면 된다. 숨은 지나가고 가루는 못 지나가게.`,
  o:[
    { l:'① 마력을 써서 다섯 장의 천에 막음을 입힌다.', k:'fix', dc:15, cost:{ mana:22 },
      ok:`천 다섯 장을 무릎에 펴고 한 장씩 마력을 흘렸다. 올과 올 사이에 막음을. 숨 하나 지나갈 틈만 남기고.<br><br>다섯이 입을 막았다. 숨이 조금 무겁다. 가루는 안 들어온다.<br>온실 한가운데까지 갔다가 나올 때까지 아무도 기침하지 않았다.<br><br>천 바깥쪽이 노랗게 덮였다. 안쪽은 하얗다.`,
      ng:`넷째 장에서 마력이 떨렸다. 올이 고르게 안 막혔다.<br><br>그 천을 쓴 사람이 반 시진 뒤 기침했다. 그러다 멈췄다.<br>멈춘 게 더 무서웠다. 흔들어서 다시 기침하게 했다. 목에서 노란 덩이가 나왔다.`,
      win:{ exp:22, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-10 } },
    { l:'② 숨을 참고 짧게 끊어 간다.', k:'evade', dc:14,
      ok:`열 걸음 가고 숨, 열 걸음 가고 숨. 숨은 화단 그늘 바람 덜 부는 데서 쉬었다.<br><br>바람이 없는 데는 가루도 덜 돈다.<br>지쳤지만 아무도 많이 마시지 않았다.`,
      ng:`그늘에서 숨을 쉬었는데 거기가 더 노랗다.<br><br>바람이 없으니 가루가 고여 있었다.<br>한참 기침했다. 침에 노란 실이 섞였다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-11, spirit:-8 } },
    { l:'③ 젖은 흙을 천에 바른다.', k:'heal', dc:14,
      ok:`화단 가장자리 젖은 흙을 천에 얇게 발랐다. 진흙은 올 사이를 메운다.<br><br>숨이 답답하다. 흙냄새가 난다. 가루는 덜 들어온다.<br>부여는 아꼈다. 땅이 대신 입혀 줬다.`,
      ng:`바른 흙에 이미 가루가 섞여 있었다.<br><br>입에 바로 대고 숨을 쉰 꼴이 됐다. 기침이 터졌다.<br>천을 버렸다. 목이 한나절 따끔거렸다.`,
      win:{ exp:14, dream:1, mind:5 }, lose:{ hp:-10, spirit:-9 } }
  ] },

{ at:'C4', t:'포자 온실 — 정원사의 앞치마',
  x:`정원사가 걷는다. 앞치마, 장화, 챙 넓은 모자. 안은 하얀 실이다.<br><br>
    곰팡이가 옷을 입고 걷는다. 그런데 걸음이 반듯하다. 곰팡이가 반듯하게 걸을 리 없다.<br>
    앞치마에 오래된 부여가 남아 있다. 일함. 진짜 정원사들이 일 잘하라고 입혀 둔 것이다.<br><br>
    곰팡이는 그 부여를 입고 일한다. 사람 대신.`,
  o:[
    { l:'① 앞치마에 남은 부여를 걷어 낸다.', k:'gaze', dc:15, wake:1,
      ok:`정원사가 등을 보일 때 다가가 앞치마 끈을 쥐었다. 일함을 한 올씩 풀었다.<br><br>정원사가 걸음을 멈췄다. 물뿌리개가 떨어졌다. 다리가 꼬였다. 옷 안의 실이 갈 데를 몰라 꿈틀댔다.<br>일행이 덮쳤다. 반듯하지 않은 것은 쉽게 쓰러진다.<br><br>입히지 않고 벗겼다. 남이 남긴 부여를 벗기면 그것을 입은 것이 무너진다. 입히는 손과 벗기는 손이 같은 손이라는 걸 오늘은 싸움에서 썼다.`,
      ng:`끈을 쥐는 순간 정원사가 돌아섰다. 모자 밑 실이 이쪽 얼굴로 쏟아졌다.<br><br>눈을 감았다. 실이 눈꺼풀에 붙었다. 떼어 내자 속눈썹이 같이 뽑혔다.<br>한동안 눈이 부어 앞이 흐렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-13, spirit:-10 } },
    { l:'② 횃불로 옷을 태운다.', k:'break', dc:15,
      ok:`횃불을 앞치마에 갖다 댔다. 마른 천이다. 금방 붙었다.<br><br>옷이 타자 안의 실이 드러났다. 실은 불을 못 견딘다. 정원사가 타며 화단에 쓰러졌다.<br>재 속에서 장화만 남았다.`,
      ng:`불이 붙었는데 정원사가 불붙은 채로 달려왔다.<br><br>불타는 앞치마가 이쪽 팔에 닿았다. 소매에 옮겨 붙었다.<br>굴러서 껐다. 팔에 화상이 길게 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-17, mind:-5 } },
    { l:'③ 쓰러진 정원사 주머니를 턴다.', k:'luck', dc:14,
      ok:`쓰러진 정원사 앞치마 주머니를 뒤졌다. 실 덩이 사이로 손을 넣었다.<br><br>꿀 한 줌이 종이에 싸여 있다. 진짜 정원사가 넣어 둔 것이다. 종이에 이름이 적혀 있다. 반쯤 곰팡이에 먹혔다.<br>꿀은 곰팡이가 안 먹는다.`,
      ng:`주머니에 손을 넣었는데 주머니가 손을 감았다.<br><br>실이 손가락 사이로 파고든다. 뺐다. 손가락 사이가 하얗게 일어났다.<br>며칠은 갈 것 같다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-10, spirit:-9 } }
  ] },

{ at:'C', t:'사냥 — 손톱 비늘',
  x:`큰 것이 나왔다. 가죽 대신 겹친 손톱이 온몸을 덮었다. 비늘처럼.<br><br>
    날은 손톱 사이로만 들어간다. 사이는 좁다. 누가 맞힐지 모른다.<br>
    마력은 한 번 크게 입힐 만큼 남았다. 한 칼에 몰아 입히면 그 칼은 무엇이든 가른다. 그 칼이 빗나가면 끝이다.<br><br>
    다섯이 이쪽을 본다. 누구 칼이냐는 눈이다.`,
  o:[
    { l:'① 마력을 써서 다섯 손에 맞힘을 나눠 입힌다.', k:'fix', dc:15, cost:{ mana:22 }, wake:1,
      ok:`한 칼에 몰지 않았다. 다섯 손등을 차례로 짚으며 마력을 조금씩 흘렸다. 날카로움이 아니라 맞힘을. 손이 사이를 찾게.<br><br>다섯 칼이 다섯 사이로 들어갔다. 하나도 안 빗나갔다. 하나하나는 얕다. 다섯이면 깊다.<br>그것이 손톱을 곤두세우며 쓰러졌다.<br><br>칼을 고르지 않고 손을 골랐다. 손에 입힌 것은 그 손이 쥔 모든 것에 묻는다. 한 번에 다섯으로 나눠 입히는 손이 처음으로 떨리지 않았다.`,
      ng:`나누다 보니 다섯째 손에 닿을 마력이 없다.<br><br>넷이 맞히고 하나가 빗나갔다. 빗나간 칼이 손톱에 튕겨 옆 사람 허벅지를 그었다.<br>그것은 쓰러졌다. 피도 많이 났다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-15, mind:-8 } },
    { l:'② 마력을 써서 창 하나에 몰아 입힌다.', k:'break', dc:15, cost:{ mana:20 },
      ok:`창 든 사람 창날을 두 손으로 감싸고 남은 마력을 다 밀어 넣었다. 창날이 하얗게 섰다.<br><br>그 사람이 숨을 고르고 던졌다. 손톱 사이가 아니라 손톱째 꿰뚫었다.<br>이쪽은 주저앉았다. 손이 차갑다.`,
      ng:`던진 창이 빗나갔다. 반 뼘.<br><br>하얗게 선 창날이 벽을 가르고 들어갔다. 꺼낼 수 없다.<br>빈손으로 싸웠다. 다들 크게 다쳤다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-17, mind:-6 } },
    { l:'③ 손톱이 겹친 결을 읽어 준다.', k:'gaze', dc:14,
      ok:`손톱이 겹친 결을 봤다. 위에서 아래로 겹친다. 기와처럼.<br><br>아래에서 위로 찌르면 결을 거슬러 들어간다. 그렇게 말해 줬다.<br>밑에서 올려 찌른 칼들이 다 들어갔다.`,
      ng:`결을 보는데 손톱이 결을 바꿨다. 아래에서 위로.<br><br>밑에서 찌른 칼이 다 튕겼다. 튕긴 칼들 사이로 그것이 몸을 굴렸다.<br>둘이 깔렸다. 끌어내는 데 이쪽 팔이 손톱에 쓸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 앞치마와 칼',
  x:`작업장 안쪽에 앞치마 두른 큰 것이 서 있다. 팔이 넷. 칼질이 안 멈춘다.<br><br>
    앞치마는 한 번도 안 더러워졌다. 피가 튀어도 흘러내린다. 칼은 한 번도 안 무뎌졌다.<br>
    둘 다 부여다. 앞치마에는 더럽혀지지 않음, 칼에는 멈추지 않음.<br><br>
    칼의 부여가 저것을 움직인다. 칼이 멈추면 저것도 멈춘다.`,
  o:[
    { l:'① 칼의 부여를 긁어낸다.', k:'fix', dc:15,
      ok:`칼이 내려가는 순간을 기다렸다가 칼등에 손바닥을 댔다. 칼이 지나가는 사이 멈추지 않음을 한 겹 긁어냈다.<br><br>칼이 처음으로 멈칫했다. 다음 칼질이 반 박 늦었다. 그다음은 한 박.<br>칼이 무거워지자 저것도 무거워졌다. 일행이 늦어진 칼질 사이로 들어갔다.<br><br>긁어낸 것이 손바닥에서 계속 움직이려 한다. 털어 냈다. 바닥에서 한참 꿈틀댔다.`,
      ng:`칼등에 손을 대는 데 반 박 늦었다.<br><br>칼날이 손바닥 가장자리를 갈랐다. 피가 앞치마에 튀었다. 흘러내렸다.<br>손을 싸쥐고 물러났다. 칼질은 그대로다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 뒤로 돌아가 앞치마 끈을 자른다.', k:'hide', dc:14,
      ok:`칼질 뒤로 돌아갔다. 앞치마 끈이 등 뒤에서 묶여 있다.<br><br>끈을 잘랐다. 앞치마가 흘러내렸다. 더럽혀지지 않음이 벗겨졌다. 저것 몸에 피가 묻기 시작했다.<br>피 묻은 것은 미끄러진다. 저것이 제 피에 미끄러져 넘어졌다.`,
      ng:`끈을 자르는데 끈이 칼을 튕겼다. 끈에도 무언가 입혀져 있다.<br><br>소리가 났다. 저것이 돌아봤다. 팔 넷이 동시에.<br>바닥을 굴러 피했다. 등에 칼자국이 하나 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, spirit:-6 } }
  ] },

{ at:'C2', t:'인형 공방 — 살 같음을 입힌 끌',
  x:`작업대 위에 연장이 놓여 있다. 끌, 붓, 작은 칼. 손때가 묻었다.<br><br>
    끌에 부여가 있다. 살 같음. 이 끌로 깎은 사기는 살처럼 움직인다. 이빨 난 인형들이 다 이 끌에서 나왔다.<br>
    끌 손잡이가 따뜻하다. 방금까지 누가 쥐고 있었다.<br><br>
    위층에서 발소리가 난다. 내려오려 한다.`,
  o:[
    { l:'① 마력을 써서 끌에 정직함을 덮는다.', k:'fix', dc:15, cost:{ mana:16 },
      ok:`끌을 쥐고 살 같음 위에 정직함을 덮었다. 깎는 대로만 깎이게. 다른 것 같지 않게.<br><br>작업대 위 빚다 만 인형 머리를 끌로 한 번 긁었다. 사기가 사기답게 부서졌다. 꿈틀대지 않았다.<br>끌은 제자리에 두고 나왔다. 위층에서 내려온 것이 이 끌로 다음 인형을 깎을 것이다. 그 인형은 그냥 사기일 것이다.`,
      ng:`정직함을 덮는데 살 같음이 이쪽 손으로 기어올랐다.<br><br>손가락 끝이 사기처럼 하얘졌다. 굽혀지지 않는다.<br>끌을 놓고 한참 주물렀다. 손끝이 겨우 분홍으로 돌아왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, spirit:-9 } },
    { l:'② 끌을 부러뜨린다.', k:'break', dc:14,
      ok:`끌을 작업대 모서리에 대고 내리쳤다. 쇠가 부러졌다.<br><br>부러진 끌에서 부여가 새어 나와 흩어졌다. 공방 인형들이 동시에 한 번 떨었다.<br>그다음부터 인형들 움직임이 굼떴다. 끌이 저것들의 숨이었던 모양이다.`,
      ng:`내리쳤는데 끌이 안 부러지고 손이 미끄러졌다.<br><br>끌 끝이 손목 안쪽을 찔렀다. 피가 끌에 묻자 끌이 따뜻해졌다.<br>던져 버렸다. 손목이 한참 욱신거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C', t:'어둠 — 마력을 마시는 것',
  x:`어둠 속에서 무언가 다가온다. 안 보인다. 다만 마력이 빠져나간다.<br><br>
    손끝에서 실처럼 풀려 나간다. 이쪽에서. 이쪽만.<br>
    마력 쓰는 사람이 이쪽밖에 없다. 저것은 그 냄새를 맡고 온다.<br><br>
    다 빨리면 이쪽은 빈 그릇이다. 빈 그릇으로는 아무것도 못 입힌다.`,
  o:[
    { l:'① 마력을 가슴에 접어 잠근다.', k:'steady', dc:15,
      ok:`마력을 가슴 한가운데로 모아 접었다. 손끝까지 나가던 것을 거둬들였다.<br><br>풀려 나가던 실이 끊겼다. 다가오던 것이 멈췄다. 냄새가 없어졌다.<br>한참 뒤 그것이 다른 데로 기어갔다. 그동안 숨도 크게 안 쉬었다.`,
      ng:`접으려는데 손끝 실이 안 끊긴다. 저쪽이 쥐고 있다.<br><br>당기는 대로 끌려 나갔다. 반이 빠졌다. 머리가 하얘진다.<br>일행이 이쪽 손을 감싸 쥐고서야 실이 끊겼다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-11, spirit:-9 } },
    { l:'② 마력을 써서 돌멩이에 입혀 미끼로 던진다.', k:'fix', dc:15, cost:{ mana:15 },
      ok:`돌멩이 하나를 쥐고 마력을 잔뜩 먹였다. 따뜻해질 때까지. 그리고 멀리 던졌다.<br><br>마력 냄새가 저쪽으로 날아갔다. 다가오던 것이 방향을 틀었다. 돌멩이 쪽으로.<br>어둠 저편에서 무언가 돌을 핥는 소리가 났다. 그 사이 다 같이 빠져나왔다.<br><br>입힌 것을 미끼로 썼다. 부여도 던질 수 있다.`,
      ng:`던진 돌멩이가 가까이 떨어졌다. 두 걸음 앞.<br><br>저것이 돌을 핥고, 그다음 이쪽을 핥았다. 미끼와 주인이 너무 가깝다.<br>손등이 차갑게 젖었다. 마력이 한 움큼 빠져나갔다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-10, spirit:-8 } },
    { l:'③ 일행 가운데로 들어가 둘러싸인다.', k:'bond', dc:14,
      ok:`일행 가운데로 들어갔다. 넷이 둘러쌌다. 이쪽 냄새가 넷 냄새에 묻혔다.<br><br>다가오던 것이 넷 앞에서 머뭇거렸다. 마력 없는 사람은 맛이 없다.<br>둘러싸인 채로 걸어서 빠져나왔다.`,
      ng:`둘러쌌는데 그것이 넷 사이로 혀를 넣었다.<br><br>가운데 이쪽 목덜미를 핥았다. 차다. 마력이 한 줌 빠졌다.<br>넷이 칼을 휘두르자 물러났다. 목덜미가 한참 얼얼했다.`,
      win:{ exp:15, spirit:5 }, lose:{ hp:-9, mind:-10 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 입을 만드는 노래',
  x:`매달린 성가대석에서 노래가 내려온다. 입이 너무 많은 노래다.<br><br>
    노래가 귀로 들어와 입을 만든다. 따라 흥얼거리는 사람 턱 밑에서 살이 갈라진다.<br>
    귀에 둔함을 입히면 노래가 덜 들어온다. 덜 듣는 귀는 위험도 덜 듣는다.<br><br>
    성가대석 밑을 지나는 데 백 걸음이다.`,
  o:[
    { l:'① 마력을 써서 다섯 귀에 둔함을 입힌다.', k:'fix', dc:15, cost:{ mana:18 },
      ok:`다섯 귓바퀴를 하나씩 손가락으로 쓸며 둔함을 먹였다. 노래가 솜을 지나는 것처럼 뭉개지게.<br><br>백 걸음 내내 노래가 멀었다. 아무도 흥얼거리지 않았다.<br>대신 서로 말이 안 들렸다. 손짓으로만 걸었다. 그래도 다 지났다.<br><br>나와서 둔함을 벗겨 주자 다들 한꺼번에 말을 했다. 시끄러웠다.`,
      ng:`넷째 귀에서 마력이 미끄러졌다. 둔함이 아니라 밝음이 들어갔다.<br><br>그 사람 귀가 노래를 두 배로 들었다. 턱 밑이 찢어지듯 갈라졌다.<br>입을 막고 끌고 나왔다. 턱 밑에 작은 입 모양 흉이 남았다.`,
      win:{ exp:22, dream:2, spirit:5 }, lose:{ mind:-10, spirit:-12 } },
    { l:'② 모든 입이 쉬는 마디를 찾는다.', k:'sense', dc:14,
      ok:`노래를 들었다. 입이 많아서 숨 쉬는 데도 많다. 그래도 모든 입이 동시에 쉬는 마디가 있다.<br><br>그 마디마다 열 걸음씩 걸었다. 노래가 다시 시작되면 귀를 막고 섰다.<br>느렸다. 아무도 흥얼거리지 않았다.`,
      ng:`쉬는 마디를 찾는데 노래가 마디를 바꿨다. 이쪽이 듣는 걸 알았다.<br><br>귀를 막는 게 늦었다. 이쪽 입에서 흥얼거림이 새어 나왔다.<br>일행이 입을 틀어막았다. 턱 밑이 한참 가려웠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-9, spirit:-11 } }
  ] },

{ at:'C4', t:'포자 온실 — 부여를 먹은 덩이',
  x:`온실 한가운데 덩이. 방 하나만 하다. 뛸 때마다 온실 전체가 부푼다.<br><br>
    덩이 표면에 부여가 덕지덕지 붙어 있다. 정원사 앞치마에서 걷어 간 일함, 유리창에서 걷어 간 막음, 문에서 걷어 간 닫힘. 덩이가 다 먹었다.<br>
    부여를 먹고 자랐다. 마력 냄새를 좋아한다.<br><br>
    덩이 쪽으로 손을 뻗으면 손끝이 저절로 끌린다.`,
  o:[
    { l:'① 덩이에 붙은 부여를 걷어 낸다.', k:'gaze', dc:15,
      doom:{ title:'먹힌 부여', what:'덩이가 마력째 끌어당깁니다', dc:15, sec:55,
        text:`덩이 표면에 손을 대고 남의 부여를 하나씩 걷었다. 일함, 막음.<br><br>닫힘을 걷는데 덩이가 이쪽 손을 닫았다. 손바닥이 표면에 붙었다. 덩이 안으로 마력이 쏟아져 들어간다. 이쪽 것이다.<br>덩이가 기뻐하듯 부풀었다. 붙은 손목이 안으로 들어간다. 팔꿈치까지.<br><br>마력이 다 빠지면 그다음은 몸이다.`,
        dieText:`덩이가 한 번 크게 뛰었다. 온실 유리가 다 울렸다.<br><br>표면에 새 부여가 하나 붙었다. 손바닥 모양이다. 아무것도 입히지 않는 부여다.<br>덩이는 그 손바닥으로 다음에 오는 마력을 부를 것이다.` },
      ok:`덩이 표면에 손을 대고 남의 부여를 하나씩 걷었다. 일함, 막음.<br><br>닫힘을 걷는데 덩이가 이쪽 손을 닫으려 했다. 걷던 닫힘을 그대로 덩이 숨구멍에 거꾸로 붙였다. 덩이가 제 몸을 닫았다.<br>숨을 못 쉬는 덩이가 쪼그라들었다. 뿌리들이 힘없이 늘어졌다.<br><br>일행이 늘어진 뿌리를 다 잘랐다. 먹힌 부여들이 흩어져 공기 속으로 녹았다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 마력을 써서 불씨에 번짐을 입힌다.', k:'break', dc:15, cost:{ mana:20 },
      ok:`부싯돌 불씨 하나에 번짐을 입혔다. 작은 불이 혼자 길을 찾아 퍼지게.<br><br>덩이 밑동에 던졌다. 불이 뿌리를 타고 번졌다. 덩이가 불을 피해 오그라들었다.<br>번짐은 덩이가 먹기 전에 탔다. 불은 먹을 수 없다.`,
      ng:`번짐이 너무 먹혔다. 불이 덩이 아닌 쪽으로도 번졌다.<br><br>화단이 다 탔다. 연기와 가루가 같이 피었다.<br>다들 기침하며 빠져나왔다. 이쪽 소매가 탔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, spirit:-7 } }
  ] },

{ at:'C', t:'쉬는 자리 — 남의 손에 남은 것',
  x:`쉬는 자리에서 일행 손을 봤다. 사냥 전에 입혀 준 맞힘이 아직 남아 있다.<br><br>
    보통은 반 시진이면 벗겨진다. 이건 한나절이 지났다.<br>
    그 사람 손 안에서 맞힘이 그 사람 것처럼 자리를 잡았다. 버릇처럼.<br><br>
    그대로 두면 계속 남을지, 썩을지 모른다.`,
  o:[
    { l:'① 남은 부여를 그 손에 맞게 다듬어 준다.', k:'fix', dc:14, wake:1,
      ok:`그 사람 손을 잡고 남은 맞힘을 짚었다. 이쪽이 입힌 모양이 아니다. 그 사람 손 모양으로 바뀌었다.<br><br>모난 데만 조금 다듬었다. 나머지는 그대로 뒀다. 그 사람 것이니까.<br>그 사람이 손을 쥐었다 폈다. 가볍다고 했다.<br><br>입힌 것은 벗겨지는 줄 알았다. 받는 사람이 제 것으로 삼으면 안 벗겨진다. 부여는 건네는 일이었다. 건넨 다음은 받는 사람 몫이다. 그 몫을 다듬는 손이 생겼다.`,
      ng:`다듬는데 그 사람 손에서 맞힘이 엉켰다.<br><br>손가락이 제멋대로 오그라들었다. 그 사람이 놀라 손을 뺐다.<br>엉킨 것을 다 벗겨 냈다. 손은 돌아왔다. 다음 사냥에서는 아무것도 안 입혀 달라고 했다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-9, spirit:-7 } },
    { l:'② 남은 것을 거둬들인다.', k:'steady', dc:13,
      ok:`남은 맞힘을 손끝으로 감아 거둬들였다. 이쪽 마력으로 돌아왔다. 조금.<br><br>모르는 부여는 남겨 두지 않는다. 그게 안전하다.<br>그 사람 손이 원래대로 돌아왔다.`,
      ng:`거두는데 맞힘이 안 따라온다. 그 사람 손에 너무 깊이 박혔다.<br><br>세게 당겼다. 그 사람이 손을 움켜쥐며 신음했다.<br>반만 거뒀다. 반은 그대로다. 둘 다 찝찝했다.`,
      win:{ exp:14, mana:6 }, lose:{ mind:-8, spirit:-6 } }
  ] },

{ at:'C', t:'사냥 뒤 — 하룻밤이면 자라는 것',
  x:`잡은 것에서 살을 떼어 냈다. 안쪽 살은 짐승 고기 색이다.<br><br>
    여기서는 뭐든 빨리 썩는다. 썩는 게 아니라 자란다. 하얀 실이 하룻밤이면 덮는다.<br>
    가져갈 만큼 떼어 내도 내일이면 못 먹는다.<br><br>
    소금 덩이는 하나 남았다.`,
  o:[
    { l:'① 마력을 써서 소금에 썩지 않음을 입힌다.', k:'fix', dc:14, cost:{ mana:15 },
      ok:`소금 덩이를 두 손으로 쥐고 썩지 않음을 먹였다. 그 소금으로 고기를 문질렀다.<br><br>소금에 입힌 것이 고기로 번졌다. 이튿날 아침에도 하얀 실이 없다.<br>고기는 멀쩡했다. 소금 덩이도 반이 남았다.`,
      ng:`썩지 않음이 소금에만 먹고 고기로 안 번졌다.<br><br>아침에 보니 소금은 멀쩡하고 고기가 하얗게 덮였다.<br>고기를 버렸다. 소금만 챙겼다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-8, mind:-7 } },
    { l:'② 오늘 다 구워 먹는다.', k:'heal', dc:13,
      ok:`내일 걱정은 접었다. 오늘 다 구웠다.<br><br>다섯이 배불리 먹었다. 한동안 처음이다.<br>배부른 다섯은 내일 더 멀리 간다.`,
      ng:`굽는 냄새가 너무 멀리 갔다.<br><br>어둠 속에서 무언가 냄새를 맡고 왔다. 고기를 반쯤 먹다 말고 싸웠다.<br>남은 고기는 그것이 가져갔다.`,
      win:{ exp:14, hp:8 }, lose:{ hp:-12, spirit:-6 } },
    { l:'③ 소금은 아끼고 연기에 그을린다.', k:'luck', dc:14,
      ok:`젖은 나무로 연기를 피워 고기를 그을렸다. 연기 속에서 하얀 실이 오그라들었다.<br><br>그을린 살덩이 사이에서 소금 덩이가 하나 더 굴러 나왔다. 그것의 뱃속에 있던 것이다. 그것도 짐승처럼 소금을 핥았던 모양이다.<br>씻어서 챙겼다.`,
      ng:`연기를 피우는데 연기가 안 빠졌다. 굴이 막혔다.<br><br>다들 눈이 매워 밖으로 뛰쳐나왔다. 고기는 시커멓게 탔다.<br>목이 한참 쓰렸다.`,
      win:{ exp:15, dream:2, item:'소금 덩이' }, lose:{ hp:-9, mind:-6 } }
  ] },

{ at:'C', t:'어둠 — 빈 그릇',
  x:`마력이 다 떨어졌다. 손끝에 아무것도 없다.<br><br>
    앞에 일행 하나가 쓰러져 있다. 다리를 크게 베였다. 피가 멎지 않는다. 묶은 천이 젖어 든다.<br>
    여느 때 같으면 천에 조임을 입혔을 것이다. 지금은 입힐 것이 없다.<br><br>
    부여술사에게서 마력을 빼면 무엇이 남는지, 지금 알아야 한다.`,
  o:[
    { l:'① 손으로만 천을 다시 묶는다.', k:'fix', dc:15, wake:1,
      ok:`젖은 천을 풀고 마른 천으로 다시 감았다. 감을 때 손바닥으로 한 바퀴마다 눌렀다. 마력을 흘리던 그 손짓으로.<br><br>마력은 안 나갔다. 그런데 손이 어디를 눌러야 조이는지 알았다. 입힐 때마다 짚던 자리다. 피가 멎었다.<br><br>마력이 손을 가르친 것이다. 수없이 입히는 동안 손이 물건의 결을 외웠다. 마력이 없어도 결은 남는다. 빈 그릇에도 그릇 모양은 남아 있다.`,
      ng:`손으로 감았는데 어디를 눌러야 할지 모르겠다.<br><br>마력 없이 짚으니 다 똑같다. 천이 또 젖었다.<br>다른 일행이 와서 다시 감았다. 이쪽 손은 피만 묻었다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-10, spirit:-9 } },
    { l:'② 숨을 고르고 마력이 고이기를 기다린다.', k:'steady', dc:14,
      ok:`다친 사람 다리를 높이 올려 두고, 이쪽은 숨을 골랐다. 마력은 쉬면 조금씩 고인다.<br><br>스무 번 숨에 손끝이 미지근해졌다. 그만큼으로 천에 조임을 입혔다. 작게.<br>피가 멎었다.`,
      ng:`숨을 고르는 사이 피가 더 났다.<br><br>고인 마력은 손톱만 했다. 그걸로는 안 된다.<br>다른 일행이 와서 꽉 묶었다. 다친 사람 얼굴이 하얗다.`,
      win:{ exp:15, mana:8 }, lose:{ hp:-10, mind:-7 } }
  ] },

{ at:'C', t:'나가는 길 — 벗기고 나간다',
  x:`나가는 문이 보인다. 다들 지쳤다.<br><br>
    오늘 입힌 것들이 아직 여기저기 남아 있다. 칼에, 신발에, 천에, 손에. 이곳 진물이 그 위에 묻었다.<br>
    진물 묻은 부여는 밖에서 무엇이 될지 모른다. 안에서 먹은 것을 밖으로 데려갈 수 있다.<br><br>
    문 앞에서 다 벗겨 두고 가야 한다.`,
  o:[
    { l:'① 하나씩 짚어 벗겨 낸다.', k:'fix', dc:14,
      ok:`칼, 신발, 천, 손. 다섯 사람 것을 하나씩 짚어 벗겼다. 진물 섞인 것은 손끝으로 털어 문 안쪽에 버렸다.<br><br>오래 걸렸다. 문 앞에서 다들 기다렸다. 아무도 재촉하지 않았다.<br>다 벗기고 나서 문을 나섰다. 바깥 공기가 손에 닿았다. 깨끗하다.`,
      ng:`하나를 빼먹었다. 이쪽 손등.<br><br>문을 나서는데 손등이 따끔했다. 하얀 점 하나가 맺혔다.<br>칼로 긁어냈다. 피가 났다. 점은 없어졌다. 아마.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-9, spirit:-8 } },
    { l:'② 진물 먹은 부여만 골라낸다.', k:'gaze', dc:14,
      ok:`다섯 사람 장비를 늘어놓고 봤다. 진물 먹은 부여는 색이 탁하다.<br><br>탁한 것만 셋 골라 벗겼다. 나머지는 맑다. 맑은 것은 밖에서도 쓸 수 있다.<br>칼 하나는 아직 날 끝이 푸르다.`,
      ng:`맑은 것과 탁한 것을 가리는데 다 탁해 보인다. 눈이 지쳤다.<br><br>탁한 걸 하나 남겼다. 나오고 나서 칼 하나가 저 혼자 칼집에서 반쯤 빠졌다.<br>칼을 버리고 왔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-8, spirit:-9 } }
  ] }

]);

// ── 분대장 ──────────────────────────────
kJob('squad', 'C', [

{ at:'C', t:'첫 점호 — 젖은 대답',
  x:`들어서자마자 머릿수를 셌다. 넷. 이쪽까지 다섯. 맞다.<br><br>
    번호를 붙이게 했다. 하나, 둘, 셋, 넷. 넷째 목소리가 젖었다. 목구멍에 물이 고인 소리다.<br>
    넷째를 봤다. 멀쩡하다. 본인은 모른다.<br><br>
    여기서는 들어서자마자 무언가 묻는다. 무엇이 묻었는지는 셈으로 안 나온다.`,
  o:[
    { l:'① 넷째를 제 바로 뒤에 세운다.', k:'fix', dc:14,
      ok:`넷째를 제 바로 뒤에 세웠다. 등 뒤에서 숨소리가 들리는 자리.<br><br>걷는 동안 숨소리를 들었다. 젖은 소리가 조금씩 마른다. 반 시진 뒤 넷째가 기침을 한 번 했다. 하얀 실 뭉치가 나왔다.<br>그 뒤로 목소리가 맑아졌다. 다음 점호에서 제일 크게 대답했다.<br><br>뒤에 세운 건 지키려고만이 아니다. 들으려고다.`,
      ng:`뒤에 세웠는데 숨소리가 점점 더 젖는다.<br><br>반 시진 뒤 넷째가 주저앉았다. 기침이 멈추지 않는다. 하얀 실이 줄줄 나왔다.<br>등을 두드려 다 뱉게 했다. 그사이 둘레에서 무언가 다가왔다. 쫓느라 팔을 할퀴었다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ hp:-11, spirit:-7 } },
    { l:'② 무력을 써서 맨 앞에서 길을 튼다.', k:'steady', dc:14, cost:{ might:15 },
      ok:`맨 앞에 섰다. 거미줄 같은 하얀 막이 길을 덮고 있다. 몸으로 밀고 나갔다.<br><br>막이 이쪽 어깨와 가슴에 다 묻었다. 뒤는 깨끗한 길이다.<br>넷째 목소리가 더 젖지 않았다. 묻을 것이 이쪽에 다 묻었다.<br><br>어깨를 털었다. 하얀 것이 바닥에서 꿈틀거렸다.`,
      ng:`밀고 나가는데 막이 질기다. 몸이 막에 감겼다.<br><br>버둥댈수록 더 감긴다. 뒤에서 칼로 잘라 줬다.<br>얼굴에 붙은 것이 한참 안 떨어졌다. 눈두덩이 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C1', t:'도축장 — 갈고리 밑 행군',
  x:`천장 쇠줄에 갈고리가 돈다. 빈 갈고리는 사람 목 높이로 지나간다.<br><br>
    작업장 끝까지 서른 걸음. 갈고리는 쉬지 않는다. 엎드려 기면 너무 느리다. 서서 가면 목이 걸린다.<br>
    일행 넷이 다 이쪽을 본다.<br><br>
    구령 하나에 다섯 몸이 같이 움직여야 한다.`,
  o:[
    { l:'① 낮은 자세 구령을 붙인다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"허리 숙여. 앞사람 허리띠. 내 발 따라."</span><br><br>다섯이 허리를 숙이고 한 줄로 붙었다. 이쪽 발이 디디면 넷이 그 자리를 디뎠다. 갈고리가 머리 위를 스쳤다. 아무도 고개를 안 들었다.<br>서른 걸음 내내 한 번도 끊기지 않았다.<br><br>다섯 몸을 한 몸처럼 움직였다. 구령이 귀가 아니라 허리띠를 타고 갔다. 말을 몸으로 건네는 길을 하나 더 알았다.`,
      ng:`허리를 숙이라 했는데 셋째가 짐 때문에 덜 숙였다.<br><br>갈고리가 짐을 꿰었다. 셋째가 뒤로 끌려갔다. 허리띠를 쥔 넷째가 같이 끌려갔다.<br>둘 다 붙잡아 끌어내렸다. 이쪽 손바닥이 갈고리 끝에 찢어졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-15, mind:-6 } },
    { l:'② 무력을 써서 갈고리를 붙잡아 멈춘다.', k:'break', dc:15, cost:{ might:18 },
      ok:`지나가는 빈 갈고리를 두 손으로 붙잡았다. 줄이 당긴다. 버텼다.<br><br>줄 전체가 멎었다. 갈고리들이 덜컹거리며 섰다.<br><span style="color:#d4af37;">"지금!"</span> 넷이 뛰어 건넜다. 마지막으로 놓고 이쪽도 뛰었다.<br><br>팔이 한참 떨렸다. 줄 하나를 몸으로 쥐었다.`,
      ng:`붙잡았는데 줄이 안 멈췄다. 이쪽이 끌려갔다.<br><br>다섯 걸음 끌려가다 놓았다. 손바닥 살갗이 쇠에 남았다.<br>다시 기다렸다가 기어서 건넜다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-5 } }
  ] },

{ at:'C1', t:'도축장 — 걸려 간 사람',
  x:`갈고리 하나가 일행을 걸었다. 어깨 옷을 꿰었다. 줄이 그 사람을 싣고 작업장 안쪽으로 간다.<br><br>
    안쪽에서 칼질 소리가 난다. 탕, 탕. 줄 끝에 앞치마 두른 큰 것이 있다.<br>
    그 사람이 버둥댄다. 줄은 느리다. 그래도 간다.<br><br>
    점호에서 넷이 대답하게 둘 수는 없다.`,
  o:[
    { l:'① 무력을 써서 줄을 따라 뛰어 끌어내린다.', k:'fix', dc:15, cost:{ might:20 }, wake:1,
      ok:`줄 밑을 따라 뛰었다. 그 사람 허리를 두 팔로 안고 매달렸다. 둘 무게에 갈고리가 기울었다.<br><br><span style="color:#d4af37;">"옷 벗어!"</span> 그 사람이 팔을 빼며 윗옷에서 빠져나왔다. 둘이 같이 바닥에 떨어졌다. 빈 옷만 줄에 걸려 안쪽으로 갔다.<br>칼질 소리가 한 번 멈췄다가 다시 났다.<br><br>몸이 구령보다 먼저 나가는 버릇이 있었다. 오늘은 몸이 구령을 품고 나갔다. 매달린 채로도 말이 나왔다. 뛰는 몸과 붙이는 구령이 하나가 됐다.`,
      ng:`매달렸는데 갈고리가 버텼다. 둘이 같이 끌려간다.<br><br>앞치마 두른 것이 가까워진다. 칼날이 보인다. 그 사람 옷을 칼로 찢어 떨어뜨렸다.<br>떨어지면서 이쪽 무릎이 쇠 받침에 부딪쳤다. 뼈가 울렸다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-17, mind:-6 } },
    { l:'② 갈고리 줄에 올라타 쫓는다.', k:'evade', dc:15,
      doom:{ title:'다음 갈고리', what:'갈고리 줄에 실려 갑니다', dc:15, sec:60,
        text:`빈 갈고리 하나를 잡고 올라탔다. 줄을 타면 따라잡는다.<br><br>따라잡았다. 그 사람 옷을 칼로 끊어 떨어뜨렸다. 됐다.<br>이제 내려야 한다. 잡은 갈고리가 손을 놓아주지 않는다. 손목에 쇠가 감긴다. 줄이 빨라진다.<br><br>칼질 소리가 가깝다. 탕. 탕.`,
        dieText:`점호에서 넷이 대답했다.<br><br>다섯째 이름을 부를 사람이 없다. 이름을 부르던 사람이 다섯째였다.<br>쇠줄은 계속 돈다. 빈 갈고리 하나가 지나갈 때마다 손목 높이에서 천 조각이 흔들린다.` },
      ok:`빈 갈고리 하나를 잡고 올라탔다. 줄을 타면 따라잡는다.<br><br>따라잡았다. 그 사람 옷을 칼로 끊어 떨어뜨렸다. 이쪽도 바로 뛰어내렸다. 갈고리가 손목을 감기 전에.<br>둘이 바닥을 굴렀다. 일어나서 셌다. 다섯.<br><br>줄 끝에서 칼질 소리가 한 번 크게 났다. 아무것도 안 온 자리를 친 소리다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 줄 돌리는 바퀴를 막으라고 한다.', k:'steady', dc:14,
      ok:`<span style="color:#d4af37;">"바퀴! 막아!"</span><br><br>벽의 나무 바퀴에 둘이 달려들어 몸으로 막았다. 줄이 멎었다. 걸린 사람이 공중에 섰다.<br>이쪽이 올라가 옷을 끊어 내렸다.<br>바퀴를 막은 둘이 손을 떼자 줄이 다시 돌았다.`,
      ng:`바퀴를 막았는데 바퀴가 둘을 밀어냈다.<br><br>줄이 다시 돈다. 걸린 사람이 더 멀어졌다.<br>뛰어가서 옷을 찢어 끌어내렸다. 그 사람 어깨가 갈고리에 깊이 찢겼다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'인형 공방 — 여섯째 대답',
  x:`공방에서 점호를 했다. 하나, 둘, 셋, 넷, 이쪽 다섯.<br><br>
    <span style="color:#d4af37;">"여섯."</span><br>
    선반 어딘가에서 대답이 났다. 작고 높은 목소리. 사기 이가 부딪치는 소리가 섞였다.<br><br>
    세어서 남는 머릿수는 셈이 아니라 침입이다.`,
  o:[
    { l:'① 번호 대신 이름으로 다시 센다.', k:'fix', dc:14,
      ok:`번호를 버리고 이름을 불렀다. 넷의 이름, 그리고 제 이름.<br><br>인형은 이름을 모른다. 선반에서 아무도 대답하지 않았다.<br>그다음부터 점호는 이름으로만 했다. 공방을 나올 때까지 여섯은 안 나왔다.<br><br>번호는 아무나 댈 수 있다. 이름은 아니다.`,
      ng:`이름을 불렀는데 셋째 이름에 대답이 둘 났다.<br><br>하나는 셋째다. 하나는 선반 위다. 셋째 목소리와 똑같다.<br>셋째를 끌어당겨 곁에 세웠다. 선반 위 것이 그 뒤로 계속 셋째 이름에 대답했다. 셋째 얼굴이 하얬다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ mind:-8, spirit:-10 } },
    { l:'② 대답한 것을 찾아낸다.', k:'gaze', dc:14,
      ok:`대답이 난 쪽 선반을 봤다. 인형 서른 개 중 하나만 입이 벌어져 있다. 이 사이에 침이 고였다.<br><br>그것을 끌어내렸다. 바닥에 내리쳤다. 사기가 깨지며 안에서 작은 혀가 나왔다. 꿈틀대다 멎었다.<br>다시 셌다. 다섯. 맞다.`,
      ng:`찾는데 서른 개가 다 입이 벌어져 있다.<br><br>다 같이 침이 고였다. 다 같이 이를 부딪쳤다. 여섯, 여섯, 여섯.<br>공방을 뛰쳐나왔다. 문 뒤에서 한참 여섯을 셌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-9, spirit:-8 } }
  ] },

{ at:'C2', t:'인형 공방 — 줄에 묶인 몸',
  x:`천장에서 내려온 실이 일행 하나를 감았다. 손목, 팔꿈치, 무릎.<br><br>
    그 사람이 칼을 들었다. 본인 뜻이 아니다. 얼굴이 울상이다. 칼끝이 옆 사람을 향한다.<br>
    위층에서 누가 줄을 당긴다. 그 사람 몸은 지금 위층 것이다.<br><br>
    몸을 되찾아 줄 수 있는 것은 그 사람이 제일 오래 들은 목소리다.`,
  o:[
    { l:'① 구령으로 그 몸을 붙잡는다.', k:'fix', dc:15, wake:1,
      ok:`그 사람 앞에 서서 늘 쓰던 구령을 붙였다. <span style="color:#d4af37;">"제자리. 칼 내려."</span><br><br>팔이 떨렸다. 줄이 당기는 쪽과 구령이 당기는 쪽. 수십 번 들은 구령이다. 몸이 먼저 안다.<br>칼끝이 바닥으로 내려갔다. 그 틈에 다른 일행이 실을 다 끊었다.<br><br>목소리가 줄보다 깊이 들어갔다. 구령은 귀에 붙이는 게 아니라 몸에 새기는 것이다. 날마다 붙인 구령이 오늘 그 사람 몸 안에서 이쪽 편이 되었다.`,
      ng:`구령을 붙였는데 위층 줄이 더 셌다.<br><br>칼이 내려오다 멈추고 다시 올라갔다. 이쪽 쪽으로. 팔뚝으로 막았다. 칼날이 살에 박혔다.<br>그 사람이 울며 칼을 놓았다. 그제야 실이 끊겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 무력을 써서 뒤에서 껴안아 누른다.', k:'steady', dc:15, cost:{ might:18 },
      ok:`그 사람을 뒤에서 껴안았다. 두 팔째. 칼 든 팔까지 같이.<br><br>줄이 당긴다. 버텼다. 위층 무게와 이쪽 무게가 다퉜다. 이쪽이 무거웠다.<br>다른 일행이 실을 다 끊을 때까지 안고 있었다. 풀어 주자 그 사람이 주저앉았다.`,
      ng:`껴안았는데 줄이 둘을 같이 들어 올렸다.<br><br>발끝이 바닥에서 떨어졌다. 둘이 같이 매달려 버둥댔다.<br>실이 끊어지며 둘이 같이 떨어졌다. 이쪽이 밑에 깔렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 등 뒤',
  x:`사냥 뒤 쉬는 자리. 치료하는 사람이 다친 둘을 돌본다.<br><br>
    둘레가 어둡다. 피 냄새가 퍼졌다. 여기 것들은 피 냄새를 따라온다.<br>
    치료하는 손이 자꾸 등 뒤를 돌아본다. 손이 늦어진다.<br><br>
    등을 맡을 사람이 필요하다.`,
  o:[
    { l:'① 둘을 세우고 저는 등 뒤에 선다.', k:'fix', dc:14,
      ok:`성한 둘을 치료하는 사람 양옆에 세우고 이쪽은 등 뒤에 섰다.<br><br>치료하는 사람이 한 번 돌아보더니 다시는 안 돌아봤다. 손이 빨라졌다.<br>어둠 속에서 무언가 두 번 다가왔다가 섰다. 셋이 서 있는 걸 보고 물러났다.`,
      ng:`세웠는데 하나가 졸았다. 다 지쳤다.<br><br>그쪽으로 무언가 기어들었다. 치료하는 사람 발목을 물었다.<br>떼어 냈다. 다친 사람이 셋이 됐다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-10, mind:-8 } },
    { l:'② 무력을 써서 혼자 둘레를 크게 돈다.', k:'sense', dc:14, cost:{ might:15 },
      ok:`횃불을 들고 둘레를 크게 돌았다. 쉬지 않고, 발소리 크게.<br><br>큰 발소리는 큰 무리처럼 들린다. 다가오던 것들이 멀찍이서 맴돌다 흩어졌다.<br>치료가 끝날 때까지 돌았다. 다리가 후들거린다. 다친 둘이 일어섰다.`,
      ng:`돌다가 너무 멀리 나갔다.<br><br>둘레 밖에서 그것과 마주쳤다. 서로 놀랐다. 그쪽이 먼저 할퀴었다.<br>횃불을 휘둘러 쫓았다. 옆구리에 자국이 셋.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 앞이 없는 대열',
  x:`성당이 거꾸로 서 있다. 발밑이 둥근 천장이다.<br><br>
    다들 어지럽다. 위에 매달린 신도석을 보면 속이 뒤집힌다. 하나가 벌써 토했다.<br>
    대열이 흐트러진다. 앞이 어딘지 모르니 앞사람도 없다.<br><br>
    앞이 없는 대열은 대열이 아니다. 앞을 다시 정해야 한다.`,
  o:[
    { l:'① 앞을 제 등으로 정한다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"위 보지 마. 내 등만 봐."</span><br><br>맨 앞에 서서 등을 내밀었다. 다들 이쪽 등을 보며 걸었다. 등은 거꾸로 서지 않는다.<br>어지러움이 가라앉았다. 대열이 다시 섰다.<br><br>앞은 방향이 아니었다. 사람이었다. 거꾸로 선 데서도 앞사람 등은 앞에 있다. 이쪽 등이 다섯의 앞이 될 수 있다는 걸 오늘 알았다.`,
      ng:`등만 보라고 했는데 이쪽이 먼저 위를 봤다. 버릇이다.<br><br>어지러움이 덮쳤다. 무릎이 꺾였다. 앞이 주저앉자 뒤가 다 섰다.<br>한참 엎드려 있다가 일어났다. 다들 이쪽 등을 걱정스럽게 봤다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ hp:-10, mind:-10 } },
    { l:'② 허리띠를 이어 한 줄로 묶는다.', k:'bond', dc:14,
      ok:`허리띠를 이어 다섯을 한 줄로 묶었다.<br><br>어지러워도 줄은 앞으로만 당긴다. 줄을 따라 걸었다.<br>토하던 사람도 줄에 끌려 따라왔다. 다 지났다.`,
      ng:`묶었는데 하나가 어지러워 쓰러졌다. 줄이 넷을 같이 넘어뜨렸다.<br><br>다섯이 갈빗대 위에 엉켜 굴렀다.<br>풀고 일어나는 데 한참. 팔꿈치가 다 까졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 흉내 내는 구령',
  x:`매달린 성가대석에서 입 많은 것들이 노래 대신 말을 한다.<br><br>
    <span style="color:#d4af37;">"제자리."</span> 이쪽 목소리다. 이쪽은 아무 말도 안 했다.<br>
    <span style="color:#d4af37;">"앞으로. 그쪽으로."</span> 일행이 그 소리에 한 걸음씩 움직인다. 성가대석 밑으로.<br><br>
    구령을 훔쳤다. 구령이 둘이면 몸은 가까운 쪽을 따른다.`,
  o:[
    { l:'① 약속한 구령을 바꾼다.', k:'fix', dc:15,
      ok:`다섯만 알게 바꿨다. 손바닥으로 제 가슴을 두 번 치고 말했다. <span style="color:#d4af37;">"둘."</span><br><br>가슴 치는 소리가 함께 나는 구령만 듣기로 했다. 입 많은 것들은 흉내만 낸다. 무엇을 쳐야 하는지는 모른다.<br>일행이 멈췄다. 이쪽을 봤다. 둘을 치고 뒤로 물리자 다 물러났다.<br><br>성가대석에서 "둘, 둘" 하는 소리가 한참 났다. 가슴 치는 소리 없이.`,
      ng:`바꾸는 사이 성가대가 그것까지 흉내 냈다. 가슴 치는 소리까지.<br><br>입 많은 것들이 제 가슴팍 입을 손바닥으로 쳤다. 두 번.<br>일행이 또 헷갈렸다. 하나를 끌어내는 동안 이쪽 귀에서 피가 났다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-10, spirit:-11 } },
    { l:'② 입을 다물고 손짓으로만 끈다.', k:'hide', dc:14,
      ok:`입을 닫았다. 손바닥을 펴서 아래로 눌렀다. 멈춤. 손가락 둘로 뒤를 가리켰다. 물러남.<br><br>성가대가 아무것도 흉내 내지 못했다. 손짓은 소리가 없다.<br>다섯이 말없이 물러났다. 성가대석에서 이쪽 목소리가 한참 혼자 떠들었다.`,
      ng:`손짓을 했는데 하나가 성가대석 밑에서 등을 지고 있었다.<br><br>손짓을 못 봤다. 이쪽 목소리를 따라 한 걸음 더 갔다.<br>손 수십 개가 내려와 그 사람 머리카락을 잡았다. 칼로 머리카락째 잘라 끌어냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-10, spirit:-10 } },
    { l:'③ 무력을 써서 성가대석 사슬을 끊는다.', k:'break', dc:15, cost:{ might:20 },
      ok:`성가대석을 매단 사슬 끝을 쳤다. 두 번, 세 번. 사슬 고리가 벌어졌다.<br><br>성가대석이 한쪽으로 기울며 떨어졌다. 둥근 천장에 처박혔다. 입들이 한꺼번에 비명을 질렀다. 이쪽 목소리로.<br>그 뒤로는 흉내가 없었다.`,
      ng:`사슬을 치는데 사슬이 안 끊어졌다. 손목만 울렸다.<br><br>성가대가 이쪽 목소리로 웃었다.<br>손이 저려 한참 칼을 못 쥐었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C4', t:'포자 온실 — 기침하는 일행',
  x:`일행 하나가 기침을 한다. 노란 가루를 마셨다.<br><br>
    기침할 때마다 하얀 실이 섞여 나온다. 본인은 괜찮다고 한다. 다른 일행들이 슬금슬금 떨어져 걷는다.<br>
    떨어져 걷는 대열은 벌어진다. 벌어진 데로 정원사가 들어온다.<br><br>
    기침하는 사람이 대열 맨 끝으로 처진다.`,
  o:[
    { l:'① 기침하는 사람을 대열 가운데에 둔다.', k:'fix', dc:14,
      ok:`<span style="color:#d4af37;">"가운데로."</span> 기침하는 사람을 대열 한가운데 세웠다. 이쪽은 그 바로 앞에.<br><br>다른 넷이 머뭇거렸다. 이쪽이 먼저 그 사람 어깨를 잡았다. 그걸 보고 다들 다시 붙었다.<br>대열이 다시 좁아졌다. 벌어진 데가 없다.<br><br>쉬는 자리에서 그 사람이 실 덩이를 다 토했다. 그 뒤로 기침이 멎었다.`,
      ng:`가운데 세웠는데 그 사람 기침이 이쪽 얼굴에 튀었다.<br><br>이쪽 입 안으로 노란 것이 들어왔다. 목이 따끔하다.<br>둘이 기침을 했다. 대열이 또 벌어졌다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 젖은 천으로 그 사람 입을 막아 준다.', k:'heal', dc:14,
      ok:`물을 붓고 천을 적셔 그 사람 입과 코를 감쌌다.<br><br>기침이 천 안에서 났다. 가루가 안 퍼진다. 다른 일행들이 다시 다가왔다.<br>천을 갈아 줄 때마다 하얀 실이 묻어 나왔다. 점점 적어졌다.`,
      ng:`천을 대자 그 사람이 숨이 막힌다고 뿌리쳤다.<br><br>천이 날아갔다. 기침이 터졌다. 가루가 대열 위로 퍼졌다.<br>다들 콜록거리며 걸었다.`,
      win:{ exp:15, dream:1, mind:5 }, lose:{ hp:-10, spirit:-9 } }
  ] },

{ at:'C4', t:'포자 온실 — 낯익은 차림',
  x:`화단 사이로 정원사 하나가 걷는다. 그런데 앞치마가 아니다.<br><br>
    가죽 조끼, 허리띠에 단 칼집, 등에 맨 짐. 사냥하러 들어온 사람 차림이다. 앞서 들어왔던 일행이다.<br>
    걸음이 대열 걸음이다. 발을 맞춰 걷는다. 하나, 둘. 그쪽 분대장이 붙이던 구령대로.<br><br>
    그것이 이쪽 대열을 봤다. 발을 맞춰 다가온다.`,
  o:[
    { l:'① 저쪽 대열 걸음을 읽어 틈을 친다.', k:'gaze', dc:15,
      ok:`저 걸음은 구령 걸음이다. 하나에 왼발, 둘에 오른발. 구령 사이에 반 박 쉰다. 사람이었을 때 버릇이다.<br><br><span style="color:#d4af37;">"둘에 들어가."</span> 그것이 오른발을 디디고 쉬는 반 박에 넷이 들어갔다. 실 덩이가 조끼째 갈라졌다.<br>쓰러진 그것의 허리띠에 이름표가 달려 있다. 챙겼다. 밖에 나가면 누군가에게 줄 것이다.`,
      ng:`둘에 들어가라 했는데 그것이 구령을 바꿨다. 셋에 디뎠다.<br><br>넷이 허공에 칼을 휘둘렀다. 그것의 칼집에서 칼이 뽑혔다. 사람 손이 아닌데 사람처럼 뽑았다.<br>앞에 선 사람 어깨가 갈렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-7 } },
    { l:'② 다가가 얼굴을 확인한다.', k:'bond', dc:15,
      doom:{ title:'남은 대원', what:'포자 덩이가 끌어안고 화단으로 끌고 갑니다', dc:15, sec:55,
        text:`다가갔다. 모자는 없다. 얼굴 자리에 하얀 실이 얽혀 사람 얼굴 모양을 만들었다.<br><br>알아보려고 한 걸음 더 갔다. 그것이 두 팔을 벌렸다. 대원을 맞는 팔이다.<br>끌어안았다. 실이 이쪽 옷 속으로 파고든다. 가슴, 목, 턱.<br><br>그것이 이쪽을 안은 채 뒷걸음질한다. 화단 흙 쪽으로. 발을 맞춰서. 하나, 둘.`,
        dieText:`화단 사이로 정원사 둘이 걷는다. 발을 맞춰서.<br><br>하나는 가죽 조끼, 하나는 이쪽 옷이다.<br>둘이 구령을 붙이듯 고개를 까딱인다. 다음에 들어오는 사람들은 그 걸음을 보고 사람인 줄 알 것이다.` },
      ok:`다가갔다. 얼굴 자리에 하얀 실이 얽혀 사람 얼굴 모양을 만들었다. 모르는 얼굴이다.<br><br>그것이 두 팔을 벌렸다. 대원을 맞는 팔이다. 팔이 닿기 전에 칼을 그 가슴에 박았다. 실 덩이 심이 거기 있었다.<br>그것이 팔을 벌린 채 무너졌다.<br><br>허리띠 이름표를 챙겼다. 이름을 소리 내어 한 번 불렀다. 대답은 없었다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 무력을 써서 정면으로 막아선다.', k:'steady', dc:15, cost:{ might:20 },
      ok:`대열 앞으로 나가 정면에 섰다. 그것이 칼을 뽑아 내리쳤다. 막았다. 무겁다. 사람보다 무겁다.<br><br>두 번, 세 번. 버텼다. 그 사이 옆에서 일행이 실 덩이 심을 찔렀다.<br>그것이 무너졌다. 이쪽 칼에 이가 셋 나갔다.`,
      ng:`막았는데 칼이 밀렸다. 칼등이 이쪽 이마를 쳤다.<br><br>눈앞이 하얬다. 무릎을 꿇었다. 일행이 끌어냈다.<br>이마에서 피가 흘러 눈에 들어갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-17, mind:-6 } }
  ] },

{ at:'C', t:'사냥 — 팔 여섯',
  x:`큰 것이 나왔다. 몸통이 소만 하고 팔이 사람 팔이다. 여섯 개.<br><br>
    팔 여섯이 동시에 휘두른다. 다섯이 다 붙으면 다섯이 다 맞는다.<br>
    누군가 팔을 받아 내야 나머지가 몸통을 친다.<br><br>
    일행이 이쪽을 본다. 구령을 기다린다.`,
  o:[
    { l:'① 둘이 막고 셋이 치는 구령을 붙인다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"방패 둘, 앞으로. 셋, 왼쪽으로 돌아. 내 손 내려가면 들어가."</span><br><br>방패 둘이 앞에서 팔 여섯을 받았다. 팔들이 그쪽으로 몰렸다. 셋이 왼쪽으로 돌았다. 이쪽은 가운데서 손을 들고 있었다.<br>팔이 다 앞으로 뻗은 순간 손을 내렸다. 셋이 옆구리로 들어갔다. 그것이 무너졌다.<br><br>이번엔 이쪽 몸이 안 나갔다. 손 하나만 내렸다. 몸이 먼저 나가던 사람이 처음으로 손으로 싸움을 이겼다. 나가지 않고 서 있는 것도 앞에 서는 일이다.`,
      ng:`손을 내리기 전에 셋 중 하나가 먼저 들어갔다.<br><br>팔 하나가 그쪽으로 돌았다. 그 사람이 나가떨어졌다. 둘만 들어갔다.<br>그것은 쓰러졌다. 나가떨어진 사람 갈비뼈가 몇 대 나갔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-16, mind:-7 } },
    { l:'② 무력을 써서 제 몸으로 팔을 받는다.', k:'steady', dc:15, cost:{ might:22 },
      ok:`맨 앞으로 나가 팔 여섯을 혼자 받았다. 막고, 막고, 맞고, 막고.<br><br>팔들이 다 이쪽에 걸렸다. 그 사이 넷이 몸통을 쳤다.<br>쓰러졌다. 이쪽도 주저앉았다. 팔뚝이 퍼렇게 부었다.`,
      ng:`여섯을 혼자 받는 건 무리였다. 넷째 팔이 머리를 쳤다.<br><br>눈앞이 하얬다. 넷이 이쪽을 끌어내느라 몸통을 못 쳤다.<br>다시 둘러싸는 데 한참. 이쪽 귀에서 한동안 이명이 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-6 } },
    { l:'③ 팔 하나씩 맡긴다.', k:'bond', dc:15,
      ok:`팔 여섯을 넷이 하나씩, 이쪽이 둘을 맡았다. 붙잡기만 하라고 했다.<br><br>팔이 하나씩 붙잡혔다. 붙잡힌 팔은 휘두르지 못한다. 이쪽이 둘을 겨드랑이에 끼고 버텼다.<br>남은 손으로 몸통을 찔렀다. 다 같이.`,
      ng:`팔 하나를 맡은 사람이 놓쳤다. 놓친 팔이 옆 사람을 쳤다.<br><br>그 사람도 놓쳤다. 팔 둘이 풀렸다. 다들 맞았다.<br>겨우 끝냈다. 다섯이 다 멍투성이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 줄 세우는 것',
  x:`앞치마 두른 큰 것이 고기를 줄 세운다. 하나, 둘, 셋. 열둘을 세우고 칼질을 한다.<br><br>
    일행이 그 앞을 지나야 한다. 다섯이 한 줄로 지나가면 그것의 눈에 줄로 보인다.<br>
    줄로 보이면 세운다. 세우면 칼질이다.<br><br>
    그것이 고개를 들어 이쪽을 셌다. 하나, 둘.`,
  o:[
    { l:'① 대열을 흐트러뜨려 지나간다.', k:'fix', dc:15,
      ok:`<span style="color:#d4af37;">"흩어져. 각자 다른 걸음."</span><br><br>하나는 빠르게, 하나는 느리게, 하나는 멈췄다 가고. 줄이 아닌 다섯이 됐다. 이쪽은 맨 끝에서 다섯을 다 봤다.<br>그것이 셈을 하다 멈췄다. 줄이 아닌 것은 셀 수가 없다. 고개를 숙이고 다시 고기를 셌다.<br><br>대열을 일부러 깨 본 건 처음이다. 깨는 것도 구령이다.`,
      ng:`흩어지라 했는데 버릇처럼 다들 발이 맞았다. 하나, 둘.<br><br>그것이 셌다. 셋, 넷, 다섯. 칼이 내려왔다. 맨 끝의 이쪽 쪽으로.<br>피했는데 등을 스쳤다. 옷과 살이 같이 갈라졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 무력을 써서 칼 든 팔을 붙잡는다.', k:'break', dc:15, cost:{ might:20 },
      ok:`그것이 칼을 드는 순간 팔꿈치를 붙잡았다. 두 손으로. 온몸 무게를 실어.<br><br>칼이 공중에 섰다. 그것이 다른 팔로 이쪽을 떼어 내려 한다. 그 사이 넷이 앞치마 밑으로 들어갔다.<br>그것이 무너졌다. 붙잡은 팔은 끝까지 안 놓았다.`,
      ng:`붙잡았는데 그것이 팔을 들어 올렸다. 이쪽째.<br><br>공중에 매달렸다. 그것이 팔을 털었다. 고기 걸이에 내동댕이쳐졌다.<br>쇠 모서리에 허리를 찧었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-17, mind:-5 } }
  ] },

{ at:'C2', t:'인형 공방 — 맨 뒤의 발소리',
  x:`공방을 지나는데 맨 뒤에서 발소리가 하나 더 난다.<br><br>
    작고 딱딱한 발소리. 사기 발이다. 이쪽 대열 맨 끝에 붙어서 같이 걷는다.<br>
    돌아보면 없다. 앞을 보면 다시 난다. 한 걸음씩 대열 안쪽으로 들어온다.<br><br>
    대열 안에 들어온 것은 대열의 하나가 된다.`,
  o:[
    { l:'① 대열을 원으로 바꾼다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"원. 등 붙여. 밖을 봐."</span><br><br>다섯이 등을 맞대고 원을 만들었다. 맨 끝이 없어졌다. 맨 끝이 없으니 붙을 데가 없다.<br>사기 발소리가 원 둘레를 맴돌았다. 들어올 틈을 찾다 멈췄다. 원을 지은 채 걸음을 옮겨 공방을 빠져나왔다.<br><br>대열은 줄이어야 하는 줄 알았다. 모양을 바꾸면 빈 데가 바뀐다. 어디가 빌지 이쪽이 정할 수 있다. 대열을 짓는 손이 한 가지 모양에서 풀려났다.`,
      ng:`원을 만드는 사이 발소리가 원 안으로 들어왔다.<br><br>원 한가운데 인형 하나가 서 있다. 무릎 높이. 이를 딸깍인다.<br>다섯이 동시에 안쪽을 보느라 원이 깨졌다. 인형이 이쪽 발목을 물었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-13, spirit:-9 } },
    { l:'② 맨 뒤로 가서 선다.', k:'steady', dc:14,
      ok:`맨 뒤로 갔다. 사기 발소리가 바로 뒤에 붙었다. 이쪽 발뒤꿈치에.<br><br>돌아보지 않고 걸었다. 대열 안으로 들어오려면 이쪽을 넘어야 한다. 이쪽은 안 비켰다.<br>공방 문을 나서자 발소리가 멎었다. 문지방을 못 넘는다.`,
      ng:`맨 뒤에 섰는데 발소리가 이쪽 다리 사이로 들어왔다.<br><br>작다. 다리 사이로 빠져 대열 안으로 갔다. 넷째 발목을 물었다.<br>떼어 내 바닥에 내리쳤다. 사기 조각이 이쪽 손바닥에 박혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-7 } }
  ] },

{ at:'C', t:'어둠 — 넷',
  x:`걷다 보니 넷이다. 이쪽까지.<br><br>
    다시 셌다. 넷. 맨 뒤가 없다. 어둠 속에 발자국이 끌린 자국으로 바뀐 데가 있다.<br>
    무언가 끌고 갔다. 소리도 없이.<br><br>
    끌린 자국은 아직 따뜻하다.`,
  o:[
    { l:'① 무력을 써서 끌린 자국을 따라 뛴다.', k:'bond', dc:15, cost:{ might:20 },
      ok:`끌린 자국을 따라 뛰었다. 서른 걸음. 굴 하나. 굴 안에서 신음 소리가 난다.<br><br>굴에 팔을 넣어 발목을 잡았다. 맨 뒷사람 발목이다. 안에서 무언가 반대로 당긴다. 버텼다. 끌어냈다.<br>그 사람 등에 이빨 자국이 줄지어 났다. 살았다.<br><br>업고 돌아왔다. 셌다. 다섯.`,
      ng:`굴에 팔을 넣었는데 안에서 무언가 이쪽 팔을 물었다.<br><br>발목을 놓지 않았다. 팔을 물린 채 당겼다. 둘이 같이 굴에서 빠져나왔다.<br>팔뚝에 구멍이 넷 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-5 } },
    { l:'② 다 같이 자국을 따라간다.', k:'fix', dc:15,
      ok:`<span style="color:#d4af37;">"한 줄. 허리띠 잡아. 따라와."</span><br><br>셋을 데리고 자국을 따라갔다. 흩어지지 않으면 하나를 더 잃지 않는다.<br>굴 앞에서 넷이 동시에 횃불을 들이밀었다. 안의 것이 불에 놀라 물고 있던 것을 놓았다.<br>맨 뒷사람이 기어 나왔다. 다섯.`,
      ng:`다 같이 가느라 느렸다. 자국이 식었다.<br><br>굴을 찾았을 때 안이 조용했다. 들어갔다. 맨 뒷사람이 혼자 웅크려 있다. 그것은 없다.<br>그 사람이 끝까지 무엇을 봤는지 말하지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-9, spirit:-11 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 종탑 위의 손가락',
  x:`둥근 천장 갈빗대 사이에 틈이 있다. 틈 밑은 종탑이다. 거꾸로 선 종탑이 아래로 뻗었다.<br><br>
    일행 하나가 틈 가장자리에서 발이 미끄러졌다. 손가락 끝으로 갈빗대에 매달렸다.<br>
    밑에서 종이 운다. 떨어지는 것을 받으려고 입을 벌렸다.<br><br>
    손가락이 하나씩 펴지고 있다.`,
  o:[
    { l:'① 엎드려 팔을 뻗어 붙잡는다.', k:'fix', dc:15,
      doom:{ title:'종탑 아래', what:'거꾸로 선 종탑 속으로 떨어집니다', dc:15, sec:55,
        text:`갈빗대에 배를 대고 엎드려 그 사람 손목을 잡았다.<br><br>당겼다. 그 사람 몸이 올라온다. 반쯤. 그때 이쪽 배 밑 갈빗대가 꿈틀했다. 산 것이었다.<br>갈빗대가 몸을 비틀었다. 이쪽 몸이 틈 쪽으로 미끄러진다. 그 사람을 위로 밀어 올렸다. 마지막 힘으로.<br><br>그 사람은 올라갔다. 이쪽 손가락이 갈빗대 끝에 걸렸다. 밑에서 종이 입을 벌린다.`,
        dieText:`그 사람은 갈빗대 위로 굴러 올라왔다. 살았다.<br><br>밑에서 종이 한 번 울렸다. 길게.<br>점호에서 넷이 대답했다. 넷 다 다섯째 자리에 이쪽 이름을 넣고 셌다. 대답이 없는 자리.` },
      ok:`갈빗대에 배를 대고 엎드려 그 사람 손목을 잡았다. <span style="color:#d4af37;">"내 다리!"</span> 뒤에서 둘이 이쪽 발목을 잡았다.<br><br>사슬처럼 이어져 당겼다. 그 사람이 올라왔다. 셋이 다 같이 뒤로 굴렀다.<br>밑에서 종이 빈 입으로 울었다.<br><br>혼자 뻗은 팔이 아니었다. 뒤에 둘이 붙었다. 구령은 한 마디면 됐다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 무력을 써서 갈빗대를 감고 줄을 내린다.', k:'steady', dc:15, cost:{ might:22 },
      ok:`갈빗대 하나를 허벅지로 감고 버텼다. 허리 밧줄을 풀어 틈으로 내렸다.<br><br>그 사람이 줄을 잡았다. 이쪽 허벅지에 두 사람 무게가 왔다. 갈빗대가 삐걱댔다. 버텼다.<br>올라왔다. 허벅지에 갈빗대 자국이 깊게 패였다.`,
      ng:`줄을 내리는 데 너무 오래 걸렸다. 그 사람 손가락이 셋 남았다.<br><br>줄을 잡긴 잡았다. 한 손으로. 당기는데 이쪽 허벅지가 풀렸다. 둘이 같이 미끄러졌다.<br>뒤에서 일행이 둘을 잡아 끌어올렸다. 이쪽 무릎이 갈빗대에 찍혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-17, mind:-6 } }
  ] },

{ at:'C4', t:'포자 온실 — 덩이를 지키는 일곱',
  x:`온실 한가운데 덩이가 뛴다. 둥. 뛸 때마다 노란 가루가 피고, 정원사들이 덩이 앞에 모여든다.<br><br>
    정원사가 일곱. 덩이를 지키는 대열이다. 덩이를 치려면 일곱을 넘어야 한다.<br>
    이쪽은 다섯이다. 다들 기침을 한다. 오래는 못 버틴다.<br><br>
    짧게 끝내야 한다.`,
  o:[
    { l:'① 쐐기 대열로 꿰뚫는다.', k:'fix', dc:15, wake:1,
      ok:`<span style="color:#d4af37;">"쐐기. 내가 끝. 둘 둘 뒤로. 멈추지 마."</span><br><br>이쪽이 쐐기 끝에 섰다. 넷이 뒤에서 양옆으로 벌어졌다. 정원사 일곱 한가운데로 파고들었다. 끝이 들어가면 양옆이 벌린다. 벌린 틈으로 뒤가 따라온다.<br>덩이까지 닿았다. 다섯 칼이 동시에 들어갔다. 덩이가 뛰다 멈췄다.<br><br>막는 대열만 짰었다. 오늘 처음 뚫는 대열을 짰다. 다섯이 칼 한 자루처럼 들어갔다. 대열이 방패만이 아니라 날도 될 수 있다는 걸 등 뒤의 넷이 보여 줬다.`,
      ng:`쐐기 끝으로 들어갔는데 뒤의 넷이 기침하느라 늦었다.<br><br>끝만 들어가고 몸통이 안 따라왔다. 정원사들 사이에 혼자 섰다. 실이 사방에서 감겼다.<br>넷이 와서 뜯어냈다. 이쪽 팔다리에 하얀 줄 자국이 남았다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-17, spirit:-8 } },
    { l:'② 무력을 써서 문짝으로 밀어붙인다.', k:'break', dc:15, cost:{ might:22 },
      ok:`쓰러진 문짝을 들고 맨 앞에서 밀었다. 정원사 셋이 문짝에 밀려 넘어졌다.<br><br>넘어진 것들 위로 넷이 넘어갔다. 덩이 앞에 닿았다.<br>이쪽은 문짝을 버티고 셋을 깔고 있었다. 다리가 후들거렸다.`,
      ng:`밀다가 문짝이 부러졌다.<br><br>정원사 셋이 일어나 이쪽을 감쌌다. 실 덩이가 얼굴을 덮었다.<br>칼로 찢고 나왔다. 숨을 한참 못 쉬었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-18, mind:-6 } },
    { l:'③ 느린 하나를 골라 대열에 구멍을 낸다.', k:'gaze', dc:14,
      ok:`정원사 일곱의 걸음을 봤다. 하나가 다른 여섯보다 느리다. 장화 한 짝이 벗겨졌다.<br><br>그 하나를 향해 소리를 지르게 했다. 느린 것이 돌아섰다. 여섯이 그것을 기다리느라 멈췄다. 대열에 구멍이 났다.<br>그 구멍으로 둘이 들어가 덩이 뿌리를 잘랐다.`,
      ng:`느린 것을 골랐는데 그것이 미끼였다.<br><br>소리에 돌아선 건 느린 것이 아니라 여섯이었다. 여섯이 동시에 이쪽을 봤다.<br>뛰었다. 노란 가루를 정면으로 맞았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-9 } }
  ] },

{ at:'C', t:'쉬는 자리 — 순번표에 없는 이름',
  x:`불침번을 짠다. 넷이 돌아가며 선다. 이쪽은 늘 빠졌다. 늘 밤새 깨어 있었으니까.<br><br>
    오늘은 다리가 안 움직인다. 눈꺼풀이 무겁다. 사흘째 제대로 안 잤다.<br>
    지친 사람이 서는 번은 번이 아니다.<br><br>
    순번표에 이쪽 이름이 없다.`,
  o:[
    { l:'① 순번표에 제 이름을 넣고 잔다.', k:'fix', dc:14, wake:1,
      ok:`순번표에 제 이름을 넣었다. 마지막 번. 그리고 누웠다.<br><br>넷이 돌아가며 섰다. 이쪽 없이. 밤새 무언가 두 번 다가왔다. 서 있던 사람이 다 쫓았다.<br>마지막 번에 깨어 섰다. 머리가 맑다. 동틀 녘의 어둠이 처음으로 덜 무거웠다.<br><br>다섯을 셀 때 제 머리는 늘 맨 끝에 셌다. 이제 제 머리도 다섯 중 하나로 센다. 제 몸을 셈에 넣는 법을 알았다. 쓰러지지 않는 것도 일이다.`,
      ng:`이름을 넣고 누웠는데 잠이 안 온다. 귀가 다 열려 있다.<br><br>무언가 다가오는 소리에 매번 일어났다. 결국 밤새 서 있던 셈이다.<br>아침에 눈이 벌겋다. 다리는 그대로 무겁다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ mind:-9, spirit:-8 } },
    { l:'② 오늘도 안 잔다.', k:'steady', dc:14,
      ok:`이름을 안 넣었다. 불 옆에 앉아 밤을 났다.<br><br>무언가 다가왔다. 일어나 쫓았다. 다시 앉았다.<br>동이 텄다. 다들 푹 잤다. 이쪽 눈 밑이 검다.`,
      ng:`앉아 있다가 졸았다. 앉은 채로.<br><br>깨어 보니 불이 꺼져 있다. 서 있던 사람도 졸았다. 둘레에 발자국이 잔뜩 찍혔다.<br>아무도 안 다쳤다. 운이었다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C', t:'사냥 뒤 — 똑같은 몫',
  x:`잡은 것의 굴을 뒤졌다. 그것이 모아 둔 것이 있다. 말린 고기 꾸러미, 물통 하나.<br><br>
    앞서 들어온 사람들 것이다. 그것이 빼앗아 쌓아 뒀다.<br>
    다들 배고프다. 많이 싸운 사람은 많이 먹고 싶다. 덜 싸운 사람도 배는 고프다.<br><br>
    몫을 나눠야 한다.`,
  o:[
    { l:'① 똑같이 나누고 제 몫도 똑같이 받는다.', k:'fix', dc:14,
      ok:`다섯 몫으로 똑같이 나눴다. 이쪽 몫도 똑같이.<br><br>많이 싸운 사람이 말을 꺼내려다 이쪽 몫을 보고 입을 다물었다. 이쪽이 제일 많이 싸웠다.<br>똑같이 받은 다섯은 조용해진다. 배는 덜 찼다. 마음은 찼다.`,
      ng:`똑같이 나눴는데 하나가 불만이다. 제가 더 싸웠다고.<br><br>말다툼이 길어졌다. 그 사이 꾸러미 하나가 바닥에 떨어져 진물에 젖었다.<br>한 몫이 사라졌다. 다들 조금씩 덜 먹었다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ mind:-8, spirit:-7 } },
    { l:'② 다친 사람에게 먼저 준다.', k:'heal', dc:13,
      ok:`다친 둘에게 먼저 한 몫 반씩 줬다. 나머지를 셋이 나눴다.<br><br>다친 둘이 먹고 일어섰다. 다음 사냥에 다섯이 다 섰다.<br>덜 먹은 셋 중 아무도 투덜대지 않았다. 다친 둘이 늘 앞에 섰던 사람들이다.`,
      ng:`다친 둘에게 줬는데 한 사람은 못 먹었다. 삼키질 못한다.<br><br>목에 무언가 걸려 있다. 하얀 실이다. 빼내느라 한참.<br>그 사이 다들 배고픈 채로 기다렸다.`,
      win:{ exp:15, dream:1, item:'맑은 물' }, lose:{ hp:-9, mind:-6 } }
  ] },

{ at:'C', t:'어둠 — 쉰 목',
  x:`목이 쉬었다. 구령을 너무 많이 붙였다. 노란 가루도 마셨다.<br><br>
    입을 열어도 바람 소리만 난다. 구령이 안 나온다.<br>
    앞에서 무언가 다가온다. 넷이 이쪽을 본다. 구령을 기다린다.<br><br>
    목소리 없는 분대장은 무엇인지, 지금 알게 된다.`,
  o:[
    { l:'① 손으로 구령을 붙인다.', k:'fix', dc:15, wake:1,
      ok:`손바닥을 펴서 들었다. 멈춤. 두 손가락으로 양옆을 가리켰다. 벌려. 주먹을 쥐고 앞으로 내렸다. 들어가.<br><br>넷이 손을 읽었다. 처음 보는 손짓인데 다 알아들었다. 날마다 이쪽 몸을 보고 움직였으니까.<br>다가오던 것을 양옆에서 덮쳤다. 끝났다.<br><br>구령은 목소리가 아니었다. 넷이 이쪽을 읽는 눈이었다. 목이 쉬어도 몸은 말을 한다. 몸 전체가 구령이 된다는 걸 쉰 목이 가르쳐 줬다.`,
      ng:`손을 들었는데 어두워서 손이 안 보인다.<br><br>넷이 머뭇거렸다. 다가오던 것이 먼저 닿았다. 제각각 싸웠다.<br>둘이 다쳤다. 이쪽 목에서 피 맛이 났다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 앞사람 어깨를 쳐서 구령을 건넨다.', k:'bond', dc:14,
      ok:`앞사람 어깨를 쳤다. 한 번은 멈춤, 두 번은 앞으로. 앞사람이 그 앞사람 어깨를 쳤다.<br><br>어깨에서 어깨로 구령이 건너갔다. 소리 없이.<br>다가오던 것이 아무 소리도 못 듣고 지나쳤다.`,
      ng:`어깨를 쳤는데 앞사람이 놀라 소리를 질렀다.<br><br>다가오던 것이 그 소리로 왔다. 다들 뛰었다.<br>이쪽은 쉰 목으로 기침을 하며 맨 뒤에서 뛰었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-11, spirit:-8 } }
  ] },

{ at:'C', t:'나가는 점호',
  x:`나가는 문 앞이다.<br><br>
    분대장은 들어갈 때 세고, 쉴 때 세고, 나올 때 센다. 마지막 셈이다.<br>
    다들 지쳤다. 셋은 업히거나 부축받는다. 그래도 서 있다.<br><br>
    문을 나가면 다시 셀 일이 없다. 이번 셈이 맞아야 한다.`,
  o:[
    { l:'① 이름을 하나씩 부른다.', k:'fix', dc:14,
      ok:`이름을 하나씩 불렀다. 넷이 대답했다. 쉰 목소리, 떨리는 목소리, 웃음 섞인 목소리.<br><br>마지막에 제 이름을 불렀다. 대답했다.<br>다섯. 맞다. 문을 나섰다.`,
      ng:`이름을 부르는데 뒤에서 대답이 하나 더 났다. 문 안쪽 어둠에서.<br><br>이쪽 이름이다. 이쪽 목소리다.<br>돌아보지 않고 문을 닫았다. 문 너머에서 한참 이쪽 이름이 불렸다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-8, spirit:-11 } },
    { l:'② 무력을 써서 맨 뒤에서 문을 지킨다.', k:'steady', dc:14, cost:{ might:15 },
      ok:`다 내보내고 맨 뒤에 섰다. 문을 등지고.<br><br>어둠 속에서 무언가 따라오는 소리가 났다. 문턱 앞에 버티고 섰다. 소리가 멈췄다.<br>마지막으로 나와서 문을 닫았다. 등으로 밀어서.`,
      ng:`맨 뒤에 섰는데 무언가 바짓단을 잡았다.<br><br>뿌리치는데 질기다. 칼로 바짓단째 잘랐다. 정강이도 같이 베였다.<br>문을 닫았다. 문 너머에서 천 찢는 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-7 } },
    { l:'③ 업힌 사람부터 내보낸다.', k:'bond', dc:13,
      ok:`업힌 셋부터 내보냈다. 업은 사람들이 먼저 나갔다. 이쪽은 문을 잡고 있었다.<br><br>밖에서 셌다. 다섯. 이쪽이 마지막으로 나왔다.<br>바깥바람에 다들 한꺼번에 주저앉았다.`,
      ng:`업은 사람 하나가 문턱에 걸려 넘어졌다.<br><br>업힌 사람이 문턱에 머리를 찧었다. 일으켜 내보냈다.<br>밖에서 그 사람이 한참 어지럽다고 했다.`,
      win:{ exp:15, hp:6 }, lose:{ hp:-10, mind:-6 } }
  ] }

]);

// ── 진법가 ──────────────────────────────
kJob('formation', 'C', [

{ at:'C', t:'첫 방 — 숨 쉬는 벽의 방위',
  x:`첫 방 벽이 숨을 쉰다. 부풀었다 꺼진다. 산 것의 안쪽이다.<br><br>
    방위를 잡으려면 북을 알아야 한다. 산 것 안에는 북이 없다. 대신 산 것에는 머리와 꼬리가 있다.<br>
    숨이 들어오는 쪽이 머리다. 나가는 쪽이 꼬리다.<br><br>
    머리를 북으로 잡으면 진이 선다. 틀리면 사문으로 들어간다.`,
  o:[
    { l:'① 내공을 실어 벽의 숨길을 짚는다.', k:'fix', dc:14, cost:{ qi:16 },
      ok:`호흡을 고르고 내공을 손바닥까지 내렸다. 벽에 손을 대고 한 바퀴 돌았다.<br><br>한쪽 벽에서 손바닥이 빨려 든다. 숨이 들어가는 쪽이다. 거기를 북으로 잡았다. 북에서 셈해 생문을 찾았다. 동남쪽 틈이다.<br>그 틈으로 나가니 숨이 덜 끈적한 통로다.<br><br>산 것의 방위는 땅의 방위보다 정직하다. 숨은 거짓말을 못 한다.`,
      ng:`손바닥이 빨려 든 데를 북으로 잡았는데 거기가 꼬리였다. 숨이 거꾸로 돈다.<br><br>생문이라 잡은 틈 너머에서 미지근한 바람이 훅 불었다. 비린내가 났다.<br>되돌아왔다. 손바닥에 진물이 묻어 한참 따끔거렸다.`,
      win:{ exp:18, dream:2, mind:5 }, lose:{ hp:-11, spirit:-7 } },
    { l:'② 바닥 물기가 흐르는 쪽을 따른다.', k:'sense', dc:14,
      ok:`바닥에 고인 물기가 한쪽으로 흐른다. 숨이 빨아들이는 쪽이다.<br><br>그쪽을 북으로 잡았다. 셈은 맞았다. 생문 쪽 틈으로 나갔다.<br>틀려도 하나를 정해야 진이 선다. 오늘은 맞게 정했다.`,
      ng:`물기를 따라가니 물기가 이쪽 발을 따라온다.<br><br>물이 아니다. 바닥에서 배어 나온 진물이 사람 발을 찾는다.<br>장화 밑창이 녹았다. 발바닥이 따갑다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-6 } }
  ] },

{ at:'C1', t:'도축장 — 도는 팔문',
  x:`천장 쇠줄이 작업장을 한 바퀴 돈다. 고리다. 갈고리 여덟이 매달려 돈다.<br><br>
    고리는 진이다. 여덟 갈고리가 여덟 문이다. 돌아가는 팔문진(八門陣)이다.<br>
    돌아가는 진은 문이 자리를 바꾼다. 생문이 지금은 동쪽에 있고, 다음에는 남쪽에 있다.<br><br>
    생문 갈고리 밑으로만 지나가야 한다.`,
  o:[
    { l:'① 돌아가는 생문을 쫓아 지난다.', k:'fix', dc:15, wake:1,
      ok:`갈고리를 셌다. 휴, 생, 상, 두. 생문 갈고리에는 고기가 안 걸려 있다. 매번 비어 있다. 비어서 생문이다.<br><br>그 갈고리 밑을 따라 걸었다. 갈고리가 가면 같이 가고, 서면 같이 섰다. 다섯이 한 줄로 생문 밑에 붙어 다녔다.<br>반 바퀴 돌아 반대편 문에 닿았다. 아무도 안 걸렸다.<br><br>선 진만 읽었었다. 오늘은 도는 진을 읽었다. 진이 돌면 이쪽도 돌면 된다. 움직이는 판 위에서 생문을 놓치지 않는 눈이 생겼다.`,
      ng:`생문 갈고리를 쫓는데 줄이 빨라졌다. 생문이 앞서 나갔다.<br><br>놓쳤다. 다음 문은 상문(傷門)이다. 그 갈고리 밑에 서 있던 셋째가 어깨를 찍혔다.<br>상문은 다치는 문이다. 셈은 맞았다. 걸음이 늦었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-15, mind:-7 } },
    { l:'② 갈고리 하나를 떼어 진을 깬다.', k:'break', dc:14,
      ok:`낮게 지나가는 갈고리 하나를 붙잡아 줄에서 떼어 냈다. 여덟이 일곱이 됐다.<br><br>일곱 문 진은 없다. 진이 깨지자 갈고리들이 엉키며 줄이 섰다.<br>선 줄 밑을 다섯이 지났다.`,
      ng:`떼어 내려는데 갈고리가 안 떨어졌다. 이쪽이 매달렸다.<br><br>줄이 이쪽을 싣고 반 바퀴를 돌았다. 놓고 떨어졌다. 고기 통에 처박혔다.<br>통 속 고기가 이쪽 팔을 감았다. 떼어 내느라 한참.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 아무는 맥',
  x:`고기 짐승은 자르면 붙는다. 숨 열 번이면 붙는다.<br><br>
    붙는 것도 기의 흐름이다. 잘린 자리로 기가 몰려가 실을 뻗게 한다. 기가 도는 길이 있다. 맥이다.<br>
    짐승 몸에 맥이 그어져 있다. 그 맥이 모이는 자리가 진의 눈처럼 하나 있을 것이다.<br><br>
    일행이 지쳐 간다.`,
  o:[
    { l:'① 내공을 실어 살의 맥을 끊는다.', k:'fix', dc:15, cost:{ qi:20 }, wake:1,
      ok:`짐승 등에 손바닥을 붙였다. 내공을 실어 기를 짚었다. 등줄기 셋째 마디에서 기가 모였다 흩어진다. 눈이다.<br><br>그 자리에 손날을 내리꽂으며 내공을 밀어 넣었다. 맥이 끊겼다. 잘린 자리로 가던 기가 길을 잃었다.<br>칼이 들어갔다. 붙지 않았다.<br><br>땅에 놓인 진을 읽던 눈으로 산 것의 몸을 읽었다. 몸도 진이다. 눈을 끊으면 진이 무너진다. 진을 놓는 손이 진을 끊는 손도 된다는 걸 알았다.`,
      ng:`셋째 마디를 짚었는데 기가 이쪽 손으로 몰려왔다. 잘린 데인 줄 안 것이다.<br><br>손바닥에서 실이 뻗었다. 짐승 살과 이쪽 손이 붙으려 한다.<br>칼로 그었다. 손바닥 살갗이 벗겨진 채 떨어졌다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-16, mind:-7 } },
    { l:'② 소금으로 둘레를 그어 기를 가둔다.', k:'steady', dc:14,
      ok:`소금 덩이를 부숴 짐승 둘레에 원을 그었다. 소금은 기를 막는다.<br><br>원 안의 기가 밖으로 못 나간다. 밖의 기가 안으로 못 들어온다. 짐승이 붙는 게 느려졌다.<br>느려진 틈에 일행이 끝냈다. 남은 소금은 챙겼다.`,
      ng:`원을 다 긋기 전에 짐승이 원을 넘었다.<br><br>반만 그은 원은 원이 아니다. 짐승이 이쪽 발목을 물었다.<br>뿌리쳤다. 소금이 다 흩어졌다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-13, mind:-6 } },
    { l:'③ 맥이 모이는 자리를 짚어 준다.', k:'gaze', dc:15,
      ok:`짐승이 움직일 때마다 살결이 한 점으로 모인다. 왼쪽 앞다리 겨드랑이.<br><br>창 든 사람에게 그 자리를 손가락으로 찍어 보였다. 창이 그리로 들어갔다.<br>짐승이 붙는 것을 멈췄다. 맥이 끊겼다.`,
      ng:`짚었는데 짐승이 몸을 틀었다. 자리가 바뀌었다.<br><br>창이 엉뚱한 데 들어갔다. 거기가 바로 붙었다. 창이 살에 물렸다.<br>창을 놓고 물러났다. 창 하나를 잃었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-7 } }
  ] },

{ at:'C2', t:'인형 공방 — 실의 그물진',
  x:`천장에서 실이 내려와 공방을 가로지른다. 가로세로로 엮였다. 그물이다.<br><br>
    그물도 진이다. 실이 만나는 매듭마다 문이 있다. 매듭 하나를 건드리면 그물 전체가 그 매듭 쪽으로 조인다.<br>
    그물 한가운데 매듭이 진의 눈이다. 거기 인형 하나가 매달려 있다. 이를 딸깍인다.<br><br>
    그물을 지나야 공방 계단에 닿는다.`,
  o:[
    { l:'① 진의 눈 매듭을 푼다.', k:'fix', dc:15,
      doom:{ title:'그물 한가운데', what:'실 그물이 감아 천장으로 끌어올립니다', dc:15, sec:60,
        text:`실 사이로 몸을 넣어 한가운데 매듭에 손을 댔다. 눈을 풀면 진이 풀린다.<br><br>매듭이 풀렸다. 그물이 풀리지 않았다. 조였다. 이쪽 쪽으로. 눈이 비자 그물이 새 눈을 찾았다. 한가운데 선 사람.<br>실이 손목, 목, 허리를 감았다. 매달린 인형 자리로 이쪽이 끌려 올라간다.<br><br>인형이 떨어지며 이쪽 발밑에서 딸깍였다. 자리를 내준 것이다.`,
        dieText:`공방 그물 한가운데 매듭에 새것이 매달렸다.<br><br>사람만 하다. 실이 감긴 채 천천히 돈다.<br>그물을 지나는 다음 사람은 그 매듭을 진의 눈으로 볼 것이다. 실제로 그렇다.` },
      ok:`실 사이로 몸을 넣어 한가운데 매듭에 손을 댔다. 풀기 전에 매달린 인형을 먼저 뜯어 쥐었다. 눈을 비우지 않고 바꿨다.<br><br>인형 대신 돌멩이 하나를 매듭에 매달고 매듭을 풀었다. 그물이 돌 쪽으로 조였다. 사람 쪽이 아니라.<br>조인 그물 밑으로 공간이 났다. 다섯이 기어서 계단까지 갔다.<br><br>눈은 비우면 새 눈을 찾는다. 비우지 말고 바꿔야 한다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 매듭을 피해 실 사이로 기어간다.', k:'evade', dc:14,
      ok:`매듭을 하나도 안 건드리고 실 사이로 몸을 넣었다. 가로 실 밑, 세로 실 옆.<br><br>그물은 매듭으로만 조인다. 실에 닿아도 매듭에 안 닿으면 된다.<br>다섯이 차례로 기었다. 계단에 닿았다. 등 뒤에서 인형이 딸깍였다. 아무것도 못 잡은 소리다.`,
      ng:`기는데 등짐 끈이 매듭에 걸렸다.<br><br>그물이 그쪽으로 조였다. 실이 목을 스쳤다. 살갗이 쓸렸다.<br>등짐을 버리고 빠져나왔다. 그물이 등짐을 꽉 쥐었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'인형 공방 — 아홉 인형의 구궁',
  x:`공방 진열장에 인형이 놓여 있다. 아홉. 세 줄로 셋씩.<br><br>
    아홉이면 구궁(九宮)이다. 놓인 자리가 진이다. 인형 얼굴이 향한 방위가 다 다르다.<br>
    그 진이 공방 문을 닫고 있다. 문이 안 열린다.<br><br>
    인형은 진의 돌이다. 돌을 옮기면 진이 바뀐다. 이 돌은 이빨이 있다.`,
  o:[
    { l:'① 인형 하나를 돌려 진을 바꾼다.', k:'fix', dc:15, wake:1,
      ok:`아홉 중 어느 것이 문을 닫는지 셈했다. 가운데 줄 오른쪽. 그 얼굴만 문을 본다.<br><br>그 인형 목덜미를 잡아 얼굴을 돌렸다. 손가락을 물기 전에. 반대 방위로.<br>문이 덜컥 열렸다. 진이 바뀌었다. 닫는 진에서 여는 진으로.<br><br>진을 깨지 않고 돌 하나 방향만 바꿨다. 깨는 것보다 바꾸는 쪽이 진에 덜 들킨다. 남이 놓은 진을 부수지 않고 제 쪽으로 돌려 쓰는 손이 생겼다.`,
      ng:`돌리는데 인형이 이쪽 손가락을 물었다.<br><br>사기 이가 뼈까지 들어왔다. 놓쳤다. 인형이 원래 방위로 돌아갔다. 진이 그대로다.<br>손가락에서 피가 뚝뚝 떨어진다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 내공을 실어 진의 기를 흐트러뜨린다.', k:'gaze', dc:15, cost:{ qi:18 },
      ok:`진열장 앞에 서서 내공을 끌어올려 아홉 칸에 고루 뿌렸다.<br><br>진의 기가 흐트러졌다. 인형들이 동시에 고개를 까딱였다. 방위를 잃었다.<br>문이 반쯤 열렸다. 다섯이 몸을 옆으로 해서 빠져나갔다.`,
      ng:`내공을 뿌렸는데 진이 그것을 먹었다.<br><br>인형 아홉의 눈이 동시에 빛났다. 기를 얻은 돌이다.<br>아홉이 진열장에서 뛰어내렸다. 문 밖까지 쫓아왔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, spirit:-7 } }
  ] },

{ at:'C', t:'쉬는 자리 — 피 냄새를 가두는 원',
  x:`사냥 뒤 쉬는 자리. 다친 사람이 셋이다. 피 냄새가 짙다.<br><br>
    여기 것들은 피 냄새를 따라온다. 쉬는 동안 몇 번은 올 것이다.<br>
    냄새도 기를 탄다. 기를 돌려 놓으면 냄새도 돌아간다.<br><br>
    돌 넷과 사람 다섯이 있다.`,
  o:[
    { l:'① 내공을 실어 냄새를 가두는 진을 놓는다.', k:'fix', dc:14, cost:{ qi:16 },
      ok:`돌 넷을 사방에 놓고 손바닥으로 이었다. 내공이 돌에서 돌로 건너갔다. 기가 원으로 돌기 시작했다.<br><br>피 냄새가 원을 따라 돌며 갇혔다. 바깥으로 안 샌다.<br>밤새 둘레에서 무언가 킁킁대다 지나갔다. 들어오지 않았다.`,
      ng:`넷째 돌을 잇다가 내공이 끊겼다.<br><br>원이 다 안 닫혔다. 그 틈으로 냄새가 한 줄기 새어 나갔다. 줄기를 따라 무언가 왔다.<br>쫓는 동안 이쪽이 물렸다. 다친 사람이 넷이 됐다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 사문 쪽에 피 묻은 천을 걸어 둔다.', k:'sense', dc:14,
      ok:`피 묻은 천을 모아 쉬는 자리 사문 쪽 멀리에 걸었다.<br><br>냄새가 그쪽으로 끈다. 사문 쪽은 비탈이다.<br>밤새 비탈에서 무언가 구르는 소리가 났다. 쉬는 자리는 조용했다.`,
      ng:`천을 거는데 방위를 잘못 셈했다. 생문 쪽이었다.<br><br>냄새를 따라온 것이 생문으로, 쉬는 자리 쪽으로 왔다.<br>밤새 막대기를 휘둘렀다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-11, mind:-7 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 뒤집힌 팔문',
  x:`성당이 거꾸로 서 있다. 둥근 천장을 밟고 걷는다.<br><br>
    진법가는 성당을 보면 문부터 센다. 이 성당에도 문이 여덟이다. 팔방으로.<br>
    그런데 거꾸로 섰다. 위와 아래가 바뀌면 남과 북이 바뀐다. 남북이 바뀌면 생문과 사문이 자리를 맞바꾼다.<br><br>
    늘 하던 셈대로 하면 사문을 연다.`,
  o:[
    { l:'① 셈을 통째로 뒤집는다.', k:'fix', dc:15, wake:1,
      ok:`셈을 뒤집었다. 북을 남으로. 동서는 그대로. 거꾸로 선 데서도 해 뜨는 쪽은 그대로다. 위아래만 바뀐다.<br><br>뒤집어 셈하니 생문이 늘 사문 자리에 있다. 그 문을 열었다. 마른 회랑이 나왔다.<br>늘 하던 셈의 사문이었다. 몸이 그 문을 거부했다. 거부하는 몸을 끌고 들어갔다. 맞았다.<br><br>셈을 외운 것과 셈을 아는 것이 다르다. 판이 뒤집혀도 셈이 따라 뒤집힌다. 손에 붙은 셈을 머리로 다시 짜는 법을 알았다.`,
      ng:`뒤집는다고 뒤집었는데 동서까지 뒤집었다.<br><br>생문인 줄 연 문 너머가 경문(驚門)이다. 매달린 무언가가 얼굴 앞에 툭 떨어졌다. 놀랐다.<br>놀라서 넘어졌다. 갈빗대에 등이 찍혔다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ hp:-12, spirit:-9 } },
    { l:'② 문틈마다 바람을 대 본다.', k:'sense', dc:14,
      ok:`셈을 버리고 문틈마다 손을 댔다. 바람이 들어오는 문, 나가는 문.<br><br>들어오는 문 하나가 마른 바람이다. 그 문을 열었다. 셈 없이 맞았다.<br>셈이 뒤집힌 데서는 손바닥이 낫다.`,
      ng:`문틈에 손을 대는데 틈 너머에서 무언가 손가락을 핥았다.<br><br>얼른 뺐다. 손가락이 차갑게 젖었다.<br>그 문은 안 열었다. 다른 문들도 무서워서 다 못 댔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-8, spirit:-9 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 일곱 종의 칠성',
  x:`둥근 천장 위에 종이 일곱. 북두 모양으로 놓였다.<br><br>
    칠성진(七星陣)이다. 하나가 울면 다음이 울고, 일곱이 차례로 울면 소리가 진 안을 돈다. 도는 소리 속에 든 것은 귀가 먼다.<br>
    종 안에는 소리로 사냥하는 것들이 산다. 귀 먼 것을 혀로 감아 들인다.<br><br>
    진을 지나야 회랑에 닿는다.`,
  o:[
    { l:'① 내공을 실어 넷째 종의 떨림을 붙잡는다.', k:'fix', dc:15, cost:{ qi:20 },
      ok:`일곱 중 넷째 종에 손바닥을 붙였다. 북두의 허리다. 내공을 밀어 넣어 종의 떨림을 붙잡았다.<br><br>첫째부터 셋째까지 울렸다. 넷째에서 소리가 멎었다. 다섯째가 받을 소리가 없다.<br>진이 반쪽으로 끊겼다. 소리가 돌지 않았다. 다섯이 그 사이로 지났다.<br><br>손바닥이 한참 떨렸다. 종 하나 몫을 혼자 받았다.`,
      ng:`넷째 종을 붙잡았는데 떨림이 이쪽 팔로 왔다.<br><br>팔뼈가 울었다. 손을 뗐다. 넷째가 울었다. 다섯째, 여섯째.<br>소리가 진을 돌았다. 귀가 먹먹하다. 혀 하나가 발목을 감았다가 놓았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-13, spirit:-9 } },
    { l:'② 국자 손잡이 끝 생문으로 돈다.', k:'gaze', dc:14,
      ok:`칠성진에도 생문은 있다. 국자 손잡이 끝, 일곱째 종 바깥.<br><br>그쪽으로 돌았다. 멀다. 종 소리가 거기까지는 덜 닿는다.<br>먼 길로 다섯이 다 돌았다. 아무도 귀가 안 멀었다.`,
      ng:`일곱째 종 바깥으로 도는데 거기 종이 하나 더 있었다. 여덟째.<br><br>칠성이 아니었다. 셈이 틀렸다. 여덟째가 울었다.<br>귀가 먹먹한 사이 혀가 나와 어깨를 쓸었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'③ 첫째 종에 금을 낸다.', k:'break', dc:15,
      ok:`국자 머리, 첫째 종. 소리가 시작되는 자리다.<br><br>쇠막대로 종 테두리를 내리쳤다. 금이 갔다. 금 간 종은 울어도 소리가 탁하다. 탁한 소리는 다음 종을 못 깨운다.<br>진이 시작부터 막혔다.`,
      ng:`내리쳤는데 종이 울었다. 금 가기 전에.<br><br>첫째가 울자 일곱이 다 울었다. 진이 돌았다.<br>귀를 막고 엎드렸다. 혀가 등을 몇 번 핥고 지나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-7 } }
  ] },

{ at:'C4', t:'포자 온실 — 여덟 화단',
  x:`온실 화단이 여덟 칸이다. 가운데 덩이를 두고 팔방으로.<br><br>
    여덟 칸이면 팔문이다. 정원사들이 놓은 진이다. 물길과 볕을 고르게 받으라고.<br>
    지금은 곰팡이가 그 진을 쓴다. 노란 가루가 진의 기를 타고 칸에서 칸으로 흐른다.<br><br>
    가루가 안 흐르는 칸이 생문이다.`,
  o:[
    { l:'① 기가 흐르지 않는 칸으로 걷는다.', k:'fix', dc:14,
      ok:`칸마다 가루가 떠도는 모양을 봤다. 일곱 칸은 가루가 돈다. 한 칸만 가라앉았다. 휴문(休門)이다. 쉬는 문.<br><br>휴문 칸으로만 걸었다. 가루가 발밑에 깔려 있을 뿐 떠오르지 않는다.<br>덩이 근처까지 아무도 기침하지 않았다.<br><br>휴문 칸 화단 흙에 산나물이 났다. 곰팡이가 안 먹은 것이다.`,
      ng:`가라앉은 칸으로 갔는데 가라앉은 게 아니라 고인 것이었다.<br><br>발을 디디자 가루가 한꺼번에 피어올랐다. 두문(杜門)이었다. 막힌 문.<br>숨이 막혔다. 기어서 나왔다.`,
      win:{ exp:18, dream:2, item:'산나물' }, lose:{ hp:-12, spirit:-9 } },
    { l:'② 내공을 끌어올려 가루를 밀어 길을 낸다.', k:'break', dc:15, cost:{ qi:18 },
      ok:`두 손바닥을 모아 내공을 끌어올렸다. 앞으로 밀었다.<br><br>가루가 밀려 갈라졌다. 갈라진 사이로 길이 났다. 다섯이 그 길을 뛰었다.<br>손목이 시큰거린다. 기를 밀면 기도 민 사람을 민다.`,
      ng:`밀었는데 가루가 되밀려 왔다. 진의 기가 이쪽 기를 받아쳤다.<br><br>얼굴에 노란 것이 덮였다. 눈과 코.<br>일행이 끌어냈다. 한참 기침했다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C4', t:'포자 온실 — 정원사들이 놓은 돌',
  x:`온실 구석에 돌이 둥글게 놓여 있다. 일곱. 원래 여덟이었을 것이다.<br><br>
    돌 놓인 모양이 진이다. 정원사들이 놓은, 곰팡이를 막는 진. 원 안에는 곰팡이가 없다. 하얀 실이 원 가장자리에서 멈췄다.<br>
    하나가 빠져서 진이 반쯤 열려 있다. 빠진 자리로 실이 조금씩 기어든다.<br><br>
    원 안에 정원사들 연장이 있다. 원 밖에 정원사들이 걷는다. 옷만.`,
  o:[
    { l:'① 빠진 돌을 마저 놓는다.', k:'fix', dc:15, wake:1,
      ok:`비슷한 크기 돌을 찾아 빠진 자리에 놓았다. 앞사람 셈을 따라가니 자리가 정확히 보였다.<br><br>마지막 돌을 놓자 원 둘레 공기가 바뀌었다. 기어들던 실이 오그라들며 물러났다. 다섯이 원 안에서 처음으로 깊게 숨을 쉬었다.<br>정원사 옷들이 원 둘레를 맴돌다 갔다.<br><br>남이 놓다 만 진을 마저 놓았다. 앞사람 셈을 읽는 일이 제 셈을 짜는 일보다 어려웠다. 그 어려운 쪽이 이제 손에 익는다. 진은 놓은 사람이 떠나도 이어 놓을 수 있다.`,
      ng:`돌을 놓았는데 크기가 조금 작았다.<br><br>진이 닫히다 말았다. 실이 그 틈으로 몰려들었다. 원 안이 하얗게 덮이기 시작했다.<br>돌을 빼고 도망쳤다. 원 안의 연장은 다 실에 먹혔다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ hp:-12, spirit:-10 } },
    { l:'② 원 안에서 등으로 빈 자리를 막고 쉰다.', k:'steady', dc:14,
      ok:`원 안으로 들어가 앉았다. 빠진 자리 쪽은 이쪽이 등으로 막았다.<br><br>반쯤 열린 진이라도 안은 바깥보다 낫다. 한 시진 쉬었다.<br>등 뒤로 실이 기어오는 게 느껴졌다. 일어날 때 털었다.`,
      ng:`앉아 있는데 등 뒤 빈 자리로 실이 들어왔다.<br><br>옷 속으로 파고들었다. 일어났을 때 등이 하얗게 덮였다.<br>옷을 벗어 버렸다. 등이 한참 따끔거렸다.`,
      win:{ exp:15, hp:6 }, lose:{ hp:-11, spirit:-8 } },
    { l:'③ 원 안 연장 상자를 연다.', k:'luck', dc:14,
      ok:`원 안 연장 상자를 열었다. 삽, 가위, 기름종이에 싼 꾸러미.<br><br>꾸러미 안에 약초가 말려 있다. 정원사들이 기르던 것이다. 곰팡이가 못 들어온 데서 말린 것이라 깨끗하다.<br>챙겼다.`,
      ng:`상자를 여는데 안에서 실이 쏟아졌다. 상자는 원 경계에 걸쳐 있었다.<br><br>반은 안, 반은 밖. 밖 쪽이 먹혔다.<br>손등에 실이 붙어 하얗게 일어났다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-10, spirit:-9 } }
  ] },

{ at:'C', t:'사냥 — 사람으로 놓는 진',
  x:`큰 것이 나왔다. 빠르다. 다섯이 둘러싸도 빈 데로 빠진다.<br><br>
    돌로 진을 놓을 시간은 없다. 돌 대신 사람이 있다. 다섯.<br>
    다섯이 다섯 방위에 서면 오행진이다. 서로가 서로를 살리는 자리와 막는 자리가 있다.<br><br>
    그것이 빈 데를 찾아 둘레를 돈다.`,
  o:[
    { l:'① 내공을 실어 다섯을 오행으로 잇는다.', k:'fix', dc:15, cost:{ qi:22 }, wake:1,
      ok:`다섯을 다섯 방위에 세웠다. 이쪽은 토(土), 가운데. 호흡을 맞추고 내공을 사방으로 펼쳤다. 넷 손바닥으로 기가 건너갔다.<br><br>그것이 빈 데를 찾았다. 없다. 한 방위로 뛰어들면 양옆 방위가 막는다. 막는 자리가 살리는 자리를 지킨다.<br>세 번 뛰어들고 세 번 막혔다. 네 번째에 넷이 동시에 쳤다.<br><br>사람이 돌보다 잘 돈다는 건 알았다. 오늘은 사람 진이 싸웠다. 진이 막기만 하는 게 아니라 칼을 쥘 수도 있다. 진 가운데 선 몸이 그걸 처음 느꼈다.`,
      ng:`펼치는데 하나가 겁을 먹고 방위를 벗어났다.<br><br>진에 구멍이 났다. 그것이 그 구멍으로 뛰어들었다. 가운데 이쪽 쪽으로.<br>막았다. 어깨가 물렸다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-17, mind:-6 } },
    { l:'② 사문 쪽 막다른 데로 몬다.', k:'gaze', dc:15,
      ok:`방의 생문과 사문을 셈했다. 사문 쪽은 막다른 구석이다.<br><br>네 사람이 소리를 지르며 그쪽으로 몰았다. 그것이 사문으로 뛰어들었다. 구석이다. 갈 데가 없다.<br>사문은 들어간 것이 못 나오는 문이다. 사람에게도 짐승에게도.`,
      ng:`사문 쪽으로 몰았는데 그것이 그쪽을 알았다. 짐승도 사문을 안다.<br><br>돌아서 생문으로 뛰었다. 생문 앞에 이쪽이 서 있었다.<br>들이받혔다. 갈비뼈가 결린다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'③ 빠지는 데마다 돌 하나라도 박는다.', k:'steady', dc:14,
      ok:`그것이 빠지는 빈 데마다 돌을 하나씩 박았다. 진이라기엔 엉성하다.<br><br>돌 하나에 그것이 한 번씩 멈칫했다. 멈칫하는 동안 일행이 쳤다.<br>엉성한 진도 진이다. 오래 걸렸다.`,
      ng:`돌을 박는데 그것이 돌을 걷어찼다.<br><br>돌이 날아와 이쪽 정강이를 쳤다. 주저앉았다.<br>일행이 끝냈다. 이쪽은 앉아서 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-5 } }
  ] },

{ at:'C1', t:'도축장 — 도축장의 눈',
  x:`갈고리 줄, 작업대, 고기 통이 작업장 안에 둥글게 놓였다. 다 한 자리를 향한다.<br><br>
    그 자리에 앞치마 두른 큰 것이 선다. 진의 눈이다. 도축장 전체가 그것을 중심으로 돈다.<br>
    눈에 선 것은 진의 기를 다 받는다. 그래서 지치지 않는다. 칼질이 안 멈춘다.<br><br>
    눈에서 떼어 놓으면 지친다.`,
  o:[
    { l:'① 그것을 진의 눈에서 끌어낸다.', k:'fix', dc:15,
      doom:{ title:'빈 눈', what:'도축장 진의 눈으로 끌려 들어갑니다', dc:15, sec:55,
        text:`고기 통 하나를 굴려 그것의 발밑을 쳤다. 그것이 비틀거리며 한 걸음 물러났다. 눈에서 벗어났다.<br><br>눈이 비었다. 도축장이 새 눈을 찾았다. 갈고리, 작업대, 통이 한꺼번에 기울었다. 이쪽 쪽으로.<br>눈 가까이 선 사람이 이쪽이다. 바닥이 이쪽을 한가운데로 끌어당긴다.<br><br>갈고리들이 머리 위로 몰려온다. 칼질 소리가 이쪽 등 뒤에서 다시 시작된다.`,
        dieText:`도축장 한가운데에 새것이 선다.<br><br>앞치마는 없다. 손에 칼도 없다. 다만 지치지 않는다.<br>갈고리 줄이 그것을 중심으로 돈다. 다음 사람은 그것이 무엇인지 모를 것이다. 사람 모양이다.` },
      ok:`고기 통 하나를 굴려 그것의 발밑을 쳤다. 그것이 비틀거리며 한 걸음 물러났다. 눈에서 벗어났다.<br><br>눈이 비기 전에 고기 통을 그 자리에 세웠다. 눈을 비우지 않고 바꿨다.<br>도축장이 통을 눈으로 삼았다. 그것은 눈 밖에서 처음으로 숨을 헐떡였다. 칼질이 느려졌다.<br><br>느려진 칼 사이로 넷이 들어갔다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 그것이 눈을 비킬 때를 기다린다.', k:'hide', dc:15,
      ok:`고기 통 뒤에 숨어 기다렸다. 그것도 가끔 칼을 갈러 눈을 비킨다.<br><br>숫돌 앞으로 갔다. 눈에서 세 걸음. 그 세 걸음 동안 칼질이 처음으로 멈췄다.<br>그 틈에 다섯이 지나갔다. 그것이 돌아왔을 때는 아무도 없었다.`,
      ng:`기다리는데 그것이 눈을 안 비켰다. 칼을 눈 자리에서 갈았다.<br><br>오래 기다렸다. 숨긴 몸이 저렸다. 하나가 발을 고쳐 디디다 통을 찼다.<br>그것이 돌아봤다. 칼이 날아와 통을 갈랐다. 통 안 고기가 쏟아져 이쪽을 덮었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, spirit:-7 } }
  ] },

{ at:'C2', t:'인형 공방 — 위층이 그린 진도',
  x:`위층 계단 밑 바닥에 숯으로 그린 그림이 있다. 진도다.<br><br>
    선이 곧다. 공방 전체의 실과 진열장과 문이 다 그려져 있다. 위층에 있는 것이 그렸다. 인형을 놓는 자리, 실을 거는 자리.<br>
    한 군데만 비었다. 위층 계단 자리. 거기는 그리다 말았다.<br><br>
    그리다 만 자리가 진의 빈틈이다.`,
  o:[
    { l:'① 진도를 외워 빈틈으로 오른다.', k:'gaze', dc:15,
      ok:`손대지 않고 진도를 눈으로 외웠다. 실이 지나가는 길, 인형이 보는 방향.<br><br>그리다 만 계단 자리로만 디뎠다. 진이 그 자리를 모른다. 모르는 자리는 지키지 않는다.<br>다섯이 차례로 계단을 올랐다. 실 하나 안 흔들렸다.`,
      ng:`외우는데 선이 움직였다. 숯이 번지는 게 아니다.<br><br>그리다 만 자리에 선이 하나 그어졌다. 방금. 위층에서 이쪽을 본 것이다.<br>빈틈이 닫혔다. 실이 계단을 가로질러 내려왔다. 목을 스쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-13, spirit:-8 } },
    { l:'② 내공을 실어 진도에 한 획을 더 긋는다.', k:'fix', dc:15, cost:{ qi:18 },
      ok:`숯 조각을 주워 내공을 실었다. 진도의 문 자리에 한 획을 그었다. 닫는 문을 여는 문으로.<br><br>공방 전체가 한 번 떨렸다. 그린 진을 따라 실제 진이 바뀌었다. 문이 열리고 실이 느슨해졌다.<br>위층에서 무언가 숯을 부러뜨리는 소리가 났다.<br><br>남의 진도에 이쪽 선을 섞었다. 그린 것은 지금 그 선을 보고 있을 것이다.`,
      ng:`획을 긋는데 숯이 이쪽 손을 끌었다. 그린 것의 손버릇대로.<br><br>선이 엉뚱한 데로 갔다. 닫는 문이 하나 더 생겼다. 계단이 막혔다.<br>다른 길로 돌았다. 실에 손목이 두 번 쓸렸다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, spirit:-9 } }
  ] },

{ at:'C', t:'어둠 — 거꾸로 도는 기',
  x:`여기 들어오고 나서 기가 거꾸로 돈다. 단전에서 올라와야 할 것이 발끝으로 빠진다.<br><br>
    호흡을 고르면 고를수록 더 빠진다. 이곳이 이쪽 기를 빨아 제 진에 보탠다.<br>
    다리가 무겁다. 손끝이 차다.<br><br>
    기를 지키는 진을 제 몸에 놓아야 한다.`,
  o:[
    { l:'① 호흡을 끊어 짧게 쉰다.', k:'steady', dc:15,
      ok:`길게 쉬지 않았다. 짧게, 짧게. 기가 돌 틈을 안 줬다.<br><br>도는 기가 없으니 빠질 기도 없다. 빠지던 것이 멈췄다.<br>답답하다. 그래도 다리가 가벼워졌다.`,
      ng:`짧게 쉬다 숨이 찼다. 한 번 길게 들이켰다.<br><br>그 한 번에 기가 쏟아져 나갔다. 무릎이 꺾였다.<br>한참 앉아 있었다. 일어나니 머리가 핑 돌았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-9 } },
    { l:'② 내공을 실어 발밑에 막는 진을 찍는다.', k:'fix', dc:15, cost:{ qi:15 },
      ok:`발밑 네 귀퉁이에 손바닥을 찍었다. 내공을 조금씩. 사방을 막는 작은 진. 사람 하나 설 만큼.<br><br>발끝으로 빠지던 기가 진에 막혔다. 다시 위로 돌았다.<br>일행에게도 하나씩 찍어 줬다. 다섯 개의 작은 진이 걸어 다녔다.<br><br>진은 땅에 놓는 줄 알았다. 신발 밑에도 놓인다.`,
      ng:`넷째 귀퉁이를 찍다 내공이 빠져나갔다. 진이 기를 막기 전에 기가 먼저 나갔다.<br><br>세 귀퉁이 진은 진이 아니다. 오히려 기가 그 틈으로 몰렸다.<br>주저앉았다. 일행이 부축했다.`,
      win:{ exp:20, dream:2, mind:5 }, lose:{ mind:-11, spirit:-8 } }
  ] },

{ at:'C3', t:'거꾸로 선 성당 — 성가대석의 눈',
  x:`매달린 성가대석이 둥글다. 대원 열둘이 원을 그리고 섰다. 가운데 자리 하나가 비었다.<br><br>
    열두 자리가 열두 방위다. 가운데가 진의 눈이다. 노래가 열두 방위에서 나와 가운데로 모인다.<br>
    가운데에 선 것은 노래를 다 받는다. 입이 생긴다. 많이.<br><br>
    성가대석 밑을 지나야 한다. 노래가 일행을 가운데로 부른다.`,
  o:[
    { l:'① 내공을 실어 다섯 숨을 하나로 돌린다.', k:'fix', dc:15, cost:{ qi:20 },
      ok:`다섯이 손을 잡게 했다. 이쪽이 먼저 쉬고 내공을 실어 옆으로 넘겼다. 숨이 손을 타고 돌았다.<br><br>다섯 숨이 하나로 도니 노래가 들어올 틈이 없다. 숨 도는 소리가 귀를 채웠다.<br>성가대석 밑을 손 잡은 채 지났다. 아무도 위를 안 봤다.<br><br>노래가 가운데로 불렀다. 가운데는 끝까지 비어 있었다.`,
      ng:`숨을 돌리는데 하나가 노래를 따라 숨을 쉬었다.<br><br>도는 숨이 그 사람에게서 끊겼다. 노래가 그 틈으로 들어왔다. 그 사람 손등에 입이 하나 생겼다.<br>손을 놓지 않고 끌고 나왔다. 손등 입이 한참 벙긋거리다 닫혔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-11, spirit:-12 } },
    { l:'② 진의 눈 밑에 서서 노래를 흘려보낸다.', k:'gaze', dc:15,
      doom:{ title:'열세 번째 자리', what:'성가대석 한가운데로 끌려 올라갑니다', dc:15, sec:55,
        text:`진의 눈에 서면 진을 쥘 수 있다. 성가대석 밑, 가운데 바로 아래에 섰다.<br><br>노래가 열두 방위에서 모여 이쪽으로 왔다. 쥐려 했다. 너무 많다. 열두 사람 몫이다.<br>목에서 무언가 갈라진다. 손바닥에서도. 이쪽 입이 노래를 받아 부르기 시작했다.<br><br>발이 둥근 천장에서 뜬다. 위로. 가운데 빈 자리가 이쪽을 맞는다.`,
        dieText:`성가대석 가운데 자리가 찼다.<br><br>열세 번째 대원이다. 입이 아직 몇 개 없다. 생기는 중이다.<br>노래가 조금 바뀌었다. 진이 바뀐 것이다. 다음 사람은 바뀐 진을 셈해야 한다.` },
      ok:`진의 눈에 서면 진을 쥘 수 있다. 성가대석 밑, 가운데 바로 아래에 섰다.<br><br>노래가 열두 방위에서 모여 이쪽으로 왔다. 받지 않았다. 숨을 멈추고 한 방위로 흘려보냈다. 사문 쪽으로.<br>노래가 사문으로 빠졌다. 한 방위로 몰린 노래는 원을 못 돈다. 노래가 흐트러졌다.<br><br>그 틈에 넷이 지났다. 이쪽은 맨 나중에 빠져나왔다. 목이 한참 쉬었다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'C4', t:'포자 온실 — 덩이는 진의 눈이다',
  x:`온실 한가운데 덩이. 여덟 화단이 그것을 둘러쌌다. 덩이가 진의 눈이다.<br><br>
    덩이가 뛸 때마다 여덟 칸의 기가 덩이로 모인다. 정원사들이 덩이 쪽으로 기운다. 뿌리 여덟이 칸마다 뻗었다.<br>
    눈을 치려면 진의 기를 먼저 끊어야 한다. 기가 도는 동안은 덩이가 안 다친다.<br><br>
    뿌리를 어느 순서로 끊느냐가 다다.`,
  o:[
    { l:'① 팔문 순서대로 뿌리를 끊는다.', k:'fix', dc:15, wake:1,
      ok:`팔문을 셌다. 생문 칸 뿌리를 먼저 끊으면 덩이가 숨을 못 쉰다. 그다음 휴문, 개문. 사문 칸 뿌리는 마지막.<br><br>순서대로 끊게 했다. 셋째 뿌리에서 덩이가 뛰다 멈췄다. 일곱째에 정원사들이 쓰러졌다. 여덟째, 사문 칸 뿌리가 끊기자 덩이가 쪼그라들었다.<br>칼 다섯이 덩이에 들어갔다. 진의 눈이 꺼졌다.<br><br>진을 놓는 셈으로 진을 허물었다. 놓은 순서를 거꾸로 따라가면 허무는 순서가 나온다. 놓는 법을 알면 허무는 법도 안다. 그 둘이 한 셈이라는 걸 손이 알았다.`,
      ng:`생문 칸 뿌리를 끊었는데 생문이 아니었다. 덩이가 진을 돌려놓았다.<br><br>끊은 건 경문 칸이다. 덩이가 놀라 크게 뛰었다. 노란 가루가 터지듯 피었다.<br>다들 기침하며 물러났다. 이쪽 눈이 부었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-15, spirit:-10 } },
    { l:'② 내공을 실어 진의 기를 덩이 밖으로 돌린다.', k:'break', dc:15, cost:{ qi:22 },
      ok:`덩이 앞에 서서 내공을 끌어올렸다. 덩이로 모이던 기를 손바닥으로 받아 옆으로 흘렸다.<br><br>기가 덩이를 비켜 흘렀다. 덩이가 굶었다. 표면이 쭈글쭈글해졌다.<br>쭈글쭈글한 데로 칼이 들어갔다.`,
      ng:`받는데 기가 너무 많다. 여덟 칸 몫이다.<br><br>손바닥이 타는 것 같다. 코에서 피가 났다. 놓쳤다.<br>기가 덩이로 쏟아졌다. 덩이가 더 커졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-17, mind:-7 } },
    { l:'③ 덩이 뒤 그늘의 맑은 흙을 판다.', k:'luck', dc:14,
      ok:`덩이 뒤, 진의 기가 안 닿는 그늘이 있다. 흙이 까맣고 실이 없다.<br><br>파 보니 물이 스몄다. 맑다. 진이 아무리 모아도 안 닿는 데에 물이 고였다.<br>물통을 채웠다.`,
      ng:`그늘을 파는데 흙 밑에 뿌리가 있었다. 아홉째 뿌리.<br><br>건드리자 뿌리가 손목을 감았다. 덩이 쪽으로 끌었다.<br>칼로 끊었다. 손목에 감긴 자국이 하얗게 남았다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 왜 동쪽이냐고',
  x:`쉬는 자리에서 일행 하나가 바닥에 그은 진도를 들여다본다.<br><br>
    사냥 때마다 이쪽이 사람을 세웠다. 그 사람은 늘 동쪽에 섰다. 왜 동쪽인지 묻는다.<br>
    진은 혼자 놓는 것이 아니다. 돌이 사람이면 돌도 알아야 한다.<br><br>
    설명하려면 밤이 길다.`,
  o:[
    { l:'① 그 사람 자리부터 가르친다.', k:'fix', dc:14,
      ok:`동쪽은 목(木)이다. 자라는 자리. 앞으로 나가는 사람이 선다. 그 사람은 늘 먼저 나갔다.<br><br>그 사람 눈이 밝아졌다. 제 버릇이 자리가 된 걸 알았다.<br>다음 사냥에서 그 사람은 말하기 전에 동쪽에 섰다. 진이 반 박 빨리 섰다.`,
      ng:`설명하는데 오행에서 막혔다. 그 사람이 상생 상극을 헷갈린다.<br><br>밤이 깊었다. 둘 다 졸렸다.<br>다음 사냥에서 그 사람이 서쪽에 섰다. 진이 뒤틀렸다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-9, spirit:-6 } },
    { l:'② 손을 잡고 기를 느끼게 한다.', k:'bond', dc:14,
      ok:`그 사람 손을 잡고 아주 조금 기를 흘렸다. 동쪽에 섰을 때 손바닥에 오는 것.<br><br>그 사람이 눈을 감았다. 따뜻하다고 했다.<br>말보다 손이 빨랐다. 다음 사냥에서 그 사람은 따뜻한 쪽을 찾아 섰다.`,
      ng:`기를 흘렸는데 그 사람이 놀라 손을 뺐다.<br><br>찌르르했다고 한다. 겁을 먹었다.<br>그 뒤로 이쪽 손을 안 잡으려 했다.`,
      win:{ exp:15, spirit:5 }, lose:{ mind:-8, spirit:-7 } }
  ] },

{ at:'C', t:'사냥 뒤 — 휴문의 불',
  x:`잡은 것의 살을 떼어 냈다. 구워야 먹는다. 불을 피워야 한다.<br><br>
    불을 피우면 연기가 나고, 연기는 멀리 간다. 여기 것들이 연기를 따라온다.<br>
    쉬는 진은 휴문을 향해 놓는다. 불도 그렇다.<br><br>
    휴문이 어디인지 셈해야 한다.`,
  o:[
    { l:'① 휴문 방위에 불을 놓는다.', k:'fix', dc:14,
      ok:`방위를 셈했다. 휴문은 북쪽 벽 밑이다. 거기에 불을 지폈다.<br><br>연기가 북쪽 벽을 타고 올라가 틈으로 빠졌다. 바깥으로. 안쪽으로는 안 퍼졌다.<br>고기를 구웠다. 다섯이 배불리 먹었다. 아무것도 안 왔다.`,
      ng:`휴문이라 잡은 데가 경문이었다. 연기가 안쪽으로 퍼졌다.<br><br>안쪽에서 무언가 놀라 뛰어나왔다. 굽던 고기를 걷어차고 갔다.<br>쫓느라 불이 꺼졌다. 반쯤 익은 고기를 먹었다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-10, mind:-7 } },
    { l:'② 불 없이 소금에 절인다.', k:'heal', dc:14,
      ok:`소금으로 고기를 문질러 두었다. 불은 안 피웠다.<br><br>짜다. 그래도 먹을 만하다. 연기가 없으니 조용하다.<br>다섯이 조금씩 씹었다.`,
      ng:`소금이 모자랐다. 고기 반이 하얗게 덮였다.<br><br>덮인 쪽을 잘라 버렸다. 남은 것은 손바닥만 하다.<br>다섯이 나눠 먹었다. 배가 고팠다.`,
      win:{ exp:14, hp:7 }, lose:{ hp:-9, mind:-6 } },
    { l:'③ 연기 길을 따라 바깥 틈을 찾는다.', k:'sense', dc:14,
      ok:`작은 불을 붙여 연기가 어디로 가는지 봤다. 천장 틈 하나로 빨려 든다.<br><br>틈 너머에 바깥이 있다. 틈 가장자리에 빗물이 고였다. 맑다.<br>물을 받아 마셨다.`,
      ng:`연기를 따라가는데 연기가 이쪽을 따라왔다. 틈이 아니라 이쪽 숨으로 빨려 든다.<br><br>기침이 터졌다. 눈이 맵다.<br>불을 껐다. 한참 눈물이 났다.`,
      win:{ exp:15, dream:2, item:'맑은 물' }, lose:{ hp:-8, mind:-8 } }
  ] },

{ at:'C', t:'어둠 — 돌도 기도 없이',
  x:`돌이 다 떨어졌다. 내공도 바닥이다. 숨만 남았다.<br><br>
    앞이 넓은 방이다. 무언가 기다린다. 진 없이 들어가면 다섯이 다 흩어진다.<br>
    진은 돌로 놓고, 기로 잇는다. 둘 다 없다.<br><br>
    진법가에게서 돌과 기를 빼면 무엇이 남는지, 지금 알아야 한다.`,
  o:[
    { l:'① 서는 자리만으로 진을 놓는다.', k:'fix', dc:15, wake:1,
      ok:`다섯을 세웠다. 돌 없이, 기 없이. 서는 자리만. 이쪽 손짓으로.<br><br>그런데 섰다. 다들 몇 번이나 이쪽이 세운 자리에 섰던 사람들이다. 손짓만으로 몸이 제자리를 찾았다. 서로 거리를 재지 않아도 맞았다.<br>방을 지나는 동안 무언가 둘레를 맴돌다 들어오지 못했다. 진은 섰다.<br><br>진은 돌에 있지 않았다. 기에도 있지 않았다. 사람들 몸에 배어 있었다. 놓아 준 자리를 몸이 기억하면 진은 저절로 선다. 남은 것은 셈이었다. 셈은 안 떨어진다.`,
      ng:`손짓으로 세웠는데 어두워서 손짓이 안 보인다.<br><br>둘이 엉뚱한 데 섰다. 진이 안 섰다. 무언가 그 빈 데로 들어왔다.<br>다들 흩어져 싸웠다. 이쪽이 제일 많이 다쳤다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-16, mind:-7 } },
    { l:'② 늘 하던 대로 밖에 서서 고친다.', k:'steady', dc:14,
      ok:`이쪽은 진 밖에 섰다. 일행만 세웠다. 밖에서 보며 틀어지는 데를 바로 고쳤다.<br><br>무언가 다가왔다. 진 밖에 선 이쪽에게로. 진 밖은 진이 안 지킨다.<br>피했다. 한 번 할퀴었다. 그래도 일행은 무사했다.`,
      ng:`밖에 서 있다가 그것과 눈이 마주쳤다.<br><br>그것이 진을 돌아 이쪽으로 왔다. 진 밖에 있는 것은 진이 안 지킨다.<br>어깨에 할퀸 자국이 셋 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-15, spirit:-6 } }
  ] },

{ at:'C', t:'나가는 길 — 개문',
  x:`나가는 문이 셋이다. 하나만 바깥이다.<br><br>
    팔문 가운데 개문(開門)은 여는 문이다. 바깥으로 열린다.<br>
    셋 다 생김새가 같다. 다들 지쳐서 아무 문이나 열고 싶어 한다.<br><br>
    마지막 셈이다.`,
  o:[
    { l:'① 처음 잡은 방위에서 거꾸로 셈한다.', k:'fix', dc:14,
      ok:`들어올 때 잡은 북을 떠올렸다. 숨이 들어오던 쪽. 거기서 거꾸로 셈했다. 들어온 문의 맞은편이 개문이다.<br><br>가운데 문이었다. 열었다. 찬 바람이 들어왔다. 바깥 공기다. 숨이 끝까지 들어간다.<br>다섯이 나갔다. 뒤의 두 문 안에서 무언가 문을 긁었다.`,
      ng:`거꾸로 셈하다 하나를 빼먹었다. 성당에서 뒤집은 셈.<br><br>왼쪽 문을 열었다. 안쪽으로 이어지는 복도다. 다시 닫았다. 닫는 사이 무언가 손가락을 끼웠다.<br>문을 세게 닫았다. 손가락 하나가 문틈에 남았다. 이쪽 것은 아니다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-8, spirit:-10 } },
    { l:'② 내공을 실어 문마다 기를 짚는다.', k:'gaze', dc:14, cost:{ qi:15 },
      ok:`남은 내공을 다 모아 손바닥을 문마다 댔다. 두 문은 손바닥이 빨려 든다. 하나만 밀어낸다. 바깥 바람이 밀고 있다.<br><br>그 문을 열었다. 바깥이다.<br>내공이 바닥났다. 나와서 한참 주저앉아 있었다.`,
      ng:`손바닥을 대는데 셋 다 빨려 든다. 내공이 바닥이라 셋 다 똑같이 느껴진다.<br><br>아무거나 열었다. 안쪽 복도다. 닫고 다른 문을 열었다. 그사이 무언가 뒤꿈치를 긁었다.<br>나오다 문틀에 어깨를 찧었다. 내공 없는 몸이 무겁다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-9, mind:-8 } }
  ] }

]);
